class PendingKind(StrEnum):
    CHALLENGE = "challenge"
    CRAFTING = "crafting"
    NPC = "npc"
    OBSERVATION = "observation"
    SOURCE_SELECTION = "source_selection"
    COLLECTION = "collection"
    TRAP = "trap"
    SEARCH = "search"
    HIDE = "hide"
    FIXTURE = "fixture"
    ZONE_OPTION = "zone_option"


class PendingStage(StrEnum):
    DECISION = "decision"
    ROLL = "roll"
    BREAKAGE = "breakage"
    HAZARD_SAVE = "hazard_save"


