    @property
    def current_zone(self) -> ExplorationZone:
        return next(zone for zone in self.state.zones if zone.id == self.state.party_position.zone_id)

    def _party_actor_for_option(self, option: ExplorationOption) -> Actor | None:
        actor_id = option.assigned_actor_id or option.required_party_actor_id
        if actor_id is None:
            return None
        return next(
            (
                actor
                for actor in self.exploration.actors
                if str(actor.id) == actor_id
                and actor.faction == Faction.ALLY
                and not actor.is_defeated()
            ),
            None,
        )

    def _zone_option_is_available(self, option: ExplorationOption) -> bool:
        return (
            option.required_party_actor_id is None
            or self._party_actor_for_option(option) is not None
        )

    def _available_zone_options(self) -> tuple[ExplorationOption, ...]:
        return tuple(
            option
            for option in self.current_zone.options
            if self._zone_option_is_available(option)
        )

    @property
    def active_point(self) -> ExplorationPoint | None:
        if not self.active_point_id:
            return None
        return next((point for point in self.state.points if point.id == self.active_point_id), None)

    @property
    def active_merchant(self) -> MerchantState | None:
        point = self.active_point
        if point is None or point.merchant_id is None:
            return None
        return next(
            (
                merchant
                for merchant in self.state.merchants
                if merchant.id == point.merchant_id
            ),
            None,
        )

    def configure_custom_party(self, actors: tuple[Actor, ...]) -> None:
        if not 1 <= len(actors) <= 5:
            raise ValueError("Wybierz od 1 do 5 postaci.")
        if len({actor.id for actor in actors}) != len(actors):
            raise ValueError("Każdą postać można wybrać tylko raz.")
        if any(actor.faction != Faction.ALLY for actor in actors):
            raise ValueError("Drużyna może zawierać wyłącznie bohaterów.")
        self.custom_party = tuple(actors)
        self.reset()

    def configure_scenario(self, scenario_path: str | Path) -> None:
        """Switch to a validated scenario while preserving runtime adapters."""
        candidate = Path(scenario_path)
        build_exploration_from_scenario(load_scenario(candidate))
        self.scenario_path = candidate
        self.reset()

    def state_payload(self) -> dict[str, object]:
        if self.ui_flow_stage not in {
            UiFlowStage.SHORT_REST,
            UiFlowStage.GAME_OVER,
            UiFlowStage.SCENARIO_COMPLETE,
        }:
            if self.pending_npc_transition is None:
                self._refresh_pending_encounter()
        self._expire_invalid_combat_effects()
        if self.combat_state is not None:
            self.active_combat_effects = synchronize_dynamic_flaw_effects(
                self.combat_state.actors,
                self.combat_state.condition_states,
                self.active_combat_effects,
            )
        active_challenge = self.active_challenge if self.ui_flow_stage == UiFlowStage.LOCATION_ACTIVE else None
        current_zone_points = self.current_zone_points() if self.ui_flow_stage == UiFlowStage.LOCATION_ACTIVE else ()
        scene_status = _scene_status_payload(self.state)
        scene_status.append({"label": "Czas scenariusza", "value": _duration_minutes_label(self.state.elapsed_minutes)})
        clock_payload = _scenario_clock_payload(
            self.state.clock_policy.start_hour,
            self.state.elapsed_minutes,
        )
        scene_status.append(
            {"label": "Pora dnia", "value": str(clock_payload["label"])}
        )
        scene_status.append(
            {
                "label": "Oświetlenie",
                "value": _light_level_label(self.current_zone.ambient_light),
            }
        )
        fixture_names = {
            (zone.id, fixture.id): fixture.name
            for zone in self.state.zones
            for fixture in zone.fixtures
        }
        for fixture_state in self.state.fixture_states:
            scene_status.append(
                {
                    "label": fixture_names.get(
                        (fixture_state.zone_id, fixture_state.fixture_id),
                        fixture_state.fixture_id,
                    ),
                    "value": fixture_state.condition,
                }
            )
        actor_names = {str(actor.id): actor.name for actor in self.exploration.actors}
        for condition in self.state.condition_states:
            condition_label = (
                "Powalony"
                if condition.condition == CombatCondition.PRONE
                else condition.condition.value
            )
            scene_status.append(
                {
                    "label": f"Stan: {actor_names.get(condition.actor_id, condition.actor_id)}",
                    "value": condition_label,
                }
            )
        trap_status_labels = {
            ExplorationTrapStatus.REVEALED: "wykryta — aktywna",
            ExplorationTrapStatus.DISARMED: "rozbrojona",
            ExplorationTrapStatus.BYPASSED: "bezpiecznie ominięta",
            ExplorationTrapStatus.TRIGGERED: "uruchomiona — rozstrzygnięta",
        }
        for trap in self.state.traps:
            trap_state = trap_state_for(self.state, trap.id)
            if trap_state.status == ExplorationTrapStatus.HIDDEN:
                continue
            trap_status = trap_status_labels[trap_state.status]
            if (
                trap_state.status == ExplorationTrapStatus.TRIGGERED
                and self.pending is not None
                and self.pending.trap is not None
                and self.pending.trap.id == trap.id
                and self.pending.stage == PendingStage.HAZARD_SAVE
            ):
                trap_status = "uruchomiona — oczekuje na rzut obronny"
            scene_status.append(
                {
                    "label": f"Pułapka: {trap.name}",
                    "value": trap_status,
                }
            )
        for edge in self.state.encounter_edges:
            if edge.consumed:
                continue
            scene_status.append(
                {
                    "label": "Przewaga na inicjatywę",
                    "value": f"{actor_names.get(edge.beneficiary_actor_id, edge.beneficiary_actor_id)} — {edge.label}",
                }
            )
        if self.pending_encounter is not None:
            scene_status.append({"label": "Encounter", "value": self.pending_encounter.name})
        preview_zone = self._preview_zone()
        objectives = objective_status_after_flags(
            self.exploration.objectives,
            self.state.flags,
        )
        continuation = self.scenario_continuation_flow.availability_payload(
            self.exploration.continuation,
            flags=self.state.flags,
            current_zone_id=self.current_zone.id,
        )
        if continuation is not None:
            travel_payload = continuation.get("travel")
            if isinstance(travel_payload, dict):
                terrain = travel_payload.get("terrain")
                natural_explorer_actor_ids = [
                    str(actor.id)
                    for actor in self.exploration.actors
                    if actor.faction == Faction.ALLY
                    and terrain is not None
                    and natural_explorer_terrain(actor) == terrain
                ]
                travel_payload["natural_explorer_actor_ids"] = (
                    natural_explorer_actor_ids
                )
                travel_payload["navigation_automatic"] = bool(
                    natural_explorer_actor_ids
                    and travel_payload.get("navigation_dc") is not None
                )
        collected_source_ids = {item.source_id for item in self.state.source_collections}
        payload = UiSessionView(
            scenario={"id": self.exploration.scenario_id, "name": self.exploration.scenario_name},
            session_log={
                "session_id": self.observer.session_id,
                "path": str(self.observer.path),
            },
            snapshot=self._snapshot_payload(),
            flow={
                "stage": self.ui_flow_stage.value,
                "can_start": self.ui_flow_stage == UiFlowStage.READY_TO_START,
                "preview_zone": _zone_payload(preview_zone, self._scenario_asset_root(), self.state) if preview_zone else None,
                "available_locations": [_zone_payload(zone, self._scenario_asset_root(), self.state) for zone in self._scene_location_zones()],
                "interaction_result": self.interaction_result,
                "objectives": [
                    {
                        "id": objective.id,
                        "name": objective.name,
                        "description": objective.description,
                        "status": objective.status.value,
                        "milestones": [
                            {
                                "label": milestone.label,
                                "completed": (
                                    scene_flag(
                                        self.state.flags,
                                        milestone.flag_key,
                                        None,
                                    )
                                    == milestone.flag_value
                                ),
                            }
                            for milestone in objective.milestones
                        ],
                    }
                    for objective in objectives
                ],
                "zone_options": [
                    _zone_option_payload(
                        option,
                        completed=_zone_option_is_completed(
                            option,
                            self.state.flags,
                        ),
                        assigned_actor=self._party_actor_for_option(option),
                    )
                    for option in self._available_zone_options()
                ],
                "board_interaction": self._board_interaction_payload(),
                "continuation": continuation,
                "scenario_handoff": self.scenario_handoff,
                "encounter_retry": self._encounter_retry_payload(),
                "clock": clock_payload,
                "visibility": [
                    exploration_visibility(
                        actor,
                        ambient_light=self.current_zone.ambient_light,
                        distance_feet=5,
                        party=self.exploration.actors,
                    ).as_payload()
                    | {"actor_id": str(actor.id), "actor_name": actor.name}
                    for actor in self.exploration.actors
                    if actor.faction == Faction.ALLY and not actor.is_defeated()
                ],
                "awareness": {
                    "allows_hiding": self.current_zone.allows_hiding,
                    "search_available": (
                        self.current_zone.search_dc is not None
                        and self.current_zone.id
                        not in self.state.exhausted_search_zones
                        and self.pending is None
                        and self.pending_encounter is None
                    ),
                    "search_minutes": self.current_zone.search_minutes,
                    "hidden_actor_states": [
                        {
                            "actor_id": item.actor_id,
                            "zone_id": item.zone_id,
                            "natural_roll": item.natural_roll,
                            "stealth_total": item.stealth_total,
                        }
                        for item in self.state.hidden_actor_states
                        if item.zone_id == self.current_zone.id
                    ],
                },
                "fixtures": self._current_fixture_payloads(),
            },
            spell_preparation=self._spell_preparation_payload(),
            short_rest=self._short_rest_payload(),
            long_rest=self._long_rest_payload(),
            current_zone=_zone_payload(self.current_zone, self._scenario_asset_root()),
            available_zones=[_zone_payload(zone, self._scenario_asset_root()) for zone in visible_exploration_zones(self.state.zones) if zone_is_ui_available(self.state, zone)],
            visible_environment=[_environment_entry_payload(entry) for entry in self.exploration.environment if entry.visibility == SetupVisibility.VISIBLE],
            travel_options=[_zone_payload(zone, self._scenario_asset_root()) for zone in self.travel_options()],
            visible_points=[_point_payload(point, _npc_state_for_point(self.state, point), self.state.flags, self.exploration.flows, self.exploration.actors) for point in visible_exploration_points(self.state.points)],
            current_zone_points=[_point_payload(point, _npc_state_for_point(self.state, point), self.state.flags, self.exploration.flows, self.exploration.actors) for point in current_zone_points],
            active_challenge=(
                _challenge_payload(
                    self.state,
                    active_challenge,
                    self.exploration.actors,
                    self.exploration.flows,
                    self.exploration_interaction_flow,
                )
                if active_challenge
                else None
            ),
            active_point=(
                _point_payload(self.active_point, _npc_state_for_point(self.state, self.active_point), self.state.flags, self.exploration.flows, self.exploration.actors)
                if self.active_point
                else None
            ),
            trade=self._trade_payload(),
            downtime=self._downtime_payload(),
            resources=[
                *[_resource_payload(resource) for resource in self.state.resources if resource.id in self.state.inventory_resource_ids],
                *[
                    _temporary_item_payload(item)
                    for item in self.state.temporary_items
                    if item.available
                    and f"temporary:{item.id}" not in collected_source_ids
                ],
            ],
            discovered_sources=self._discovered_sources_payload(),
            actors=_exploration_actor_payloads(
                self.exploration.actors,
                self.state.condition_states,
            ),
            active_effects=[
                *[effect.as_payload() for effect in self.active_combat_effects],
                *[
                    self._timed_magic_effect_view(effect)
                    for effect in self.state.magic_effects
                ],
            ],
            scene_status=scene_status,
            flags=[{"key": key, "value": value} for key, value in self.state.flags.values],
            messages=[message.as_payload() for message in self.messages],
            conversation=self._conversation_payload(),
            pending=self._pending_payload(),
            pending_npc_transition=(
                self.pending_npc_transition.as_payload()
                if self.pending_npc_transition is not None
                else None
            ),
            selected_lead_actor_id=self.selected_lead_actor_id,
            selected_helper_actor_id=self.selected_helper_actor_id,
            allowed_mechanics=[tool.as_payload() for tool in MECHANIC_TOOLS.values()],
            pending_encounter=self._pending_encounter_payload(),
            exploration_setup=self.exploration_setup_flow.as_payload() if self.exploration_setup_flow else None,
            encounter_setup=self.encounter_setup_flow.as_payload() if self.encounter_setup_flow else None,
            encounter_stealth=self._precombat_stealth_payload(),
            encounter_initiative=(
                self.encounter_initiative_flow.as_payload() if self.encounter_initiative_flow else None
            ),
            combat=_combat_payload(
                state=self.combat_state,
                encounter=self._active_encounter(),
                selected_movement_path=self.selected_combat_movement_path,
                pending_enemy_turn_intent=self.pending_enemy_turn_intent,
                pending_enemy_turn_result=self.pending_enemy_turn_result,
                pending_enemy_turn_ack_result=self.pending_enemy_turn_ack_result,
                pending_enemy_saving_throw=self.pending_enemy_saving_throw,
                pending_encounter_result=self.pending_encounter_result,
                pending_player_attack=self.pending_player_attack,
                pending_player_healing=self.pending_player_healing,
                pending_area_spell=self.pending_area_spell,
                pending_summon=self.pending_summon,
                pending_magic_movement=self.pending_magic_movement,
                pending_spell_debuff=self.pending_spell_debuff,
                pending_spell_dispel=self.pending_spell_dispel,
                pending_multi_target_damage_spell=self.pending_multi_target_damage_spell,
                pending_combat_context_menu=self.pending_combat_context_menu,
                pending_combat_interaction=self.pending_combat_interaction,
                pending_combat_help=self.pending_combat_help,
                pending_combat_skill_check=self.pending_combat_skill_check,
                pending_combat_shove=self.pending_combat_shove,
                pending_combat_grapple=self.pending_combat_grapple,
                pending_concentration_action=self.pending_concentration_action,
                pending_concentration_check=self.pending_concentration_check,
                pending_combat_ready=self.pending_combat_ready,
                pending_opportunity_movement=self.pending_opportunity_movement,
                pending_reaction_window=self.pending_reaction_window,
                pending_enemy_opportunity_attack=self.pending_enemy_opportunity_attack,
                pending_ready_attack=self.pending_ready_attack,
                active_combat_effects=self.active_combat_effects,
                selected_attack_source_ids=self.selected_attack_source_ids,
                selected_healing_source_ids=self.selected_healing_source_ids,
                targeting_attack_source_id=self.combat_targeting_attack_source_id,
                targeting_healing_source_id=self.combat_targeting_healing_source_id,
                targeting_class_feature_action_id=(
                    self.combat_targeting_class_feature_action_id
                ),
                selected_class_feature_target_id=(
                    self.combat_selected_class_feature_target_id
                ),
                selected_class_feature_target_ids=(
                    self.combat_selected_class_feature_target_ids
                ),
                aux_targeting_mode=self.combat_aux_targeting_mode,
                stabilization_method=self.combat_stabilization_method,
                stabilization_target_id=self.combat_stabilization_target_id,
                pending_physical_feature_action_id=(
                    self.pending_physical_feature_action_id
                ),
            )
            if self.combat_state
            else None,
            board=self._board_payload(),
            board_selection=self._board_selection_payload(),
            required_rolls=self.required_rolls_payload(),
            playground=(
                {
                    "enabled": True,
                    "config": self.playground_trial_config.as_payload(),
                    "trial_active": bool(
                        self.pending_encounter is not None
                        or self.encounter_setup_flow is not None
                        or self.combat_state is not None
                    ),
                    "modules": [
                        {"id": "combat_arena", "label": "Walka i pozycjonowanie"},
                        {"id": "spell_lab", "label": "Czary, obszary i stany"},
                        {"id": "exploration_course", "label": "Eksploracja i przedmioty"},
                        {"id": "social_lab", "label": "Rozmowy i testy społeczne"},
                        {"id": "rest_station", "label": "Odpoczynek i zasoby"},
                    ],
                    "audit": load_playground_audit_registry().as_payload(),
                }
                if self.exploration.scenario_id == "mechanics_playground"
                else None
            ),
            exploration_card=self._exploration_card_payload(),
        ).as_payload()
        combat_payload = payload.get("combat")
        if isinstance(combat_payload, dict) and self.combat_state is not None:
            combat_payload["card_reminders"] = self._combat_card_reminders_payload()
        return payload

    @staticmethod
    def _physical_card_resource_note(actor: Actor, source_id: str) -> str | None:
        """Describe the finite resource behind a currently legal physical card."""

        resource_ids = {
            resource_id
            for feature in actor.features
            if source_id in feature.action_ids or source_id == feature.feature_id
            for resource_id in feature.resource_ids
        }
        shared_feature_resource = {
            "cutting_words": "bardic_inspiration_uses",
            "preserve_life": "channel_divinity_uses",
        }.get(source_id)
        if shared_feature_resource is not None:
            resource_ids.add(shared_feature_resource)
        for profile in actor.spell_access:
            resource_ids.update(
                resource_id
                for spell_id, resource_id in profile.resource_ids_by_spell
                if spell_id == source_id
            )
        pools = [
            pool
            for resource_id in sorted(resource_ids)
            if (pool := actor_resource_pool(actor, resource_id)) is not None
        ]
        if pools:
            return " · ".join(
                f"{pool.label}: {pool.current}/{pool.maximum}" for pool in pools
            )

        spell = next((item for item in actor.spells if item.id == source_id), None)
        if spell is None or spell.level <= 0:
            return None
        slots = tuple(slot for slot in actor.spell_slots if slot.level >= spell.level)
        if not slots:
            return None
        return "Komórki: " + " · ".join(
            f"{slot.level}. {slot.remaining}/{slot.maximum}" for slot in slots
        )

    def _combat_card_reminders_payload(self) -> list[dict[str, object]]:
        """List only cards that the scanner can legally accept at this checkpoint."""

        if self.combat_state is None or self.combat_state.status != CombatStatus.ACTIVE:
            return []
        actors_by_id = {str(actor.id): actor for actor in self.combat_state.actors}
        reminders = []
        window = self.pending_reaction_window
        if window is not None:
            option = window.current_option
            owner = actors_by_id.get(option.reactor_actor_id)
            if owner is not None:
                reminder = reaction_card_reminder(
                    source_id=option.effect_id,
                    owner_actor_id=str(owner.id),
                    owner_actor_name=owner.name,
                    trigger_event=option.trigger_event,
                    label=option.label,
                )
                if reminder is not None:
                    reminders.append(reminder)

        actor = combat_current_actor(self.combat_state)
        if actor.faction == Faction.ALLY and not actor.is_defeated():
            options = self._combat_context_options(actor, actor.position)
            available_action_ids: set[str] = set()
            labels_by_action_id: dict[str, str] = {}
            for option in options:
                action_id = option.source_id or option.action_id
                if action_id is None or option.provider not in {
                    "attack_source",
                    "healing_source",
                    "combat_action",
                    "class_feature",
                }:
                    continue
                available_action_ids.add(action_id)
                option_label = option.label.rsplit(": ", 1)[-1].strip()
                labels_by_action_id.setdefault(
                    action_id,
                    option_label or player_label(action_id),
                )
            reminders.extend(
                action_selection_card_reminders(
                    owner_actor_id=str(actor.id),
                    owner_actor_name=actor.name,
                    available_action_ids=available_action_ids,
                    labels_by_action_id=labels_by_action_id,
                )
            )
        payloads: list[dict[str, object]] = []
        for reminder in reminders:
            payload: dict[str, object] = reminder.as_payload()
            owner = actors_by_id.get(reminder.owner_actor_id)
            if owner is not None:
                resource_note = self._physical_card_resource_note(
                    owner,
                    reminder.source_id,
                )
                if resource_note is not None:
                    payload["resource_note"] = resource_note
            payloads.append(payload)
        return payloads

    def _pending_payload(self) -> dict[str, object] | None:
        if self.pending is None:
            return None
        payload = self.pending.as_payload()
        if (
            self.pending.stage == PendingStage.HAZARD_SAVE
            and self.pending.hazard is not None
            and _hazard_is_fall(self.pending.hazard)
        ):
            payload["feather_fall_options"] = [
                {
                    "actor_id": str(actor.id),
                    "actor_name": actor.name,
                    "spell_id": "feather_fall",
                    "spell_name": "Powolne opadanie",
                }
                for actor in self.exploration.actors
                if (
                    (validation := actor_spell_cast_validation(
                        actor,
                        "feather_fall",
                    ))
                    is not None
                    and validation.valid
                )
            ]
        return payload

    def _discovered_sources_payload(self) -> list[dict[str, object]]:
        registry = build_crafting_source_registry(self.state, self.exploration.actors)
        property_label = self.exploration.crafting_policy.property_label
        collections_by_source: dict[str, list[SceneSourceCollection]] = {}
        for collection in self.state.source_collections:
            collections_by_source.setdefault(collection.source_id, []).append(collection)
        result: list[dict[str, object]] = []
        for discovery in self.state.source_discoveries:
            if discovery.zone_id != self.current_zone.id:
                continue
            source = registry.source_by_id(discovery.source_id)
            if source is None:
                continue
            collections = collections_by_source.get(source.id, [])
            result.append(
                {
                    "id": source.id,
                    "label": source.label,
                    "kind": source.kind.value,
                    "quantity": source.quantity,
                    "condition": source.condition,
                    "properties": [
                        {"id": item, "label": property_label(item)}
                        for item in source.properties
                    ],
                    "matched_properties": [
                        {"id": item, "label": property_label(item)}
                        for item in discovery.matched_properties
                    ],
                    "purpose": discovery.purpose,
                    "requested_as": discovery.requested_as,
                    "semantic_substitution": discovery.semantic_substitution,
                    "available": source.usable,
                    "portable": source.portable,
                    "inventory": False,
                    "collections": [
                        {
                            "quantity": item.quantity,
                            "destination": item.destination,
                            "owner_actor_id": item.owner_actor_id,
                        }
                        for item in collections
                    ],
                }
            )
        return result

    @property
    def snapshot_path(self) -> Path:
        return self.save_dir / f"{self.exploration.scenario_id}.snapshot.json"

    @property
    def encounter_checkpoint_path(self) -> Path:
        return self.save_dir / (
            f"{self.exploration.scenario_id}.encounter-checkpoint.json"
        )

    def create_snapshot(self) -> SessionSnapshot:
        blocker = self._snapshot_blocker()
        if blocker is not None:
            raise ValueError(blocker)
        return SessionSnapshot(
            scenario_id=self.exploration.scenario_id,
            scenario_schema=self.exploration.content_header.schema,
            scenario_schema_version=self.exploration.content_header.schema_version,
            ruleset_id=self.exploration.content_header.ruleset_id,
            source_pack_ids=self.exploration.content_header.source_pack_ids,
            ui_stage=self.ui_flow_stage.value,
            actors=self.exploration.actors,
            exploration_state=self.state,
            active_effects=self.active_combat_effects,
            pending_encounter=self.pending_encounter,
            pending_npc_transition=(
                self.pending_npc_transition.pending
                if self.pending_npc_transition is not None
                else None
            ),
            combat_state=self.combat_state,
            resolved_encounter_trigger_ids=tuple(sorted(self.resolved_encounter_trigger_ids)),
            selected_attack_source_ids=tuple(sorted(self.selected_attack_source_ids.items())),
            selected_healing_source_ids=tuple(sorted(self.selected_healing_source_ids.items())),
            selected_lead_actor_id=self.selected_lead_actor_id,
            selected_helper_actor_id=self.selected_helper_actor_id,
            active_point_id=self.active_point_id,
            preview_zone_id=self.preview_zone_id,
            interaction_result=self.interaction_result,
            conversation_entries=tuple(self.conversation_entries),
        )

    def save_snapshot(self) -> dict[str, object]:
        snapshot = self.create_snapshot()
        write_snapshot(self.snapshot_path, snapshot)
        self._record(
            "ui_snapshot_saved",
            {"path": str(self.snapshot_path), "schema_version": SNAPSHOT_SCHEMA_VERSION},
        )
        self._add_message("Gra zapisana", f"Zapisano stan scenariusza w wersji {SNAPSHOT_SCHEMA_VERSION}.")
        return self.state_payload()

    def load_snapshot(self) -> dict[str, object]:
        return self._load_snapshot_from_path(self.snapshot_path)

    def _load_snapshot_from_path(
        self,
        snapshot_path: Path,
        *,
        expected_encounter_trigger_id: str | None = None,
    ) -> dict[str, object]:
        base_exploration = build_exploration_from_scenario(load_scenario(self.scenario_path))
        base_state = ExplorationState(
            base_exploration.zones,
            base_exploration.points,
            base_exploration.party_position,
            SceneFlags(),
            challenges=base_exploration.challenges,
            resources=base_exploration.resources,
            inventory_resource_ids=base_exploration.initial_resource_ids,
            traps=base_exploration.traps,
            merchants=base_exploration.merchants,
            clock_policy=base_exploration.clock_policy,
        )
        snapshot = read_snapshot(snapshot_path, base_state=base_state)
        if expected_encounter_trigger_id is not None:
            checkpoint_encounter = snapshot.pending_encounter
            if (
                checkpoint_encounter is None
                or checkpoint_encounter.trigger_id
                != expected_encounter_trigger_id
                or snapshot.combat_state is None
                or snapshot.combat_state.status != CombatStatus.ACTIVE
            ):
                raise ValueError(
                    "Checkpoint nie odpowiada encounterowi zakończonemu porażką."
                )
        if snapshot.scenario_id != base_exploration.scenario_id:
            raise ValueError(
                f"Zapis dotyczy scenariusza {snapshot.scenario_id}, a nie {base_exploration.scenario_id}."
            )
        expected_content = base_exploration.content_header
        if (
            snapshot.scenario_schema != expected_content.schema
            or snapshot.scenario_schema_version != expected_content.schema_version
            or snapshot.ruleset_id != expected_content.ruleset_id
        ):
            raise ValueError(
                "Zapis używa innego kontraktu contentu lub rulesetu niż aktualny scenariusz."
            )
        unknown_source_packs = set(snapshot.source_pack_ids) - set(
            expected_content.source_pack_ids
        )
        if unknown_source_packs:
            raise ValueError(
                "Zapis wymaga niedostępnych source packów: "
                + ", ".join(sorted(unknown_source_packs))
                + "."
            )
        expected_actor_ids = {str(actor.id) for actor in base_exploration.actors}
        restored_actor_ids = {str(actor.id) for actor in snapshot.actors}
        restored_custom_party: tuple[Actor, ...] = ()
        if expected_actor_ids != restored_actor_ids:
            custom_party = tuple(
                actor
                for actor in snapshot.actors
                if actor.faction == Faction.ALLY
            )
            authored_non_allies = {
                str(actor.id)
                for actor in base_exploration.actors
                if actor.faction != Faction.ALLY
            }
            restored_non_allies = {
                str(actor.id)
                for actor in snapshot.actors
                if actor.faction != Faction.ALLY
            }
            if (
                not 1 <= len(custom_party) <= 5
                or authored_non_allies != restored_non_allies
            ):
                raise ValueError(
                    "Lista aktorów zapisu nie odpowiada aktualnej wersji scenariusza."
                )
            base_exploration = _exploration_with_custom_party(
                base_exploration,
                custom_party,
            )
            restored_custom_party = custom_party
            expected_actor_ids = {
                str(actor.id) for actor in base_exploration.actors
            }
            if expected_actor_ids != restored_actor_ids:
                raise ValueError(
                    "Customowa drużyna zapisu nie pasuje do scenariusza."
                )
        stage = UiFlowStage(snapshot.ui_stage)
        known_trigger_by_id = {trigger.id: trigger for trigger in base_exploration.encounter_triggers}
        if set(snapshot.resolved_encounter_trigger_ids) - set(known_trigger_by_id):
            raise ValueError("Zapis zawiera nieznany trigger rozstrzygniętego encountera.")
        if snapshot.pending_encounter is not None:
            trigger = known_trigger_by_id.get(snapshot.pending_encounter.trigger_id)
            if trigger is None or trigger.encounter_scenario != snapshot.pending_encounter.encounter_scenario:
                raise ValueError("Oczekujący encounter nie odpowiada aktualnej wersji scenariusza.")
        point_ids = {point.id for point in base_exploration.points}
        zone_ids = {zone.id for zone in base_exploration.zones}
        if snapshot.active_point_id and snapshot.active_point_id not in point_ids:
            raise ValueError("Zapis odwołuje się do nieznanego aktywnego punktu.")
        if snapshot.preview_zone_id and snapshot.preview_zone_id not in zone_ids:
            raise ValueError("Zapis odwołuje się do nieznanej lokacji podglądu.")
        selection_actor_ids = restored_actor_ids | (
            {str(actor.id) for actor in snapshot.combat_state.actors} if snapshot.combat_state is not None else set()
        )
        selected_actor_ids = {
            snapshot.selected_lead_actor_id,
            snapshot.selected_helper_actor_id or "",
            *(actor_id for actor_id, _source_id in snapshot.selected_attack_source_ids),
            *(actor_id for actor_id, _source_id in snapshot.selected_healing_source_ids),
        } - {""}
        if selected_actor_ids - selection_actor_ids:
            raise ValueError("Zapis zawiera wybór dla nieznanego aktora.")
        effect_actor_ids = {
            actor_id
            for effect in snapshot.active_effects
            for actor_id in (effect.actor_id, effect.source_actor_id, effect.target_actor_id)
            if actor_id
        }
        if effect_actor_ids - selection_actor_ids:
            raise ValueError("Aktywny efekt zapisu odwołuje się do nieznanego aktora.")
        exploration_condition_actor_ids = {
            condition.actor_id for condition in snapshot.exploration_state.condition_states
        }
        if exploration_condition_actor_ids - restored_actor_ids:
            raise ValueError("Stan eksploracyjny zapisu odwołuje się do nieznanego aktora.")
        restored_initiative_flow = None
        if snapshot.combat_state is not None:
            if snapshot.pending_encounter is None:
                raise ValueError("Zapis aktywnej walki nie zawiera identyfikatora encountera.")
            encounter = build_encounter_from_scenario(load_scenario(snapshot.pending_encounter.encounter_scenario))
            if restored_custom_party:
                encounter = encounter_with_custom_party(
                    encounter,
                    restored_custom_party,
                )
            encounter = encounter_for_party_size(
                encounter,
                sum(actor.faction == Faction.ALLY for actor in encounter.actors),
            )
            combat_by_id = {actor.id: actor for actor in snapshot.combat_state.actors}
            encounter = replace(
                encounter,
                actors=tuple(combat_by_id.get(actor.id, actor) for actor in encounter.actors),
            )
            combat_ids = {str(actor.id) for actor in snapshot.combat_state.actors}
            encounter_ids = {str(actor.id) for actor in encounter.actors}
            summon_ids = {
                str(summon.actor_id)
                for summon in snapshot.combat_state.summoned_creatures
            }
            if combat_ids != encounter_ids | summon_ids:
                raise ValueError("Lista aktorów walki nie odpowiada aktualnej wersji encountera.")
            restored_initiative_flow = EncounterInitiativeFlow(
                encounter=encounter,
                prompts=(),
                entries=list(snapshot.combat_state.initiative_order.entries),
                completed=True,
                order=snapshot.combat_state.initiative_order,
            )
        self.custom_party = restored_custom_party
        self.exploration = replace(base_exploration, actors=snapshot.actors)
        self.state = snapshot.exploration_state
        self.active_combat_effects = snapshot.active_effects
        self.combat_state = snapshot.combat_state
        self.resolved_encounter_trigger_ids = set(snapshot.resolved_encounter_trigger_ids)
        self.selected_attack_source_ids = dict(snapshot.selected_attack_source_ids)
        self.selected_healing_source_ids = dict(snapshot.selected_healing_source_ids)
        self.selected_lead_actor_id = snapshot.selected_lead_actor_id
        self.selected_helper_actor_id = snapshot.selected_helper_actor_id
        self.active_point_id = snapshot.active_point_id
        self.preview_zone_id = snapshot.preview_zone_id
        self.interaction_result = dict(snapshot.interaction_result) if snapshot.interaction_result is not None else None
        self.ui_flow_stage = stage
        self.active_paper_map_id = (
            self.current_zone.paper_map.id
            if self.current_zone.paper_map is not None
            else ""
        )
        self.board_selected_goal_id = ""
        self.board_selected_panel = ""
        self.board_selected_action_kind = ""
        self.board_selected_action_id = ""
        self.board_selected_action_confirmed = False
        self.board_actor_selection = None
        self.board_selected_actor_id = ""
        self.board_selected_actor_role = ""
        self.board_selection_revision = 0
        self.exploration_board_selection_active = False
        restored_npc_transition = (
            restore_npc_transition_plan(base_exploration.npc_transitions, snapshot.pending_npc_transition)
            if snapshot.pending_npc_transition is not None
            else None
        )
        self.pending_state = UiPendingState(
            encounter=snapshot.pending_encounter,
            npc_transition=restored_npc_transition,
        )
        self.declaration_thread = []
        self.active_preparation_effects = []
        self.exploration_setup_flow = None
        self.post_interaction_setup_steps = ()
        self.selected_combat_movement_path = None
        self.encounter_setup_flow = None
        self.encounter_initiative_flow = restored_initiative_flow
        self._retry_encounter_combat_state = None
        self._retry_encounter_initiative_flow = None
        self.messages = []
        self.conversation_entries = list(snapshot.conversation_entries)
        self._record(
            "ui_snapshot_loaded",
            {"path": str(snapshot_path), "schema_version": SNAPSHOT_SCHEMA_VERSION},
        )
        self._add_message("Gra wczytana", "Przywrócono zapisany stan scenariusza.")
        self.board_message = "Przywrócono zapis gry. Stan planszy zsynchronizowano z sesją."
        self._sync_board_leds()
        return self.state_payload()

    def _terminal_encounter_trigger_id(self) -> str | None:
        terminal_ids = {
            trigger.id
            for trigger in self.exploration.encounter_triggers
            if trigger.defeat_policy == EncounterDefeatPolicy.GAME_OVER
        }.intersection(self.resolved_encounter_trigger_ids)
        if len(terminal_ids) != 1:
            return None
        return next(iter(terminal_ids))

    def _encounter_retry_payload(self) -> dict[str, object]:
        trigger_id = self._terminal_encounter_trigger_id()
        available = bool(
            self.ui_flow_stage == UiFlowStage.GAME_OVER
            and trigger_id is not None
            and self.encounter_checkpoint_path.exists()
        )
        return {
            "available": available,
            "trigger_id": trigger_id,
            "reason": (
                ""
                if available
                else "Brak poprawnego checkpointu początku encountera."
            ),
        }

    def _write_encounter_checkpoint(self) -> bool | None:
        if not self.automatic_checkpoints:
            return None
        if self.pending_encounter is None or self.combat_state is None:
            return False
        if self.combat_state.status != CombatStatus.ACTIVE:
            return False
        try:
            write_snapshot(self.encounter_checkpoint_path, self.create_snapshot())
        except (OSError, ValueError) as exc:
            self._record(
                "ui_encounter_checkpoint_failed",
                {
                    "trigger_id": self.pending_encounter.trigger_id,
                    "error": str(exc),
                },
            )
            return False
        self._record(
            "ui_encounter_checkpoint_saved",
            {
                "trigger_id": self.pending_encounter.trigger_id,
                "path": str(self.encounter_checkpoint_path),
                "schema_version": SNAPSHOT_SCHEMA_VERSION,
            },
        )
        return True

    def retry_encounter(self) -> dict[str, object]:
        if self.ui_flow_stage != UiFlowStage.GAME_OVER:
            raise ValueError("Encounter można ponowić wyłącznie z ekranu Game Over.")
        trigger_id = self._terminal_encounter_trigger_id()
        if trigger_id is None:
            raise ValueError("Nie można ustalić encountera do ponowienia.")
        if not self.encounter_checkpoint_path.is_file():
            raise ValueError("Brak checkpointu początku encountera.")
        self._load_snapshot_from_path(
            self.encounter_checkpoint_path,
            expected_encounter_trigger_id=trigger_id,
        )
        checkpoint_combat = self.combat_state
        initiative_flow = self.encounter_initiative_flow
        if checkpoint_combat is None or initiative_flow is None:
            raise ValueError("Checkpoint nie zawiera kompletnego początku walki.")
        encounter = replace(
            initiative_flow.encounter,
            actors=checkpoint_combat.actors,
        )
        initiative_flow.encounter = encounter
        self._retry_encounter_combat_state = checkpoint_combat
        self._retry_encounter_initiative_flow = initiative_flow
        self.combat_state = None
        self.encounter_initiative_flow = None
        self.encounter_setup_flow = EncounterSetupFlow(
            encounter=encounter,
            steps=_build_encounter_setup_steps(
                encounter,
                fixed_player_positions=True,
            ),
            is_retry=True,
        )
        self._record(
            "ui_encounter_retried",
            {
                "trigger_id": trigger_id,
                "path": str(self.encounter_checkpoint_path),
            },
        )
        self._add_message(
            "Ponowienie encountera",
            "Przywrócono początek walki. Rozstawcie ponownie bohaterów, teren i przeciwników na wskazanych polach; zachowana inicjatywa zacznie obowiązywać po potwierdzeniu setupu.",
        )
        self.board_message = (
            "Checkpoint przywrócony. Rozpocznij ponowny setup planszy."
        )
        self._sync_board_leds()
        return self.state_payload()

    def _snapshot_blocker(self) -> str | None:
        if self.exploration_card_state.pending is not None:
            return "Najpierw zaakceptuj albo odrzuć zeskanowaną kartę eksploracji."
        pending_fields = tuple(
            item.name
            for item in fields(self.pending_state)
            if item.name not in {"encounter", "npc_transition"}
            and getattr(self.pending_state, item.name) not in (None, "")
        )
        if pending_fields:
            return "Najpierw dokończ albo anuluj rozpoczęty wybór, rzut lub odpoczynek."
        if self.active_preparation_effects:
            return "Najpierw rozstrzygnij aktywne przygotowanie do testu."
        if self.selected_combat_movement_path is not None:
            return "Najpierw potwierdź albo anuluj podgląd ruchu."
        if self.exploration_setup_flow is not None and not self.exploration_setup_flow.completed:
            return "Najpierw zakończ setup eksploracji."
        if self.encounter_setup_flow is not None and self.combat_state is None:
            return "Najpierw zakończ setup i inicjatywę encountera."
        if self.encounter_initiative_flow is not None and self.combat_state is None:
            return "Najpierw zakończ inicjatywę encountera."
        return None

    def _snapshot_payload(self) -> dict[str, object]:
        blocker = self._snapshot_blocker()
        return {
            "schema_version": SNAPSHOT_SCHEMA_VERSION,
            "path": str(self.snapshot_path),
            "exists": self.snapshot_path.exists(),
            "can_save": blocker is None,
            "blocker": blocker,
        }

    def _write_stable_checkpoint(self, *, reason: str) -> bool:
        if not self.automatic_checkpoints:
            return False
        if self._snapshot_blocker() is not None:
            return False
        try:
            write_snapshot(self.snapshot_path, self.create_snapshot())
        except OSError as exc:
            self._record(
                "ui_automatic_checkpoint_failed",
                {"reason": reason, "error": str(exc)},
            )
            return False
        self._record(
            "ui_automatic_checkpoint_saved",
            {
                "reason": reason,
                "path": str(self.snapshot_path),
                "schema_version": SNAPSHOT_SCHEMA_VERSION,
            },
        )
        return True

    def configure_board(
        self,
        *,
        backend: str,
        board_url: str = "",
        board_serial_port: str = "",
        wled_url: str = "",
        scan_timeout_s: float | None = None,
    ) -> dict[str, object]:
        backend = str(backend or "none").strip().lower()
        if backend not in {"none", "simulator", "hardware"}:
            raise ValueError("Backend planszy musi mieć wartość none, simulator albo hardware.")
        self.board_backend = backend
        self.board_url = board_url.strip() or self.board_url
        self.board_serial_port = board_serial_port.strip()
        self.wled_url = wled_url.strip()
        if scan_timeout_s is not None:
            self.scan_timeout_s = max(0.1, float(scan_timeout_s))
        if backend == "none":
            self.board_adapter = None
            self.board_message = "Plansza niepodłączona."
            if (
                not self.debug_point_id
                and not self.debug_challenge_id
                and self.ui_flow_stage != UiFlowStage.SPELL_PREPARATION
            ):
                self.ui_flow_stage = UiFlowStage.WAITING_FOR_BOARD
            self._record("ui_board_configured", {"backend": backend, "connected": False})
            return self.state_payload()
        self.board_adapter = BoardSessionAdapter.connect(
            backend=backend,
            board_url=self.board_url,
            serial_port=self.board_serial_port,
            wled_url=self.wled_url,
        )
        self.board_message = f"Plansza podłączona: {backend}."
        if self.ui_flow_stage == UiFlowStage.WAITING_FOR_BOARD:
            self.ui_flow_stage = UiFlowStage.READY_TO_START
        self._sync_board_leds()
        self._record(
            "ui_board_configured",
            {
                "backend": backend,
                "connected": True,
                "board_url": self.board_url,
                "serial_port": self.board_serial_port,
                "wled_url": self.wled_url,
            },
        )
        return self.state_payload()

    def attach_board_connection(self, connection: object, *, backend: str = "simulator") -> None:
        self.board_backend = backend
        self.board_adapter = BoardSessionAdapter(connection)
        self.board_message = f"Plansza podłączona: {backend}."
        if backend in {"simulator", "hardware"} and self.ui_flow_stage == UiFlowStage.WAITING_FOR_BOARD:
            self.ui_flow_stage = UiFlowStage.READY_TO_START

    def confirm_spell_preparation(
        self,
        *,
        actor_id: str,
        spell_ids: tuple[str, ...],
    ) -> dict[str, object]:
        if self.ui_flow_stage != UiFlowStage.SPELL_PREPARATION:
            raise ValueError("Przygotowanie czarów nie jest teraz aktywne.")
        transition = self.spell_preparation_flow.confirm(
            actors=self.exploration.actors,
            actor_id=actor_id,
            spell_ids=spell_ids,
        )
        self.exploration = replace(self.exploration, actors=transition.actors)
        actor = next(candidate for candidate in transition.actors if str(candidate.id) == actor_id)
        self._record(
            "ui_spell_preparation_confirmed",
            {
                "actor_id": actor_id,
                "prepared_spell_ids": list(transition.prepared_spell_ids),
                "complete": transition.complete,
            },
        )
        self._add_message(
            "Przygotowanie czarów",
            f"{actor.name} potwierdza przygotowane czary.",
        )
        if transition.complete:
            self.ui_flow_stage = UiFlowStage.LOCATION_PREVIEW
            self.preview_zone_id = ""
            self.board_message = "Przygotowanie zakończone. Wybierz pierwszą lokację na planszy."
        self._sync_board_leds()
        return self.state_payload()

    def declare_spell_preparation_card(self, spell_id: str) -> dict[str, object]:
        """Validate one physical spell card for the active preparation step."""

        if self.ui_flow_stage != UiFlowStage.SPELL_PREPARATION:
            raise ValueError("Przygotowanie czarów nie jest teraz aktywne.")
        pending = self.spell_preparation_flow.pending_actors(self.exploration.actors)
        if not pending:
            raise ValueError("Wszystkie postacie przygotowały już czary.")
        actor = pending[0]
        profile = actor.spell_preparation
        if profile is None:
            raise ValueError(f"{actor.name} nie przygotowuje czarów.")
        spell = next(
            (
                candidate
                for candidate in profile.available_spells
                if candidate.id == spell_id
            ),
            None,
        )
        if spell is None:
            raise ValueError(
                f"Karta tego czaru nie należy do listy przygotowań postaci {actor.name}."
            )
        if spell.id in profile.always_prepared_spell_ids:
            raise ValueError(
                f"{spell.label} jest zawsze przygotowany i nie zajmuje miejsca w limicie."
            )
        self._record(
            "ui_spell_preparation_card_declared",
            {
                "actor_id": str(actor.id),
                "spell_id": spell.id,
            },
        )
        return {
            "actor_id": str(actor.id),
            "actor_name": actor.name,
            "spell_id": spell.id,
            "spell_label": spell.label,
            "spell_level": spell.level,
            "preparation_limit": profile.preparation_limit,
        }

    def _active_exploration_prompt(self) -> ExplorationPrompt:
        """Project the current UI wait state into the shared card prompt contract."""

        actor_ids = tuple(
            str(actor.id)
            for actor in self.exploration.actors
            if actor.faction == Faction.ALLY and not actor.is_defeated()
        )
        zone_id = self.current_zone.id
        instance_id = f"{self.exploration.scenario_id}:{zone_id}"
        interaction_id = self._exploration_card_interaction_id()
        if (
            self.ui_flow_stage == UiFlowStage.SHORT_REST
            and self.pending_short_rest is not None
            and not self.pending_short_rest.completed
        ):
            return ExplorationPrompt(
                id=f"{instance_id}:short_rest:{self.state.elapsed_minutes}",
                kind=ExplorationPromptKind.REST,
                tags=frozenset({"rest", "short_rest", "safe_break"}),
                eligible_actor_ids=actor_ids,
                instance_id=instance_id,
                handler_ids=frozenset(self.current_zone.exploration_card_ids),
            )
        if self.pending is not None and self.pending.stage == PendingStage.ROLL:
            plan = self.pending.check_plan
            tags = {"check", "before_roll"}
            if plan is not None:
                tags.add(plan.ability)
                if plan.skill:
                    tags.add(plan.skill)
                tags.update(plan.context_tags)
            return ExplorationPrompt(
                id=(
                    f"{instance_id}:{self.pending.kind.value}:"
                    f"{interaction_id or 'check'}:roll"
                ),
                kind=ExplorationPromptKind.BEFORE_ROLL,
                tags=frozenset(tags),
                eligible_actor_ids=actor_ids,
                instance_id=instance_id,
                interaction_id=interaction_id,
                handler_ids=frozenset(self.current_zone.exploration_card_ids),
            )
        if (
            self.exploration.continuation is not None
            and self.pending_continuation_navigator_actor_id is not None
            and self.ui_flow_stage == UiFlowStage.LOCATION_ACTIVE
        ):
            return ExplorationPrompt(
                id=f"{instance_id}:scenario_continuation:before_roll",
                kind=ExplorationPromptKind.BEFORE_ROLL,
                tags=frozenset(
                    {
                        "check",
                        "before_roll",
                        "travel",
                        "navigation",
                        "survival",
                        "route",
                    }
                ),
                eligible_actor_ids=actor_ids,
                instance_id=instance_id,
                interaction_id="scenario_continuation",
                handler_ids=frozenset(self.current_zone.exploration_card_ids),
            )
        if self.pending is not None or self.active_point is not None:
            tags = {"interaction"}
            interaction_id = interaction_id or "pending"
            if self.pending is not None:
                tags.add(self.pending.kind.value)
                tags.update(
                    {
                        PendingKind.NPC: {"conversation", "npc", "negotiation"},
                        PendingKind.FIXTURE: {"object", "fixture", "mechanism", "lock", "security", "closed"},
                        PendingKind.TRAP: {"trap", "hazard", "mechanism"},
                        PendingKind.CHALLENGE: {"tactical", "route", "hazard", "location"},
                        PendingKind.ZONE_OPTION: {"location", "route", "travel"},
                        PendingKind.OBSERVATION: {"search", "object", "location"},
                    }.get(self.pending.kind, set())
                )
            if self.active_point is not None:
                tags.update({"object", "target"})
                if self.active_point.npc_interaction is not None:
                    tags.update({"conversation", "npc", "negotiation"})
                tags.update(self.active_point.divination_tags)
            return ExplorationPrompt(
                id=f"{instance_id}:{interaction_id}:decision",
                kind=ExplorationPromptKind.INTERACTION,
                tags=frozenset(tags),
                eligible_actor_ids=actor_ids,
                instance_id=instance_id,
                interaction_id=interaction_id,
                handler_ids=frozenset(self.current_zone.exploration_card_ids),
            )
        if self.ui_flow_stage == UiFlowStage.LOCATION_ACTIVE:
            return ExplorationPrompt(
                id=f"{instance_id}:free:{len(self.state.flags.values)}",
                kind=ExplorationPromptKind.FREE_ACTION,
                tags=frozenset(
                    {
                        "free_action", "location", "route", "travel", "search",
                        "target", "object", "trap", "hazard", "tactical",
                    }
                ),
                eligible_actor_ids=actor_ids,
                instance_id=instance_id,
                handler_ids=frozenset(self.current_zone.exploration_card_ids),
            )
        raise ValueError("Aplikacja nie oczekuje teraz na decyzję eksploracyjną.")

    def _exploration_card_interaction_id(self) -> str | None:
        if self.board_selected_goal_id:
            return self.board_selected_goal_id
        if self.pending is not None:
            if self.pending.option is not None:
                return self.pending.option.id
            if self.pending.zone_option is not None:
                return self.pending.zone_option.id
            if self.pending.point is not None:
                return self.pending.point.id
        return self.active_point_id or None

    def _exploration_card_actor(
        self,
        action_id: str,
        owner_actor_id: str | None,
    ) -> Actor:
        alive = tuple(
            actor
            for actor in self.exploration.actors
            if actor.faction == Faction.ALLY and not actor.is_defeated()
        )
        allowed_ids = CURATED_CARD_OWNERS.get(action_id, ())
        if owner_actor_id is not None:
            actor = next(
                (candidate for candidate in alive if str(candidate.id) == owner_actor_id),
                None,
            )
            if actor is None:
                raise ValueError("Właściciel tej karty nie uczestniczy w scenie.")
            if allowed_ids and owner_actor_id not in allowed_ids:
                raise ValueError(
                    "Ta karta nie należy do wskazanej postaci "
                    f"({action_id}: {owner_actor_id}; dozwoleni: "
                    f"{', '.join(allowed_ids)})."
                )
            return actor
        candidates = tuple(
            actor
            for actor in alive
            if not allowed_ids or str(actor.id) in allowed_ids
        )
        if len(candidates) != 1:
            raise ValueError(
                "Ta karta ma kilku możliwych właścicieli. Użyj karty z osobistym QR v2."
            )
        return candidates[0]

    def _declare_exploration_card(
        self,
        definition: CardActionDefinition,
        *,
        owner_actor_id: str | None,
    ) -> dict[str, object]:
        handler = exploration_card_handler(definition.action_id)
        if handler is None:
            raise ValueError(
                "Ta karta eksploracyjna nie reaguje na żaden obsługiwany prompt."
            )
        if definition.action_id == "bardic_inspiration" and owner_actor_id == "lorian":
            flaw_key = f"flaw_lorian_approval_block:{self.active_point_id or 'scene'}"
            if scene_flag(self.state.flags, flaw_key, False):
                raise ValueError(
                    "Lorian stracił pewność siebie po porażce w tej rozmowie. "
                    "Najpierw potrzebuje Pomocy sojusznika albo szczerej próby naprawy relacji."
                )
        prompt = self._active_exploration_prompt()
        actor = self._exploration_card_actor(handler.card_action_id, owner_actor_id)
        persisted_attempts = scene_flag(
            self.state.flags,
            "exploration_card_attempt_keys",
            (),
        )
        if not isinstance(persisted_attempts, (list, tuple)):
            persisted_attempts = ()
        self.exploration_card_state = replace(
            self.exploration_card_state,
            spent_attempt_keys=frozenset(str(key) for key in persisted_attempts),
        )
        transition = self.exploration_card_flow.declare(
            state=self.exploration_card_state,
            handler=handler,
            prompt=prompt,
            actor_id=str(actor.id),
        )
        self.exploration_card_state = transition.state
        self.board_message = (
            f"{handler.player_label or player_label(handler.card_action_id)} — "
            "zeskanuj AKCEPTUJ, aby uruchomić efekt, albo ODRZUĆ, aby wrócić."
        )
        self._record(
            "ui_exploration_card_declared",
            {
                "actor_id": str(actor.id),
                "card_action_id": handler.card_action_id,
                "prompt_id": prompt.id,
                "prompt_kind": prompt.kind.value,
            },
        )
        return self.state_payload()

    def resolve_exploration_card(self, *, accept: bool) -> dict[str, object]:
        pending = self.exploration_card_state.pending
        if pending is None:
            raise ValueError("Nie ma karty eksploracji oczekującej na decyzję.")
        if not accept:
            transition = self.exploration_card_flow.decline(self.exploration_card_state)
            self.exploration_card_state = transition.state
            self.board_message = "Odrzucono kartę eksploracji. Wrócono do poprzedniej decyzji."
            self._record(
                "ui_exploration_card_declined",
                {"card_action_id": pending.card_action_id, "prompt_id": pending.prompt_id},
            )
            return self.state_payload()

        actor = next(
            candidate
            for candidate in self.exploration.actors
            if str(candidate.id) == pending.actor_id
        )
        resource_id = {
            "guard_duty": "guard_duty_uses",
            "bardic_inspiration": "bardic_inspiration_uses",
            "tracking": "instinct",
            "find_traps": "instinct" if pending.actor_id == "erynd" else "",
            "locate_object": "instinct" if pending.actor_id == "erynd" else "",
            "pass_without_trace": "instinct",
        }.get(pending.card_action_id, "")
        if resource_id:
            actor = spend_actor_resource(actor, resource_id).actor_after
            self.exploration = self._replace_exploration_actor(actor)
        spell = next(
            (item for item in actor.spells if item.id == pending.card_action_id),
            None,
        )
        if (
            spell is not None
            and spell.level > 0
            and pending.card_action_id not in {"detect_magic", "identify"}
        ):
            spell_use = consume_spell_resource(
                actor,
                spell.level,
                spell_id=spell.id,
                cast_level=spell.level,
            )
            actor = spell_use.actor_after
            self.exploration = self._replace_exploration_actor(actor)

        if pending.card_action_id == "guidance":
            self._use_guidance_physical_card()
        elif pending.card_action_id in {"guard_duty", "alarm"}:
            self.state = replace(
                self.state,
                flags=set_scene_flag(self.state.flags, "short_rest_alarm_active", True),
            )
            self.board_message = (
                "Warta zabezpiecza odpoczynek. Drużyna nie będzie Zaskoczona "
                "przez napad podczas tego odpoczynku."
            )
        elif pending.card_action_id == "find_traps":
            revealed = tuple(
                trap
                for trap in self.state.traps
                if trap.zone_id == self.current_zone.id
            )
            for trap in revealed:
                self.state = reveal_trap(self.state, trap.id)
            self.board_message = (
                f"Wykrycie pułapek ujawnia zagrożenia w tej lokacji: {len(revealed)}."
            )
        else:
            result_flag = pending.handler.result_flag
            if result_flag:
                self.state = replace(
                    self.state,
                    flags=set_scene_flag(self.state.flags, result_flag, True),
                )
            self.board_message = (
                f"{pending.handler.player_label or player_label(pending.card_action_id)}: "
                "efekt został przekazany do aktywnej interakcji."
            )
        self._apply_authored_exploration_card_reaction(pending)
        transition = self.exploration_card_flow.accept(self.exploration_card_state)
        self.exploration_card_state = transition.state
        self.state = replace(
            self.state,
            flags=set_scene_flag(
                self.state.flags,
                "exploration_card_attempt_keys",
                tuple(sorted(self.exploration_card_state.spent_attempt_keys)),
            ),
        )
        self._record(
            "ui_exploration_card_accepted",
            {
                "actor_id": pending.actor_id,
                "card_action_id": pending.card_action_id,
                "prompt_id": pending.prompt_id,
                "attempt_key": pending.attempt_key,
            },
        )
        return self.state_payload()

    def _apply_authored_exploration_card_reaction(self, pending) -> None:
        prompt = self._active_exploration_prompt()
        reaction = next(
            (
                item
                for item in self.current_zone.exploration_card_reactions
                if item.matches(
                    card_action_id=pending.card_action_id,
                    interaction_id=prompt.interaction_id,
                    prompt_kind=prompt.kind.value,
                    tags=prompt.tags,
                )
            ),
            None,
        )
        if reaction is None:
            return
        for raw_effect in reaction.effects:
            result = apply_exploration_effect(self.state, raw_effect)
            self.state = result.state
            self._record_effect_result(
                result,
                source=f"exploration_card_reaction:{reaction.id}",
                raw_effect=raw_effect,
            )
        if reaction.check_modifier or reaction.roll_mode != RollMode.NORMAL:
            kind = (
                "exploration_card_check_advantage"
                if reaction.roll_mode == RollMode.ADVANTAGE
                else "exploration_card_check_disadvantage"
                if reaction.roll_mode == RollMode.DISADVANTAGE
                else "exploration_card_check_modifier"
            )
            effect = ActiveCombatEffect(
                id=f"{kind}:{reaction.id}:{pending.actor_id}",
                actor_id=pending.actor_id,
                kind=kind,
                label=reaction.message or pending.handler.player_label,
                object_id=f"exploration_card_reaction:{reaction.id}",
                value=reaction.check_modifier,
                source=EffectSource(
                    EffectSourceType.SCENE,
                    reaction.id,
                    reaction.message or pending.handler.player_label,
                ),
                duration=EffectDuration.UNTIL_SCENARIO_END,
                stacking_key=f"exploration_card_reaction:{reaction.id}:{pending.actor_id}",
            )
            self.active_combat_effects = apply_active_effect(
                self.active_combat_effects,
                effect,
            ).active_effects
        if reaction.redirect_option_id and self.pending is not None:
            if self.pending.challenge is not None:
                option = next(
                    (
                        item
                        for item in self.pending.challenge.options
                        if item.id == reaction.redirect_option_id
                    ),
                    None,
                )
                if option is not None:
                    self.pending = replace(self.pending, option=option)
            self.state = replace(
                self.state,
                flags=set_scene_flag(
                    self.state.flags,
                    f"exploration_card_redirect:{reaction.redirect_option_id}",
                    True,
                ),
            )
        if reaction.message:
            self.board_message = reaction.message
            self._add_message("Karta eksploracji", reaction.message)
        self._record(
            "ui_exploration_card_reaction_applied",
            {
                "reaction_id": reaction.id,
                "card_action_id": pending.card_action_id,
                "interaction_id": prompt.interaction_id,
                "redirect_option_id": reaction.redirect_option_id,
                "check_modifier": reaction.check_modifier,
                "roll_mode": reaction.roll_mode.value,
            },
        )

    def _exploration_card_payload(self) -> dict[str, object]:
        return {
            "enabled": False,
            "prompt": None,
            "pending": None,
            "spent_attempt_keys": [],
            "message": (
                "Karty eksploracji są wyłączone. Specjalne możliwości postaci "
                "pojawiają się jako autorskie kafelki interakcji."
            ),
        }

    def use_physical_action_card(
        self,
        action_kind: DecisionCardActionKind,
        source_id: str,
        owner_actor_id: str | None = None,
    ) -> dict[str, object]:
        """Route a scanned action card through the same domain flows as the UI."""

        definition = card_action_definition(source_id, qr_kind=action_kind)
        phase = (
            CardPhase.COMBAT
            if self.combat_state is not None
            and self.combat_state.status == CombatStatus.ACTIVE
            else CardPhase.EXPLORATION
        )
        validate_card_phase(definition, phase)

        if phase is CardPhase.EXPLORATION:
            raise ValueError(
                "Karty eksploracji są obecnie wyłączone. Wybierz specjalny "
                "kafelek postaci dostępny w tej interakcji."
            )

        if self.combat_state is None:
            raise ValueError("Walka nie została rozpoczęta.")
        if owner_actor_id is not None:
            current_actor_id = str(combat_current_actor(self.combat_state).id)
            window = self.pending_reaction_window
            reaction_owner_is_legal = bool(
                window is not None
                and window.current_option.reactor_actor_id == owner_actor_id
                and window.current_option.effect_id
                in {definition.source_id, definition.action_id}
            )
            if owner_actor_id != current_actor_id and not reaction_owner_is_legal:
                raise ValueError(
                    "W walce kartę może zagrać wyłącznie aktualnie aktywna "
                    "postać albo bohater wskazany przez otwarte okno reakcji."
                )
        if action_kind is DecisionCardActionKind.SPELL:
            caster = combat_current_actor(self.combat_state)
            spell = next(
                (item for item in caster.spells if item.id == definition.action_id),
                None,
            )
            if (
                spell is not None
                and getattr(spell, "concentration", False)
                and flaw_blocks_concentration_spell(caster, self.active_combat_effects)
            ):
                raise ValueError(
                    "Echo magicznego wycieku blokuje czary z Koncentracją do końca tury Nimry."
                )
        if action_kind is DecisionCardActionKind.FEATURE:
            if definition.action_id in {
                "bardic_inspiration",
                "lay_on_hands",
                "preserve_life",
            }:
                return self.start_combat_class_feature_targeting(definition.action_id)
            if definition.action_id == "cutting_words":
                window = self.pending_reaction_window
                if (
                    window is None
                    or window.current_option.kind != ReactionKind.CUTTING_WORDS
                ):
                    raise ValueError(
                        "Ciętą ripostę można zagrać dopiero po pokazaniu rzutu "
                        "ataku albo obrażeń przeciwnika."
                    )
                self.board_message = (
                    "Cięta riposta zadeklarowana. Wpisz wynik kości Inspiracji "
                    "w otwartym oknie reakcji."
                )
                return self.state_payload()
            if definition.action_id in PHYSICAL_METAMAGIC_ACTION_IDS:
                return self.apply_physical_metamagic(definition.action_id)
            if definition.action_id in {
                "second_wind",
                "sacred_weapon",
                "turn_the_unholy",
                "turn_undead",
                "divine_smite",
                "deflect_missiles",
                "wild_shape",
                "cunning_action",
                "pact_weapon",
            }:
                if (
                    definition.action_id == "wild_shape"
                    and combat_current_actor(self.combat_state).wild_shape is not None
                ):
                    return self.use_combat_class_feature("wild_shape")
                return self._queue_physical_feature_prompt(definition.action_id)
            return self.use_combat_class_feature(definition.action_id)
        if action_kind is DecisionCardActionKind.SPELL:
            if definition.combat_route is not None:
                return self._route_combat_spell_card(definition)
            raise ValueError(
                "Ten czar bojowy jest skatalogowany, ale jego skan nie został "
                "jeszcze podłączony do dedykowanego przepływu."
            )
        raise ValueError("Ten rodzaj karty nie jest jeszcze obsługiwany przez skaner.")

    def _route_combat_spell_card(
        self,
        definition: CardActionDefinition,
    ) -> dict[str, object]:
        """Enter an existing combat flow without duplicating spell mechanics."""

        if self.combat_state is None:
            raise ValueError("Walka nie została rozpoczęta.")
        actor = combat_current_actor(self.combat_state)
        route = definition.combat_route

        if route is CombatCardRoute.ATTACK_SOURCE:
            if not any(
                source.id == definition.action_id
                for source in self._attack_sources_for_actor(actor)
            ):
                raise ValueError(
                    f"{actor.name} nie ma teraz dostępnego czaru {definition.source_id}."
                )
            return self.select_combat_attack_source(definition.action_id)

        if route is CombatCardRoute.HEALING_SOURCE:
            if not any(
                source.id == definition.action_id
                for source in self._healing_sources_for_actor(actor)
            ):
                raise ValueError(
                    f"{actor.name} nie ma teraz dostępnego czaru {definition.source_id}."
                )
            return self.select_combat_healing_source(definition.action_id)

        if route is CombatCardRoute.COMBAT_ACTION:
            if definition.action_id == "spare_the_dying":
                return self.start_combat_stabilization_targeting(
                    StabilizationMethod.SPARE_THE_DYING.value,
                )
            if (
                definition.action_id == "goodberry"
                and (pool := actor_resource_pool(actor, "goodberry_charges"))
                is not None
                and pool.current > 0
            ):
                return self.select_combat_healing_source("goodberry_use")
            if definition.action_id in {"moonbeam", "flaming_sphere"}:
                movable_zone = next(
                    (
                        effect
                        for effect in self.active_combat_effects
                        if effect.source_actor_id == str(actor.id)
                        and effect.object_id
                        == f"combat_action:{definition.action_id}"
                        and effect.kind.startswith("ongoing_damage_zone:")
                    ),
                    None,
                )
                if movable_zone is not None:
                    return self.start_moonbeam_move(movable_zone.id)
            action = self._combat_action_for_physical_card(
                actor,
                definition.action_id,
            )
            if action is None:
                raise ValueError(
                    f"{actor.name} nie ma teraz dostępnego czaru {definition.source_id}."
                )
            cast_level = action.spell_level if action.spell_level > 0 else None
            self._start_combat_action(action, cast_level=cast_level)
            pending = self.pending_concentration_action
            actor_id = str(actor.id)
            if (
                (
                    definition.targeting.startswith("self")
                    or definition.action_id in {"find_traps", "goodberry"}
                )
                and pending is not None
                and actor_id in pending.target_ids
                and actor_id not in pending.selected_target_ids
            ):
                self.pending_concentration_action = (
                    self.player_combat_resource_flow.toggle_concentration_target(
                        pending,
                        actor_id,
                    )
                )
                self.board_message = (
                    f"{action.label}: celem jest {actor.name}. "
                    "Potwierdź użycie karty w panelu."
                )
                self._sync_board_leds()
            return self.state_payload()

        if route is CombatCardRoute.REACTION:
            window = self.pending_reaction_window
            if (
                definition.action_id == "shield"
                and window is not None
                and window.current_option.kind == ReactionKind.DEFENSIVE_SPELL
                and window.current_option.effect_id == definition.action_id
            ):
                return self.cast_defensive_spell_reaction()
            if (
                definition.action_id == "hellish_rebuke"
                and window is not None
                and window.current_option.kind == ReactionKind.RETALIATION_SPELL
                and window.current_option.effect_id == definition.action_id
            ):
                return self.cast_retaliation_spell_reaction()
            raise ValueError(
                "Tę kartę można zagrać wyłącznie w aktywnym oknie właściwej reakcji."
            )

        raise ValueError("Ta karta nie ma obsługiwanego wejścia do walki.")

    def _combat_action_for_physical_card(
        self,
        actor: Actor,
        action_id: str,
    ) -> Any | None:
        encounter = self._active_encounter()
        if encounter is None:
            raise ValueError("Brak danych encountera dla aktywnej walki.")
        actions = encounter.combat_actions_by_actor.get(actor.id, ())
        return next(
            (
                action
                for action in actions
                if action.id == action_id or action.cast_flag == f"cast_{action_id}"
            ),
            None,
        )

    def _start_combat_action(
        self,
        action: Any,
        *,
        cast_level: int | None,
    ) -> dict[str, object]:
        """Shared execution router used by the screen menu and physical cards."""

        if action.source_item_id and self.combat_state is not None:
            actor = combat_current_actor(self.combat_state)
            if flaw_blocks_equipment_use(actor, self.active_combat_effects):
                raise ValueError(
                    "Skaza Brakki: podczas Szału nie może korzystać z mikstur, zwojów ani aktywnych właściwości ekwipunku."
                )

        if action.action_type == "strength_potion":
            return self.use_combat_strength_potion(action.id)
        if action.action_type == "multi_target_damage":
            return self.start_multi_target_damage_spell(
                action.id,
                cast_level=cast_level,
            )
        if action.action_type == "assisted_spell":
            return self.use_assisted_combat_spell(
                action.id,
                cast_level=cast_level,
            )
        if action.action_type in {
            "concentration_attack_bonus",
            "targeted_status",
        }:
            return self.start_combat_concentration_action(
                action.id,
                cast_level=cast_level,
            )
        if action.action_type == "long_cast_effect":
            return self.start_long_cast(action.id, cast_level=cast_level)
        if action.action_type == "summon":
            return self.start_summon(action.id, cast_level=cast_level)
        if action.action_type == "spell_movement":
            return self.start_magic_movement(action.id, cast_level=cast_level)
        if action.action_type == "spell_debuff":
            return self.start_spell_debuff(action.id, cast_level=cast_level)
        if action.action_type == "spell_dispel":
            return self.start_spell_dispel(action.id, cast_level=cast_level)
        raise ValueError("Ten typ akcji nie ma jeszcze wykonawcy w menu walki.")

    def _use_guidance_physical_card(self) -> dict[str, object]:
        pending = self.pending
        if (
            pending is None
            or pending.stage != PendingStage.ROLL
            or pending.check_plan is None
        ):
            raise ValueError("Wskazówki można zagrać bezpośrednio przed testem k20.")
        target_id = str(pending.check_plan.lead_actor_id or self.selected_lead_actor_id)
        target = next(
            (
                actor
                for actor in self.exploration.actors
                if str(actor.id) == target_id and actor.faction == Faction.ALLY
            ),
            None,
        )
        if target is None:
            raise ValueError("Nie znaleziono prowadzącego oczekującego testu.")
        casters = tuple(
            actor
            for actor in self.exploration.actors
            if actor.faction == Faction.ALLY
            and not actor.is_defeated()
            and (
                (validation := actor_spell_cast_validation(actor, "guidance"))
                is not None
                and validation.valid
            )
        )
        if not casters:
            raise ValueError("Żaden bohater nie może teraz rzucić Wskazówek.")
        caster = next(
            (
                actor
                for actor in casters
                if str(actor.id) == self.selected_lead_actor_id
            ),
            casters[0],
        )
        if grid_distance_feet(caster.position, target.position) > 5:
            raise ValueError("Cel Wskazówek musi znajdować się w zasięgu dotyku.")
        effect = ActiveCombatEffect(
            id=f"guidance:{caster.id}:{target.id}:{uuid.uuid4().hex[:8]}",
            actor_id=str(target.id),
            kind="guidance_roll_bonus",
            label="Wskazówki",
            object_id="spell:guidance",
            value=4,
            source_actor_id=str(caster.id),
            source=EffectSource(EffectSourceType.SPELL, "guidance", "Wskazówki"),
            stacking_key=f"guidance_roll_bonus:{target.id}",
        )
        self.active_combat_effects = apply_active_effect(
            self.active_combat_effects,
            effect,
        ).active_effects
        self.board_message = (
            f"{target.name} ma Wskazówki k4. Przy teście wpisz 0, aby zachować "
            "efekt, albo wynik 1–4, aby go zużyć."
        )
        self._record(
            "ui_physical_guidance_applied",
            {"caster_id": str(caster.id), "target_id": str(target.id)},
        )
        return self.state_payload()

    def _use_alarm_physical_card(self) -> dict[str, object]:
        pending = self.pending_short_rest
        if (
            self.ui_flow_stage != UiFlowStage.SHORT_REST
            or pending is None
            or pending.completed
        ):
            raise ValueError("Alarm można zagrać w podglądzie krótkiego odpoczynku.")
        casters = []
        for actor in self.exploration.actors:
            if actor.faction != Faction.ALLY or actor.is_defeated():
                continue
            validation = actor_spell_cast_validation(actor, "alarm", cast_level=1)
            if validation is not None and validation.valid:
                casters.append(actor)
        if not casters:
            raise ValueError("Żaden bohater nie może teraz rzucić Alarmu.")
        caster = next(
            (
                actor
                for actor in casters
                if str(actor.id) == self.selected_lead_actor_id
            ),
            casters[0],
        )
        spell_use = consume_spell_resource(
            caster,
            1,
            spell_id="alarm",
            cast_level=1,
        )
        self.exploration = self._replace_exploration_actor(spell_use.actor_after)
        self.state = replace(
            self.state,
            flags=set_scene_flag(self.state.flags, "short_rest_alarm_active", True),
        )
        self.board_message = (
            f"{caster.name} zabezpiecza odpoczynek Alarmem. Jeśli dojdzie do "
            "napadu, drużyna nie otrzyma kary za zaskoczenie."
        )
        self._record(
            "ui_physical_alarm_armed",
            {"caster_id": str(caster.id), "spell_level": 1},
        )
        return self.state_payload()

    def start_short_rest(self) -> dict[str, object]:
        if self.ui_flow_stage != UiFlowStage.LOCATION_ACTIVE:
            raise ValueError("Krótki odpoczynek można rozpocząć tylko podczas eksploracji.")
        if self.pending is not None or self.active_point is not None:
            raise ValueError("Najpierw zakończ aktywną interakcję.")
        self._refresh_pending_encounter()
        pending = self.short_rest_flow.start(
            state=self.state,
            zone=self.current_zone,
            encounter_pending=self.pending_encounter is not None,
        )
        self.pending_short_rest = pending
        self.ui_flow_stage = UiFlowStage.SHORT_REST
        self.board_message = "Podgląd krótkiego odpoczynku. Potwierdź koszt i ryzyko."
        self._record(
            "ui_short_rest_started",
            {
                "policy_id": pending.policy.id,
                "zone_id": pending.zone_id,
                "duration_minutes": pending.policy.duration_minutes,
                "safety": pending.policy.safety.value,
            },
        )
        return self.state_payload()

    def complete_long_rest(self) -> dict[str, object]:
        """Resolve a long rest only when the active zone explicitly offers it."""
        if self.ui_flow_stage != UiFlowStage.LOCATION_ACTIVE:
            raise ValueError("Długi odpoczynek można rozpocząć tylko podczas eksploracji.")
        if self.pending is not None or self.active_point is not None:
            raise ValueError("Najpierw zakończ aktywną interakcję.")
        self._refresh_pending_encounter()
        transition = self.long_rest_flow.complete(
            state=self.state,
            zone=self.current_zone,
            actors=self.exploration.actors,
            encounter_pending=self.pending_encounter is not None,
            active_effects=self.active_combat_effects,
            roll_die=lambda die_sides: self.encounter_rng.randint(1, die_sides),
        )
        self.state = clear_exploration_hidden(transition.state)
        self.exploration = replace(self.exploration, actors=transition.actors)
        self.active_combat_effects = transition.active_effects
        self._advance_party_lights(transition.policy.duration_minutes)
        self._add_trigger_activation_notices(transition.trigger_activations)
        self._add_expired_magic_effect_notices(transition.expired_magic_effects)
        self._add_expired_condition_notices(
            transition.expired_conditions,
            prefix="Długi odpoczynek kończy stan",
        )
        self._add_clock_event_notices(transition.triggered_clock_events)
        for effect, raw_effect in zip(
            transition.effects,
            transition.policy.completion_effects,
            strict=True,
        ):
            self._record_effect_result(effect, source="long_rest_completion", raw_effect=raw_effect)
        self.board_message = "Drużyna kończy długi odpoczynek. PW, komórki i zasoby zostały odnowione."
        self._add_message("Długi odpoczynek", self.board_message)
        self._record(
            "ui_long_rest_completed",
            {
                "policy_id": transition.policy.id,
                "zone_id": self.current_zone.id,
                "duration_minutes": transition.policy.duration_minutes,
                "elapsed_minutes": self.state.elapsed_minutes,
            },
        )
        if self.custom_party and self.character_progress_sink is not None:
            self.character_progress_sink(
                tuple(actor for actor in self.exploration.actors if actor.faction == Faction.ALLY)
            )
        return self.state_payload()

    def confirm_short_rest(
        self,
        *,
        attunement_choices: list[object] | None = None,
    ) -> dict[str, object]:
        from dnd_board_game.inventory import ItemAttunementAction, ItemAttunementChoice

        pending = self.pending_short_rest
        if self.ui_flow_stage != UiFlowStage.SHORT_REST or pending is None:
            raise ValueError("Brak krótkiego odpoczynku do potwierdzenia.")
        if any(not isinstance(choice, dict) for choice in (attunement_choices or [])):
            raise ValueError("Każdy wybór attunement musi być obiektem.")
        transition = self.short_rest_flow.complete(
            state=self.state,
            actors=self.exploration.actors,
            pending=pending,
            active_effects=self.active_combat_effects,
            roll_die=lambda die_sides: self.encounter_rng.randint(1, die_sides),
            attunement_choices=tuple(
                ItemAttunementChoice(
                    actor_id=str(choice.get("actor_id", "")),
                    item_id=str(choice.get("item_id", "")),
                    action=ItemAttunementAction(str(choice.get("action", ""))),
                )
                for raw_choice in (attunement_choices or [])
                for choice in (raw_choice,)
            ),
        )
        self.state = transition.state
        self.exploration = replace(self.exploration, actors=transition.actors)
        self.state = clear_exploration_hidden(self.state)
        self._advance_party_lights(pending.policy.duration_minutes)
        self.pending_short_rest = transition.pending
        self.active_combat_effects = transition.active_effects
        self._add_trigger_activation_notices(transition.trigger_activations)
        self._add_expired_magic_effect_notices(transition.expired_magic_effects)
        self._add_expired_condition_notices(
            transition.expired_conditions,
            prefix="Krótki odpoczynek kończy stan",
        )
        self._add_clock_event_notices(transition.triggered_clock_events)
        for effect, raw_effect in zip(transition.effects, pending.policy.completion_effects, strict=True):
            self._record_effect_result(
                effect,
                source="short_rest_completion",
                raw_effect=raw_effect,
            )
        recovered = {
            str(result.actor_after.id): list(result.recovered_resource_ids)
            for result in transition.rest_results
            if result.recovered_resource_ids
        }
        self._record(
            "ui_short_rest_completed",
            {
                "policy_id": pending.policy.id,
                "zone_id": pending.zone_id,
                "elapsed_minutes": self.state.elapsed_minutes,
                "recovered_resources": recovered,
                "recovered_item_charges": {
                    str(result.actor_after.id): [
                        {
                            "item_id": recovery.item_id,
                            "recovered": recovery.recovered,
                            "after": recovery.after,
                            "rolls": list(recovery.rolls),
                        }
                        for recovery in result.item_charge_recoveries
                    ]
                    for result in transition.rest_results
                    if result.item_charge_recoveries
                },
                "effect_types": [effect.effect_type for effect in transition.effects],
                "expired_effect_ids": [effect.id for effect in transition.expired_effects],
                "expired_conditions": [
                    {
                        "actor_id": condition.actor_id,
                        "condition": condition.condition.value,
                    }
                    for condition in transition.expired_conditions
                ],
                "expired_magic_effect_ids": [
                    effect.id for effect in transition.expired_magic_effects
                ],
                "attunement": [
                    {
                        "actor_id": str(result.actor.id),
                        "item_id": result.item.id,
                        "action": result.action.value,
                    }
                    for result in transition.attunement_results
                ],
            },
        )
        self._add_message(
            "Krótki odpoczynek ukończony",
            "Minęła godzina. Gracze mogą teraz wydawać Hit Dice pojedynczo.",
        )
        self.board_message = "Odpoczynek ukończony. Wydaj Hit Dice albo zakończ odpoczynek."
        return self.state_payload()

    def declare_continuation_navigator(self, actor_id: str) -> dict[str, object]:
        """Validate a hero-card declaration for the active travel plan."""

        if self.ui_flow_stage != UiFlowStage.LOCATION_ACTIVE:
            raise ValueError("Wybór prowadzącego nie jest teraz dostępny.")
        if self.pending_short_rest is not None or self.pending is not None:
            raise ValueError("Najpierw zakończ aktywną decyzję albo odpoczynek.")
        if self.active_point is not None:
            raise ValueError("Najpierw zakończ aktywną rozmowę lub interakcję.")
        plan = self.scenario_continuation_flow.plan(
            self.exploration.continuation,
            source_scenario_id=self.exploration.scenario_id,
            flags=self.state.flags,
            current_zone_id=self.current_zone.id,
        )
        policy = plan.continuation.travel_policy
        if policy.navigation_dc is None:
            raise ValueError("Ta podróż nie wymaga wyboru prowadzącego.")
        natural_explorer = next(
            (
                actor
                for actor in self.exploration.actors
                if actor.faction == Faction.ALLY
                and not actor.is_defeated()
                and policy.terrain is not None
                and natural_explorer_terrain(actor) == policy.terrain
            ),
            None,
        )
        if natural_explorer is not None:
            raise ValueError(
                f"{natural_explorer.name} prowadzi automatycznie dzięki Natural Explorer."
            )
        actor = next(
            (
                candidate
                for candidate in self.exploration.actors
                if str(candidate.id) == actor_id
                and candidate.faction == Faction.ALLY
                and not candidate.is_defeated()
            ),
            None,
        )
        if actor is None:
            raise ValueError("Ta postać nie może prowadzić drużyny.")
        self._record(
            "ui_continuation_navigator_declared",
            {
                "actor_id": str(actor.id),
                "continuation_id": plan.continuation.id,
            },
        )
        self.pending_continuation_navigator_actor_id = str(actor.id)
        return {
            "actor_id": str(actor.id),
            "actor_name": actor.name,
            "continuation_id": plan.continuation.id,
            "navigation_dc": policy.navigation_dc,
            "navigation_ability": policy.navigation_ability,
            "navigation_skill": policy.navigation_skill,
        }

    def continue_scenario(
        self,
        *,
        pace: str = TravelPace.NORMAL.value,
        navigator_actor_id: str | None = None,
        navigation_roll: object = None,
        forced_march_rolls: Mapping[str, object] | None = None,
    ) -> dict[str, object]:
        if self.pending_short_rest is not None or self.pending is not None:
            raise ValueError("Najpierw zakończ aktywną decyzję albo odpoczynek.")
        if navigator_actor_id is None:
            navigator_actor_id = self.pending_continuation_navigator_actor_id
        plan = self.scenario_continuation_flow.plan(
            self.exploration.continuation,
            source_scenario_id=self.exploration.scenario_id,
            flags=self.state.flags,
            current_zone_id=self.current_zone.id,
        )
        travel_actors = tuple(
            actor
            for actor in self.exploration.actors
            if actor.faction == Faction.ALLY and not actor.is_defeated()
        )
        travel = resolve_travel(
            plan.continuation,
            travel_actors,
            pace=TravelPace(pace),
            navigator_actor_id=navigator_actor_id,
            navigation_roll=(
                _travel_d20_input(navigation_roll)
                if navigation_roll is not None
                else None
            ),
            navigation_roll_mode=(
                RollMode.ADVANTAGE
                if bool(scene_flag(self.state.flags, "travel_navigation_advantage", False))
                else RollMode.NORMAL
            ),
            navigation_modifier=int(
                scene_flag(self.state.flags, "travel_navigation_modifier", 0) or 0
            ),
            forced_march_rolls={
                str(actor_id): tuple(
                    _travel_d20_input(item)
                    for item in (
                        raw_rolls
                        if isinstance(raw_rolls, list | tuple)
                        else ()
                    )
                )
                for actor_id, raw_rolls in (forced_march_rolls or {}).items()
            },
        )
        traveled_by_id = {str(actor.id): actor for actor in travel.actors}
        self.exploration = replace(
            self.exploration,
            actors=tuple(
                traveled_by_id.get(str(actor.id), actor)
                for actor in self.exploration.actors
            ),
        )
        departure_minute = self.state.elapsed_minutes
        travel_advance = self._advance_scenario_time(
            travel.total_minutes,
            source="scenario_continuation",
        )
        arrival_clock = _scenario_clock_payload(
            self.state.clock_policy.start_hour,
            self.state.elapsed_minutes,
        )
        outcome_resolution = self.scenario_continuation_flow.resolve_outcome(
            plan,
            flags=self.state.flags,
            navigation_succeeded=travel.navigation.success,
        )
        source_objectives = objective_status_after_flags(
            self.exploration.objectives,
            self.state.flags,
        )
        self.finish_scenario(_authored_continuation=True)
        target_path = (
            self.scenario_path.parent
            / plan.continuation.target_scenario_path
        ).resolve()
        self.scenario_handoff = {
            **plan.as_payload(),
            "target_scenario_path": str(target_path),
            "source_snapshot_path": str(self.snapshot_path.resolve()),
            "departure_minute": departure_minute,
            "arrival_minute": self.state.elapsed_minutes,
            "travel_minutes": travel.total_minutes,
            "travel": travel.as_payload(),
            "arrival_clock": arrival_clock,
            "triggered_clock_event_ids": [
                event.id for event in travel_advance.triggered_clock_events
            ],
            "outcome": outcome_resolution.as_payload(),
            "source_objectives": [
                {
                    "id": objective.id,
                    "name": objective.name,
                    "status": objective.status.value,
                }
                for objective in source_objectives
            ],
        }
        write_snapshot(self.snapshot_path, self.create_snapshot())
        self._record(
            "ui_scenario_continuation_ready",
            dict(self.scenario_handoff),
        )
        target_scenario_label = (
            plan.continuation.target_scenario_name
            or plan.continuation.target_scenario_id
        )
        self._add_message(
            "Dalsza droga",
            (
                f"{outcome_resolution.outcome.narration or plan.continuation.description} "
                f"Podróż zajęła "
                f"{travel.total_minutes} min. Stan wioski i drużyny zapisano. "
                f"Kolejna lokacja: {target_scenario_label}."
            ),
        )
        self.board_message = (
            f"Lokacja zakończona. Kolejna lokacja: "
            f"{target_scenario_label}."
        )
        self._sync_board_leds()
        return self.state_payload()

    def start_scenario_handoff(self) -> dict[str, object]:
        if self.ui_flow_stage != UiFlowStage.SCENARIO_COMPLETE:
            raise ValueError("Najpierw zakończ bieżącą lokację.")
        if self.scenario_handoff is None:
            raise ValueError("Zakończony scenariusz nie wskazuje kolejnej sceny.")
        handoff = dict(self.scenario_handoff)
        target_path = Path(str(handoff["target_scenario_path"])).resolve()
        source_party = tuple(
            actor for actor in self.exploration.actors if actor.faction == Faction.ALLY
        )
        source_resources = self.state.inventory_resource_ids
        board_adapter = self.board_adapter
        board_backend = self.board_backend
        board_settings = (
            self.board_url,
            self.board_serial_port,
            self.wled_url,
            self.scan_timeout_s,
        )

        self.scenario_path = target_path
        self.debug_point_id = ""
        self.debug_challenge_id = ""
        self.debug_courtyard_entry = False
        self.reset()

        travel_payload = handoff.get("travel")
        if isinstance(travel_payload, dict):
            pace = str(travel_payload.get("pace", "normal"))
            if pace in {"slow", "normal", "fast"}:
                self.state = replace(
                    self.state,
                    flags=set_scene_flag(
                        self.state.flags,
                        f"travel.pace.{pace}",
                        True,
                    ),
                )

        source_by_id = {str(actor.id): actor for actor in source_party}
        target_party_positions = [
            actor.position
            for actor in self.exploration.actors
            if actor.faction == Faction.ALLY
        ]
        fallback_position = (
            target_party_positions[0]
            if target_party_positions
            else self.exploration.actors[0].position
        )
        merged_actors = []
        merged_ids: set[str] = set()
        for target_actor in self.exploration.actors:
            source_actor = source_by_id.get(str(target_actor.id))
            if source_actor is None:
                merged_actors.append(target_actor)
                continue
            merged_actors.append(merge_handoff_actor(source_actor, target_actor))
            merged_ids.add(str(source_actor.id))
        merged_actors.extend(
            replace(actor, position=fallback_position)
            for actor in source_party
            if str(actor.id) not in merged_ids
        )
        self.exploration = replace(
            self.exploration,
            actors=tuple(merged_actors),
        )

        outcome = handoff.get("outcome")
        if isinstance(outcome, dict):
            for raw_effect in outcome.get("target_effects", ()):
                if not isinstance(raw_effect, dict):
                    continue
                result = apply_exploration_effect(self.state, raw_effect)
                self.state = result.state
                self._record_effect_result(
                    result,
                    source="scenario_handoff",
                    raw_effect=raw_effect,
                )
        arrival_clock = handoff.get("arrival_clock")
        if isinstance(arrival_clock, dict):
            arrival_hour = int(arrival_clock.get("hour", 0))
            arrival_minute = int(arrival_clock.get("minute", 0))
            elapsed_minutes = (
                arrival_hour * 60
                + arrival_minute
                - self.state.clock_policy.start_hour * 60
            ) % (24 * 60)
            self.state = replace(self.state, elapsed_minutes=elapsed_minutes)
        self.state = replace(
            self.state,
            inventory_resource_ids=tuple(
                dict.fromkeys((*self.state.inventory_resource_ids, *source_resources))
            ),
        )

        self.board_adapter = board_adapter
        self.board_backend = board_backend
        (
            self.board_url,
            self.board_serial_port,
            self.wled_url,
            self.scan_timeout_s,
        ) = board_settings
        if board_adapter is not None and board_backend in {"simulator", "hardware"}:
            self.ui_flow_stage = UiFlowStage.READY_TO_START
            self.board_message = (
                f"Plansza nadal podłączona: {board_backend}. "
                "Rozpocznij setup kolejnej papierowej mapy."
            )
        self.selected_lead_actor_id = str(
            next(
                actor
                for actor in self.exploration.actors
                if actor.faction == Faction.ALLY
            ).id
        )
        handoff["applied"] = True
        self.scenario_handoff = handoff
        self._record(
            "ui_scenario_handoff_applied",
            {
                "source_scenario_id": handoff["source_scenario_id"],
                "target_scenario_id": self.exploration.scenario_id,
                "party_actor_ids": [
                    str(actor.id)
                    for actor in self.exploration.actors
                    if actor.faction == Faction.ALLY
                ],
                "elapsed_minutes": self.state.elapsed_minutes,
            },
        )
        write_snapshot(self.snapshot_path, self.create_snapshot())
        self._sync_board_leds()
        return self.state_payload()

    def finish_scenario(
        self,
        *,
        _authored_continuation: bool = False,
    ) -> dict[str, object]:
        if self.combat_state is not None:
            raise ValueError("Najpierw zakończ aktywną walkę.")
        if self.pending_short_rest is not None or self.pending is not None:
            raise ValueError("Najpierw zakończ aktywną decyzję albo odpoczynek.")
        if self.ui_flow_stage == UiFlowStage.SCENARIO_COMPLETE:
            return self.state_payload()
        if self.exploration.continuation is not None and not _authored_continuation:
            raise ValueError(
                "Ten scenariusz ma autorskie wyjście. Ukończ cel i wyrusz "
                "wskazaną drogą."
            )
        if self.ui_flow_stage not in {
            UiFlowStage.LOCATION_ACTIVE,
            UiFlowStage.INTERACTION_RESULT,
        }:
            raise ValueError("Scenariusz można zakończyć dopiero podczas aktywnej eksploracji.")
        expiration = expire_active_effects(
            self.active_combat_effects,
            EffectEvent(EffectEventType.SCENARIO_ENDED),
        )
        self.active_combat_effects = expiration.active_effects
        self.state, condition_expiration = expire_exploration_conditions(
            self.state,
            EffectEvent(EffectEventType.SCENARIO_ENDED),
        )
        self._add_expired_condition_notices(
            condition_expiration.expired_conditions,
            prefix="Koniec scenariusza usuwa stan",
        )
        self.active_preparation_effects.clear()
        expired_temporary_items = tuple(item.id for item in self.state.temporary_items if item.available)
        self.state = replace(self.state, temporary_items=())
        self.pending_encounter = None
        self.ui_flow_stage = UiFlowStage.SCENARIO_COMPLETE
        self.board_message = "Scenariusz zakończony. Efekty dzienne wygasły."
        self._record(
            "ui_scenario_completed",
            {
                "elapsed_minutes": self.state.elapsed_minutes,
                "expired_effect_ids": [effect.id for effect in expiration.expired_effects],
                "expired_conditions": [
                    {
                        "actor_id": condition.actor_id,
                        "condition": condition.condition.value,
                    }
                    for condition in condition_expiration.expired_conditions
                ],
                "expired_temporary_item_ids": list(expired_temporary_items),
            },
        )
        self._add_message(
            "Scenariusz zakończony",
            "Efekty trwające do końca scenariusza wygasły. Reset rozpocznie kolejny scenariusz automatycznym long restem.",
        )
        self._sync_board_leds()
        return self.state_payload()

    def spend_short_rest_hit_die(
        self,
        *,
        actor_id: str,
        die_sides: int,
        natural_roll: int,
        song_of_rest_roll: int | None = None,
    ) -> dict[str, object]:
        pending = self.pending_short_rest
        if (
            self.ui_flow_stage != UiFlowStage.SHORT_REST
            or pending is None
            or not pending.completed
        ):
            raise ValueError("Hit Dice można wydawać dopiero po ukończeniu short resta.")
        bard = next(
            (
                actor
                for actor in self.exploration.actors
                if actor.faction == Faction.ALLY
                and actor_has_feature(actor, "song_of_rest")
            ),
            None,
        )
        if (
            song_of_rest_roll is not None
            and actor_id in pending.song_of_rest_used_actor_ids
        ):
            raise ValueError("Ten bohater wykorzystał już Song of Rest podczas tego odpoczynku.")
        transition = self.short_rest_flow.spend_hit_die(
            actors=self.exploration.actors,
            actor_id=actor_id,
            die_sides=die_sides,
            natural_roll=natural_roll,
            song_of_rest_roll=song_of_rest_roll,
            song_of_rest_die_sides=(
                song_of_rest_die_sides(bard) if bard is not None else 0
            ),
            song_of_rest_bard_id=str(bard.id) if bard is not None else None,
        )
        self.exploration = replace(self.exploration, actors=transition.actors)
        if song_of_rest_roll is not None:
            self.pending_short_rest = replace(
                pending,
                song_of_rest_used_actor_ids=(
                    *pending.song_of_rest_used_actor_ids,
                    actor_id,
                ),
            )
        result = transition.result
        self._record(
            "ui_short_rest_hit_die_spent",
            {
                "actor_id": actor_id,
                "die_sides": die_sides,
                "natural_roll": natural_roll,
                "constitution_modifier": result.constitution_modifier,
                "effective_healing": result.effective_healing,
                "song_of_rest_healing": transition.song_of_rest_healing,
            },
        )
        self._add_message(
            "Wydana Hit Die",
            (
                f"{result.actor_after.name}: d{die_sides} {natural_roll}, "
                f"CON {_format_signed(result.constitution_modifier)}, "
                f"odzyskano {result.effective_healing} HP"
                + (
                    f" oraz {transition.song_of_rest_healing} HP z Song of Rest."
                    if transition.song_of_rest_bard_id is not None
                    else "."
                )
            ),
        )
        return self.state_payload()

    def recover_short_rest_spell_slots(
        self,
        *,
        actor_id: str,
        slot_levels: tuple[int, ...],
    ) -> dict[str, object]:
        pending = self.pending_short_rest
        if (
            self.ui_flow_stage != UiFlowStage.SHORT_REST
            or pending is None
            or not pending.completed
        ):
            raise ValueError("Odzyskiwanie slotów jest dostępne po ukończeniu short resta.")
        actor = next(
            (
                candidate
                for candidate in self.exploration.actors
                if str(candidate.id) == actor_id
            ),
            None,
        )
        if actor is None or actor.faction != Faction.ALLY:
            raise ValueError("Nieznany bohater odpoczynku.")
        updated = apply_short_rest_slot_recovery(
            actor,
            slot_levels=tuple(int(level) for level in slot_levels),
        )
        self.exploration = replace(
            self.exploration,
            actors=tuple(
                updated if candidate.id == actor.id else candidate
                for candidate in self.exploration.actors
            ),
        )
        self._record(
            "ui_short_rest_spell_slots_recovered",
            {
                "actor_id": actor_id,
                "slot_levels": list(slot_levels),
            },
        )
        self._add_message(
            "Odzyskanie slotów",
            (
                f"{actor.name} odzyskuje sloty: "
                + ", ".join(f"{level}. poziom" for level in slot_levels)
                + "."
            ),
        )
        return self.state_payload()

    def cancel_short_rest(self) -> dict[str, object]:
        pending = self.pending_short_rest
        if self.ui_flow_stage != UiFlowStage.SHORT_REST or pending is None:
            raise ValueError("Brak krótkiego odpoczynku do anulowania.")
        if pending.completed:
            raise ValueError("Ukończonego odpoczynku nie można anulować.")
        self.pending_short_rest = None
        self.state = replace(
            self.state,
            flags=set_scene_flag(self.state.flags, "short_rest_alarm_active", False),
        )
        self.ui_flow_stage = UiFlowStage.LOCATION_ACTIVE
        self.board_message = "Krótki odpoczynek anulowany bez upływu czasu."
        self._record("ui_short_rest_cancelled", {"policy_id": pending.policy.id})
        return self.state_payload()

    def finish_short_rest(self) -> dict[str, object]:
        pending = self.pending_short_rest
        if (
            self.ui_flow_stage != UiFlowStage.SHORT_REST
            or pending is None
            or not pending.completed
        ):
            raise ValueError("Najpierw ukończ krótki odpoczynek.")
        self.pending_short_rest = None
        self.ui_flow_stage = UiFlowStage.LOCATION_ACTIVE
        self._refresh_pending_encounter()
        if self.pending_encounter is None:
            self.state = replace(
                self.state,
                flags=set_scene_flag(
                    self.state.flags,
                    "short_rest_alarm_active",
                    False,
                ),
            )
        self.board_message = "Krótki odpoczynek zakończony. Drużyna wraca do eksploracji."
        self._record("ui_short_rest_finished", {"policy_id": pending.policy.id})
        return self.state_payload()

    def start_session(self) -> dict[str, object]:
        paper_map_step = _paper_map_setup_step(self.current_zone)
        setup_steps = (
            ((paper_map_step,) if paper_map_step is not None else ())
            + _build_exploration_setup_steps(self.exploration.environment)
        )
        transition = self.exploration_flow.start_session(
            board_connected=self.board_adapter is not None,
            board_backend=self.board_backend,
            current_stage=self.ui_flow_stage,
            setup_steps=setup_steps,
            spell_preparation_pending=bool(
                self.spell_preparation_flow.pending_actors(self.exploration.actors)
            ),
        )
        if transition is None:
            return self.state_payload()
        self.exploration_setup_flow = (
            ExplorationSetupFlow(
                transition.setup_steps,
                paper_map=self.current_zone.paper_map,
                paper_map_step_index=0 if paper_map_step is not None else -1,
            )
            if transition.setup_steps
            else None
        )
        self.exploration_setup_is_initial = bool(transition.setup_steps)
        self.ui_flow_stage = UiFlowStage(transition.stage.value)
        self.board_message = transition.board_message
        self.preview_zone_id = ""
        self.pending = None
        self.active_point_id = ""
        self._sync_board_leds()
        self._record("ui_play_session_started", {"stage": self.ui_flow_stage.value, "board_backend": self.board_backend})
        return self.state_payload()

    def finish_interaction_result(self) -> dict[str, object]:
        transition = self.exploration_flow.finish_interaction(
            current_stage=self.ui_flow_stage,
            post_interaction_setup_steps=self.post_interaction_setup_steps,
        )
        if transition is None:
            return self.state_payload()
        self.interaction_result = None
        self.preview_zone_id = ""
        self.exploration_setup_flow = (
            ExplorationSetupFlow(transition.setup_steps) if transition.setup_steps else None
        )
        self.exploration_setup_is_initial = False
        self.post_interaction_setup_steps = ()
        self.ui_flow_stage = transition.stage
        self.exploration_board_selection_active = False
        self.board_message = transition.board_message
        self._sync_board_leds()
        return self.state_payload()

    def cancel_location_preview(self) -> dict[str, object]:
        transition = self.exploration_flow.cancel_location_preview(current_stage=self.ui_flow_stage)
        if transition is None:
            return self.state_payload()
        self.preview_zone_id = transition.preview_zone_id
        self.board_message = transition.board_message
        self._sync_board_leds()
        return self.state_payload()

    def confirm_location_preview(self) -> dict[str, object]:
        previous_zone_id = self.current_zone.id
        transition = self.exploration_flow.confirm_location_preview(
            current_stage=self.ui_flow_stage,
            state=self.state,
            current_zone=self.current_zone,
            preview_zone=self._preview_zone(),
            active_point_id=self.active_point_id,
        )
        if transition is None:
            return self.state_payload()
        self.state = transition.state
        self.ui_flow_stage = transition.stage
        self.preview_zone_id = transition.preview_zone_id
        self.active_point_id = transition.active_point_id
        self.exploration_board_selection_active = False
        self.board_message = transition.board_message
        if transition.event_type:
            self._record(transition.event_type, dict(transition.event_payload))
        paper_map_setup_started = (
            self.current_zone.id != previous_zone_id
            and self._begin_current_zone_paper_map_setup()
        )
        if (
            self.ui_flow_stage == UiFlowStage.LOCATION_ACTIVE
            and not paper_map_setup_started
        ):
            self._detect_passive_traps()
            self._queue_current_zone_npc_setup()
        self._sync_board_leds()
        return self.state_payload()

    def confirm_exploration_setup_step(self) -> dict[str, object]:
        if self.exploration_setup_flow is None:
            return self.state_payload()
        flow = self.exploration_setup_flow
        confirmed_paper_map_id = (
            flow.paper_map.id
            if flow.paper_map is not None
            and flow.current_index == flow.paper_map_step_index
            else ""
        )
        if flow.assignment_point_id and flow.assigned_position is None:
            raise ValueError(
                f"Najpierw ustaw figurkę: {flow.assignment_point_name} na jednym z podświetlonych pól."
            )
        transition = self.exploration_flow.advance_setup_step(
            steps=flow.steps,
            current_index=flow.current_index,
            spell_preparation_pending=bool(
                self.exploration_setup_is_initial
                and self.spell_preparation_flow.pending_actors(self.exploration.actors)
            ),
        )
        if transition is None:
            return self.state_payload()
        if confirmed_paper_map_id:
            self.active_paper_map_id = confirmed_paper_map_id
        self._add_message("Setup mapy", f"Potwierdzono: {transition.confirmed_label}.")
        if transition.completed:
            flow.completed = True
            self.exploration_setup_flow = None
            self.exploration_setup_is_initial = False
            completed_stage = (
                UiFlowStage.LOCATION_ACTIVE
                if flow.return_to_location_active
                else transition.stage
            )
            if (
                completed_stage == UiFlowStage.LOCATION_PREVIEW
                and self.current_zone.activate_after_setup
            ):
                completed_stage = UiFlowStage.LOCATION_ACTIVE
            self.ui_flow_stage = completed_stage
            self.preview_zone_id = ""
            self.board_message = (
                f"Figurka {flow.assignment_point_name} jest ustawiona. "
                f"Wybierzcie działanie w lokacji: {self.current_zone.name}."
                if flow.return_to_location_active and flow.assignment_point_name
                else (
                    f"Mapa gotowa. Wybierzcie jeden z podświetlonych hotspotów "
                    f"lokacji: {self.current_zone.name}. Pierwsze kliknięcie pokazuje "
                    "podgląd, a drugie kliknięcie tego samego pola potwierdza wybór."
                )
                if self.ui_flow_stage == UiFlowStage.LOCATION_ACTIVE
                else transition.board_message
            )
            self._refresh_pending_encounter()
            if self.pending_encounter is not None:
                trigger = self._trigger_by_id(self.pending_encounter.trigger_id)
                self.board_message = (
                    "Encounter gotowy. Rozstrzygnij rozpoczęcie starcia w UI albo Enterem."
                    if trigger is not None and trigger.opening_policy is not None
                    else "Encounter gotowy. Potwierdź rozpoczęcie setupu w UI albo Enterem."
                )
            if self.ui_flow_stage == UiFlowStage.LOCATION_ACTIVE:
                self._detect_passive_traps()
            if self.ui_flow_stage in {
                UiFlowStage.LOCATION_ACTIVE,
                UiFlowStage.LOCATION_PREVIEW,
            }:
                self._queue_current_zone_npc_setup()
        else:
            flow.current_index = transition.current_index
            self.ui_flow_stage = transition.stage
            self.board_message = transition.board_message
        self._sync_board_leds()
        return self.state_payload()

    def _begin_current_zone_paper_map_setup(self) -> bool:
        step = _paper_map_setup_step(self.current_zone)
        paper_map = self.current_zone.paper_map
        if (
            step is None
            or paper_map is None
            or paper_map.id == self.active_paper_map_id
        ):
            return False
        self.exploration_setup_flow = ExplorationSetupFlow(
            (step,),
            return_to_location_active=True,
            paper_map=self.current_zone.paper_map,
            paper_map_step_index=0,
        )
        self.ui_flow_stage = UiFlowStage.PARTY_SETUP
        self.board_message = (
            f"Rozłóż papierową mapę lokacji: {self.current_zone.name}, "
            "a następnie potwierdź setup."
        )
        self._add_message(
            "Zmiana papierowej mapy",
            (
                f"Przed dalszą grą rozłóżcie mapę „{self.current_zone.name}” "
                "na całej fizycznej planszy."
            ),
        )
        return True

    def _queue_current_zone_npc_setup(self) -> None:
        if self.ui_flow_stage not in {
            UiFlowStage.LOCATION_ACTIVE,
            UiFlowStage.LOCATION_PREVIEW,
        }:
            return
        point = next(
            (
                candidate
                for candidate in self.current_zone_points()
                if candidate.npc_interaction is not None
                and candidate.requires_setup
                and not bool(scene_flag(self.state.flags, _point_setup_flag(candidate.id), False))
            ),
            None,
        )
        if point is None:
            return
        step = SetupStep(
            kind=SetupStepKind.ENVIRONMENT,
            label=point.name,
            positions=point.positions,
            color=point.color,
            message=(
                f"W lokacji „{self.current_zone.name}” pojawia się punkt: "
                f"„{point.name}”. Ustaw figurkę na jednym z podświetlonych pól "
                "i potwierdź pozycję kliknięciem."
            ),
            visibility=SetupVisibility.VISIBLE,
        )
        self.exploration_setup_flow = ExplorationSetupFlow(
            (step,),
            assignment_point_id=point.id,
            assignment_point_name=point.name,
            return_to_location_active=True,
        )
        self.ui_flow_stage = UiFlowStage.PARTY_SETUP
        self.board_message = (
            f"Ustaw figurkę {point.name} w lokacji {self.current_zone.name} "
            "na jednym z podświetlonych pól."
        )
        npc_description = (
            point.npc_interaction.public_description
            if point.npc_interaction is not None
            else point.description
        )
        self._add_message(
            self.current_zone.name,
            (
                f"{self.current_zone.description} "
                f"{self.current_zone.llm_context.summary} "
                f"{npc_description}"
            ).strip(),
        )
        self._add_message(
            "Setup punktu eksploracji",
            (
                f"Postaw figurkę „{point.name}” na jednym z podświetlonych pól. "
                "Kliknięcie wybranego pola zapisze pozycję punktu i odblokuje "
                f"działania w lokacji {self.current_zone.name}."
            ),
        )
        self._record(
            "ui_exploration_point_setup_started",
            {
                "point_id": point.id,
                "candidate_positions": [position.as_tuple() for position in point.positions],
            },
        )

    def _prepare_debug_courtyard_entry(self) -> None:
        courtyard = next(zone for zone in self.state.zones if zone.id == "courtyard")
        flags = set_scene_flag(self.state.flags, "gate_passed", True)
        flags = set_scene_flag(flags, "gate_skirmish_cleared", True)
        self.state = replace(
            self.state,
            party_position=PartyPosition(courtyard.id),
            flags=flags,
        )
        self.state, _ = reveal_exploration_points(self.state, ("wounded_scout",))
        self.resolved_encounter_trigger_ids.add("gate_open_skirmish")
        self.active_point_id = ""
        self.preview_zone_id = ""
        self.ui_flow_stage = UiFlowStage.LOCATION_ACTIVE
        self.messages.clear()
        self._queue_current_zone_npc_setup()

    def assign_exploration_point_position(self, position: Coordinate) -> dict[str, object]:
        flow = self.exploration_setup_flow
        if flow is None or not flow.assignment_point_id:
            raise ValueError("Aktualny setup nie oczekuje ustawienia punktu eksploracji.")
        step = flow.current_step
        if step is None or position not in step.positions:
            raise ValueError("Wybierz jedno z podświetlonych pól dla figurki NPC.")
        point = next(
            (candidate for candidate in self.state.points if candidate.id == flow.assignment_point_id),
            None,
        )
        if point is None:
            raise ValueError("Nie znaleziono ustawianego punktu eksploracji.")
        self.state = replace(
            self.state,
            points=tuple(
                replace(candidate, positions=(position,))
                if candidate.id == point.id
                else candidate
                for candidate in self.state.points
            ),
            flags=set_scene_flag(self.state.flags, _point_setup_flag(point.id), True),
        )
        flow.assigned_position = position
        self.board_message = f"Ustawiono figurkę {point.name} na polu {position.as_tuple()}."
        self._record(
            "ui_exploration_point_setup_assigned",
            {"point_id": point.id, "position": position.as_tuple()},
        )
        return self.confirm_exploration_setup_step()

    def scan_board_selection(
        self,
        *,
        expected_revision: str = "",
        automatic: bool = False,
    ) -> dict[str, object]:
        if not self._board_scan_lock.acquire(blocking=False):
            self._record(
                "ui_board_scan_duplicate_ignored",
                {
                    "expected_revision": expected_revision,
                    "automatic": automatic,
                },
            )
            return self.state_payload()
        try:
            return self._scan_board_selection_locked(
                expected_revision=expected_revision,
                automatic=automatic,
            )
        finally:
            self._board_scan_lock.release()

    def _scan_board_selection_locked(
        self,
        *,
        expected_revision: str,
        automatic: bool,
    ) -> dict[str, object]:
        if self.board_adapter is None:
            raise ValueError("Najpierw podłącz backend planszy.")
        selection = self._board_selection_payload()
        revision = str(selection["revision"])
        if expected_revision and expected_revision != revision:
            self._record(
                "ui_board_scan_stale_before_start",
                {
                    "expected_revision": expected_revision,
                    "current_revision": revision,
                    "automatic": automatic,
                },
            )
            return self.state_payload()
        target = self._current_board_scan_target()
        if not target.positions:
            raise ValueError(target.empty_message)
        started_at = time.monotonic()
        self._record(
            "ui_board_scan_started",
            {
                "stage": self.ui_flow_stage.value,
                "revision": revision,
                "automatic": automatic,
                "position_count": len(target.positions),
                "frames": [
                    {
                        "positions": [
                            [position.col, position.row]
                            for position in frame.positions
                        ],
                        "rgb": list(frame.color),
                        "color_name": led_color_name_pl(frame.color),
                        "role": frame.role.value,
                    }
                    for frame in target.feedback.frames
                ],
            },
        )
        self.board_adapter.show_scan_feedback(target.feedback)
        try:
            selected_raw = self.board_adapter.scan(
                target.positions,
                timeout_s=self.scan_timeout_s,
            )
        except TimeoutError as exc:
            elapsed_ms = round((time.monotonic() - started_at) * 1000)
            self.board_message = (
                "Plansza nie odpowiedziała w wyznaczonym czasie. "
                "Zresetowano nasłuchiwanie; spróbuj ponownie."
            )
            reset_action = ""
            reset_error = ""
            try:
                reset_action = self.board_adapter.reset_scan()
            except Exception as reset_exc:
                reset_error = str(reset_exc)
            self._record(
                "ui_board_scan_timeout",
                {
                    "stage": self.ui_flow_stage.value,
                    "revision": revision,
                    "automatic": automatic,
                    "elapsed_ms": elapsed_ms,
                    "error": str(exc),
                    "reset_action": reset_action,
                    "reset_error": reset_error,
                },
            )
            raise
        finally:
            self.board_adapter.restore_feedback(
                self._current_board_scan_target().feedback
            )
        if selected_raw is None:
            current_revision = str(self._board_selection_payload()["revision"])
            if current_revision != revision:
                self._record(
                    "ui_board_scan_stale_after_cancel",
                    {
                        "scan_revision": revision,
                        "current_revision": current_revision,
                        "automatic": automatic,
                        "elapsed_ms": round(
                            (time.monotonic() - started_at) * 1000
                        ),
                    },
                )
                return self.state_payload()
            self.board_message = "Nie wybrano pola na planszy."
            self._record(
                "ui_board_scan_cancelled",
                {
                    "stage": self.ui_flow_stage.value,
                    "revision": revision,
                    "automatic": automatic,
                    "elapsed_ms": round(
                        (time.monotonic() - started_at) * 1000
                    ),
                },
            )
            return self.state_payload()
        selected = _coordinate_from_scan(selected_raw)
        current_revision = str(self._board_selection_payload()["revision"])
        elapsed_ms = round((time.monotonic() - started_at) * 1000)
        if current_revision != revision:
            self._record(
                "ui_board_scan_stale_after_receive",
                {
                    "scan_revision": revision,
                    "current_revision": current_revision,
                    "automatic": automatic,
                    "position": [selected.col, selected.row],
                    "elapsed_ms": elapsed_ms,
                },
            )
            return self.state_payload()
        self._record(
            "ui_board_scan_received",
            {
                "stage": self.ui_flow_stage.value,
                "revision": revision,
                "automatic": automatic,
                "position": [selected.col, selected.row],
                "elapsed_ms": elapsed_ms,
            },
        )
        return self._handle_board_position(selected)

    def set_exploration_board_selection(self, enabled: bool) -> dict[str, object]:
        if self.ui_flow_stage != UiFlowStage.LOCATION_ACTIVE or self.combat_state is not None:
            raise ValueError("Wybór elementów eksploracji nie jest teraz dostępny.")
        self.exploration_board_selection_active = bool(enabled)
        self.board_selected_goal_id = ""
        self.board_selected_panel = ""
        self.board_selected_action_kind = ""
        self.board_selected_action_id = ""
        self.board_selected_action_confirmed = False
        self.board_actor_selection = None
        self.board_selected_actor_id = ""
        self.board_selected_actor_role = ""
        self.board_message = (
            "Tryb podróży aktywny. Uruchom skan i kliknij znacznik podświetlonej lokacji."
            if self.exploration_board_selection_active
            else "Tryb interakcji aktywny. Numer i kolor pola na planszy odpowiadają kafelkowi w panelu."
        )
        self._sync_board_leds()
        return self.state_payload()

    def clear_board_interaction_selection(self) -> dict[str, object]:
        had_selection = bool(
            self.board_selected_goal_id
            or self.board_selected_panel
            or self.board_selected_action_id
            or self.board_actor_selection is not None
            or self.board_selected_actor_id
        )
        self.board_selected_goal_id = ""
        self.board_selected_panel = ""
        self.board_selected_action_kind = ""
        self.board_selected_action_id = ""
        self.board_selected_action_confirmed = False
        self.board_actor_selection = None
        self.board_selected_actor_id = ""
        self.board_selected_actor_role = ""
        if had_selection:
            self.board_selection_revision += 1
            self._record(
                "ui_board_interaction_selection_cleared",
                {"selection_revision": self.board_selection_revision},
            )
        self._sync_board_leds()
        return self.state_payload()

    def start_exploration_actor_selection(
        self,
        *,
        goal_id: str,
        role: str = "lead",
        excluded_actor_ids: tuple[str, ...] = (),
    ) -> dict[str, object]:
        if self.ui_flow_stage != UiFlowStage.LOCATION_ACTIVE or self.combat_state is not None:
            raise ValueError("Wybór bohatera nie jest teraz dostępny.")
        if role not in {"lead", "helper"}:
            raise ValueError("Nieznana rola bohatera w teście.")
        goal = self._current_interaction_goal_payload(goal_id)
        eligible_ids = {
            str(actor_id) for actor_id in goal.get("eligible_actor_ids", ())
        }
        excluded_ids = {str(actor_id) for actor_id in excluded_actor_ids}
        actors = tuple(
            actor
            for actor in self._party_actors()
            if str(actor.id) in eligible_ids
            and str(actor.id) not in excluded_ids
            and not actor.is_defeated()
        )
        if not actors:
            raise ValueError("Żaden bohater nie spełnia wymagań tej próby.")
        self.board_selected_goal_id = goal_id
        self.board_selected_actor_id = ""
        self.board_selected_actor_role = ""
        self.board_actor_selection = BoardActorSelection(
            goal_id=goal_id,
            role=role,
            eligible_actor_ids=tuple(str(actor.id) for actor in actors),
        )
        self.board_selection_revision += 1
        self.board_message = (
            "Zeskanuj kartę bohatera, który pomaga w teście."
            if role == "helper"
            else "Zeskanuj kartę bohatera, który wykonuje test."
        )
        self._record(
            "ui_exploration_actor_board_selection_started",
            {
                "goal_id": goal_id,
                "role": role,
                "eligible_actor_ids": list(self.board_actor_selection.eligible_actor_ids),
                "selection_revision": self.board_selection_revision,
            },
        )
        self._sync_board_leds()
        return self.state_payload()

    def select_exploration_actor(
        self,
        *,
        goal_id: str,
        actor_id: str,
        role: str = "lead",
    ) -> dict[str, object]:
        goal = self._current_interaction_goal_payload(goal_id)
        if role == "whole_party":
            allowed = tuple(
                str(option)
                for option in goal.get("allowed_check_participants", ())
            )
            if (
                str(goal.get("check_participants", "")) != "whole_party"
                and "whole_party" not in allowed
            ):
                raise ValueError("To działanie nie pozwala na test całej drużyny.")
            self.board_selected_goal_id = goal_id
            self.board_actor_selection = None
            self.board_selected_actor_id = ""
            self.board_selected_actor_role = "whole_party"
            self.board_selection_revision += 1
            self.board_message = "Wybrano test całej drużyny."
            self._sync_board_leds()
            return self.state_payload()
        eligible_ids = {
            str(candidate) for candidate in goal.get("eligible_actor_ids", ())
        }
        actor = next(
            (
                candidate
                for candidate in self._party_actors()
                if str(candidate.id) == actor_id
                and str(candidate.id) in eligible_ids
                and not candidate.is_defeated()
            ),
            None,
        )
        if actor is None:
            raise ValueError("Ta postać nie może wykonać wybranej próby.")
        if role not in {"lead", "helper"}:
            raise ValueError("Nieznana rola bohatera w teście.")
        self.board_selected_goal_id = goal_id
        next_selection: BoardActorSelection | None = None
        if role == "lead":
            participant_options = {
                str(option)
                for option in goal.get("allowed_check_participants", ())
            }
            if (
                str(goal.get("check_participants", "")) == "lead_with_help"
                or "lead_with_help" in participant_options
            ):
                helper_ids = tuple(
                    str(candidate.id)
                    for candidate in self._party_actors()
                    if str(candidate.id) in eligible_ids
                    and str(candidate.id) != actor_id
                    and not candidate.is_defeated()
                )
                if helper_ids:
                    next_selection = BoardActorSelection(
                        goal_id=goal_id,
                        role="helper",
                        eligible_actor_ids=helper_ids,
                    )
        self.board_actor_selection = next_selection
        self.board_selected_actor_id = actor_id
        self.board_selected_actor_role = role
        self.board_selection_revision += 1
        self.board_message = (
            f"{actor.name} pomaga w teście."
            if role == "helper"
            else (
                f"{actor.name} prowadzi. Zeskanuj kartę pomocnika albo ACCEPT, "
                "aby przejść dalej bez pomocy."
                if next_selection is not None
                else f"{actor.name} wykonuje test i ponosi jego konsekwencje."
            )
        )
        self._record(
            "ui_exploration_actor_selected",
            {
                "goal_id": goal_id,
                "actor_id": actor_id,
                "role": role,
                "selection_revision": self.board_selection_revision,
            },
        )
        self._sync_board_leds()
        return self.state_payload()

    def _current_interaction_goal_payload(self, goal_id: str) -> dict[str, object]:
        goals: tuple[dict[str, object], ...] = ()
        if self.active_point is not None:
            point_payload = _point_payload(
                self.active_point,
                _npc_state_for_point(self.state, self.active_point),
                self.state.flags,
                self.exploration.flows,
                self.exploration.actors,
            )
            npc_payload = point_payload.get("npc") if point_payload else None
            if isinstance(npc_payload, dict):
                goals = tuple(
                    goal
                    for goal in npc_payload.get("goals", ())
                    if isinstance(goal, dict)
                )
        elif self.active_challenge is not None:
            challenge_payload = _challenge_payload(
                self.state,
                self.active_challenge,
                self.exploration.actors,
                self.exploration.flows,
                self.exploration_interaction_flow,
            )
            goals = tuple(
                goal
                for goal in (challenge_payload or {}).get("goals", ())
                if isinstance(goal, dict)
            )
        goal = next(
            (candidate for candidate in goals if str(candidate.get("id")) == goal_id),
            None,
        )
        if goal is None:
            raise ValueError("Wybrane działanie nie jest już dostępne.")
        if "eligible_actor_ids" not in goal:
            goal = {
                **goal,
                "eligible_actor_ids": [
                    str(actor.id)
                    for actor in self._party_actors()
                    if not actor.is_defeated()
                ],
            }
        return goal

    def _party_actors(self) -> tuple[Actor, ...]:
        return tuple(
            actor
            for actor in self.exploration.actors
            if actor.faction == Faction.ALLY
        )

    def set_exploration_lead_actor(self, actor_id: str) -> dict[str, object]:
        actor = next(
            (
                candidate
                for candidate in self.exploration.actors
                if str(candidate.id) == actor_id
                and candidate.faction == Faction.ALLY
                and not candidate.is_defeated()
            ),
            None,
        )
        if actor is None:
            raise ValueError("Ta postać nie może teraz prowadzić interakcji.")
        self.selected_lead_actor_id = actor_id
        self.board_message = (
            f"{actor.name} prowadzi testy i ponosi konsekwencje wyborów z planszy."
        )
        return self.state_payload()

    def select_board_position(self, selected: Coordinate) -> dict[str, object]:
        target = self._current_board_scan_target()
        if target.positions and selected not in target.positions:
            raise ValueError("Wybrane pole nie jest teraz aktywnym polem planszy.")
        self._record("ui_board_position_selected", {"stage": self.ui_flow_stage.value, "position": [selected.col, selected.row]})
        return self._handle_board_position(selected)

    def submit_action(
        self,
        text: str,
        *,
        selected_goal_id: str | None = None,
        selected_check_participants: str | None = None,
        participant_actor_ids: tuple[str, ...] = (),
        selected_social_skill: str | None = None,
        selected_action_source_id: str | None = None,
        conversation_only: bool = False,
    ) -> dict[str, object]:
        if self.ui_flow_stage != UiFlowStage.LOCATION_ACTIVE:
            raise ValueError("Najpierw rozpocznij sesję i potwierdź wejście do lokacji na planszy.")
        if self.pending is not None:
            raise ValueError(
                "Najpierw rozstrzygnij widoczną decyzję, pułapkę albo rzut. "
                "Nowa deklaracja nie została wysłana."
            )
        raw_text = text.strip()
        if not raw_text:
            raise ValueError("Deklaracja nie może być pusta.")
        parsed_input = parse_player_input(raw_text)
        if conversation_only and (
            selected_goal_id is not None
            or selected_check_participants is not None
            or participant_actor_ids
            or selected_social_skill is not None
            or selected_action_source_id is not None
        ):
            raise ValueError("Swobodna wiadomość do MG nie może jednocześnie deklarować akcji.")
        point = self.active_point
        if selected_social_skill is not None and (
            point is None or point.npc_interaction is None
        ):
            raise ValueError(
                "Podejście społeczne można wybrać tylko w interakcji z NPC."
            )
        available_goals = (
            self.npc_goal_execution.available_goals(
                npc=point.npc_interaction,
                flows=self.exploration.flows,
                flags=self.state.flags,
                actors=self.exploration.actors,
            )
            if point is not None and point.npc_interaction is not None
            else self.active_challenge.goals
            if self.active_challenge is not None
            else ()
        )
        selected_goal_execution: ExplorationGoalExecutionPlan | None = None
        selected_npc_execution: NpcGoalExecutionPlan | None = None
        if self.active_challenge is not None and (
            point is None or point.npc_interaction is None
        ):
            selected_goal_execution = (
                self.exploration_goal_execution.plan(
                    challenge=self.active_challenge,
                    flows=self.exploration.flows,
                    flags=self.state.flags,
                    actors=self.exploration.actors,
                    goal_id=selected_goal_id,
                    requested_check_participants=selected_check_participants,
                    requested_actor_ids=participant_actor_ids,
                )
                if selected_goal_id is not None
                else None
            )
            selected_goal = (
                selected_goal_execution.route.goal
                if selected_goal_execution is not None
                else None
            )
        elif point is not None and point.npc_interaction is not None:
            selected_npc_execution = (
                self.npc_goal_execution.plan(
                    npc=point.npc_interaction,
                    flows=self.exploration.flows,
                    flags=self.state.flags,
                    actors=self.exploration.actors,
                    goal_id=selected_goal_id,
                    requested_check_participants=selected_check_participants,
                    requested_actor_ids=participant_actor_ids,
                )
                if selected_goal_id is not None
                else None
            )
            selected_goal = (
                selected_npc_execution.route.goal
                if selected_npc_execution is not None
                else None
            )
        else:
            selected_goal = interaction_goal(
                available_goals,
                selected_goal_id,
                self.state.flags,
            )
        if selected_goal_id and selected_goal is None:
            raise ValueError("Wybrany cel nie jest dostępny w tej interakcji.")
        selected_participant_ids: tuple[str, ...] = ()
        resolved_check_participants: CheckParticipants | None = None
        if selected_goal_execution is not None:
            resolved_check_participants = (
                selected_goal_execution.check_participants
            )
            selected_participant_ids = (
                selected_goal_execution.participant_actor_ids
            )
        elif selected_npc_execution is not None:
            resolved_check_participants = selected_npc_execution.check_participants
            selected_participant_ids = selected_npc_execution.participant_actor_ids
        elif participant_actor_ids:
            raise ValueError("Postacie można wskazać dopiero po wybraniu celu wyzwania.")
        action_source = (
            selected_action_source(
                self.state,
                self.exploration.actors,
                selected_goal.accepted_source_tags,
                selected_action_source_id,
                lead_actor_id=(
                    selected_participant_ids[0]
                    if selected_participant_ids
                    else None
                ),
                required=selected_goal.source_required,
            )
            if selected_goal is not None
            and self.active_challenge is not None
            else None
        )
        selected_goal_route = (
            selected_goal_execution.route
            if selected_goal_execution is not None
            else None
        )
        selected_flow_transition = (
            selected_goal_route.transition
            if selected_goal_route is not None
            else selected_npc_execution.route.transition
            if selected_npc_execution is not None
            else None
        )
        if (
            selected_goal is not None
            and self.board_selected_goal_id == selected_goal.id
        ):
            self.board_selected_goal_id = ""
            self.board_actor_selection = None
            self.board_selected_actor_id = ""
            self.board_selected_actor_role = ""
        self._record(
            "ui_action_submitted",
            {
                "text": raw_text,
                "slash_command": parsed_input.command.name if parsed_input.command is not None else None,
                "intent_hint": (
                    PlayerIntentHint.QUESTION.value
                    if conversation_only
                    else parsed_input.intent_hint.value
                    if parsed_input.intent_hint is not None
                    else None
                ),
                "conversation_only": conversation_only,
                "zone_id": self.current_zone.id,
                "active_point_id": self.active_point.id if self.active_point else None,
                "active_challenge_id": self.active_challenge.id if self.active_challenge else None,
                "selected_goal_id": selected_goal.id if selected_goal is not None else None,
                "flow_transition_id": (
                    selected_flow_transition.id
                    if selected_flow_transition is not None
                    else None
                ),
                "flow_route_kind": (
                    selected_flow_transition.route_kind.value
                    if selected_flow_transition is not None
                    else selected_goal_route.route_kind.value
                    if selected_goal_route is not None
                    else None
                ),
                "participant_actor_ids": list(selected_participant_ids),
                "check_participants": (
                    resolved_check_participants.value
                    if resolved_check_participants is not None
                    else None
                ),
                "selected_social_skill": selected_social_skill,
                "selected_action_source_id": (
                    action_source.id if action_source is not None else None
                ),
            },
        )
        if (
            selected_goal is None
            or selected_goal.description_mode
            != InteractionDescriptionMode.NONE
        ):
            self._add_message("Gracze", raw_text)
        if parsed_input.intent_hint == PlayerIntentHint.HELP:
            self._add_message("Dostępne komendy", slash_help_message())
            return self.state_payload()
        action_text = parsed_input.content
        if parsed_input.intent_hint == PlayerIntentHint.TAKE:
            return self._submit_collection_action(action_text, player_display_text=raw_text)
        if point is not None and point.npc_interaction is not None:
            return self._submit_npc_action(
                point,
                action_text,
                selected_goal_id=selected_goal.id if selected_goal is not None else None,
                goal_execution=selected_npc_execution,
                selected_social_skill=selected_social_skill,
                conversation_only=conversation_only,
            )
        referenced_point = self._referenced_current_zone_point(action_text)
        if referenced_point is not None:
            positions = ", ".join(f"({position.col},{position.row})" for position in referenced_point.positions)
            self._add_message(
                "Punkt eksploracji",
                (
                    f"{referenced_point.name} jest osobnym punktem interakcji. "
                    f"Najpierw przestaw pionek drużyny na podświetlone na {led_color_name_pl(referenced_point.color)} "
                    f"pole {positions}, żeby wejść w interakcję z tym punktem."
                ),
            )
            return self.state_payload()
        challenge = self.active_challenge
        if challenge is None:
            self._remove_latest_visible_player_message()
            self._add_message(
                "Najpierw wybierz interakcję",
                (
                    "Podejdź pionkiem do podświetlonego punktu albo wybierz dostępną "
                    "interakcję w tej lokacji, a dopiero potem opisz działanie."
                ),
            )
            return self.state_payload()
        trap_action = match_revealed_trap_action(
            self.state,
            action_text,
            zone_id=self.current_zone.id,
        )
        if trap_action is not None:
            trap, action = trap_action
            return self._submit_trap_action(trap, action)
        if (
            selected_goal is not None
            and selected_goal.resolution_mode == InteractionResolutionMode.CHECK
            and selected_goal.description_mode == InteractionDescriptionMode.NONE
            and selected_goal_execution is not None
        ):
            scripted_result = self._start_scripted_challenge_check(
                challenge,
                action_text,
                goal_execution=selected_goal_execution,
                selected_check_participants=resolved_check_participants,
                participant_actor_ids=selected_participant_ids,
                action_source=action_source,
            )
            if scripted_result is not None:
                return scripted_result
        return self._submit_challenge_action(
            challenge,
            action_text,
            player_intent_hint=(
                PlayerIntentHint.QUESTION
                if conversation_only
                else parsed_input.intent_hint
            ),
            player_display_text=raw_text,
            selected_goal_id=selected_goal.id if selected_goal is not None else None,
            selected_check_participants=resolved_check_participants,
            participant_actor_ids=selected_participant_ids,
            conversation_only=conversation_only,
            goal_execution=selected_goal_execution,
            action_source=action_source,
        )

    def _start_scripted_challenge_check(
        self,
        challenge: ExplorationChallenge,
        text: str,
        *,
        goal_execution: ExplorationGoalExecutionPlan,
        selected_check_participants: CheckParticipants | None,
        participant_actor_ids: tuple[str, ...],
        action_source: ExplorationActionSource | None,
    ) -> dict[str, object] | None:
        """Start an authored check without asking the LLM to reinterpret it."""
        route = goal_execution.route
        profile_id = route.resolution_option_id
        if profile_id is None:
            return None
        profile = next(
            (candidate for candidate in challenge.options if candidate.id == profile_id),
            None,
        )
        if profile is None:
            raise ValueError(
                f"Cel {route.goal.id} wskazuje nieistniejący profil rozstrzygnięcia {profile_id}."
            )
        option = apply_goal_resolution_profile(
            profile,
            challenge=challenge,
            selected_goal_id=route.goal.id,
            resolution_option_id=profile_id,
            selected_check_participants=selected_check_participants,
            player_action=text,
            state=self.state,
            minimum_dc=EXPLORATION_DECISION_DC_MIN,
        )
        selected_resource = resource_for_action_source(self.state, action_source)
        if action_source is not None:
            noise_delta = (
                2
                if "very_loud" in action_source.consequence_tags
                else 1
                if "loud" in action_source.consequence_tags
                else 0
            )
            if noise_delta:
                option = replace(
                    option,
                    success_noise=option.success_noise + noise_delta,
                    failure_noise=option.failure_noise + noise_delta,
                    critical_failure_noise=option.critical_failure_noise + noise_delta,
                )
            if (
                action_source.kind == ExplorationActionSourceKind.SPELL
                and action_source.check_ability is not None
            ):
                option = replace(
                    option,
                    ability_check=replace(
                        option.ability_check,
                        ability=action_source.check_ability,
                        skill=None,
                        tool=None,
                    ),
                    requires_item_ids=(),
                    bonuses=tuple(
                        bonus
                        for bonus in option.bonuses
                        if bonus.source_type != "item"
                    ),
                )
            elif action_source.kind in {
                ExplorationActionSourceKind.ITEM,
                ExplorationActionSourceKind.TOOL,
                ExplorationActionSourceKind.WEAPON,
            }:
                option = replace(
                    option,
                    requires_item_ids=(action_source.reference_id,),
                    bonuses=tuple(
                        bonus
                        for bonus in option.bonuses
                        if (
                            bonus.source_type != "item"
                            or bonus.source_id == action_source.reference_id
                        )
                    ),
                )
        eligible_actors = tuple(
            actor
            for actor in actors_matching_challenge_option(
                self.exploration.actors,
                option,
            )
            if actor.faction == Faction.ALLY
        )
        if eligible_actors:
            self.selected_lead_actor_id = str(eligible_actors[0].id)
        self.pending = PendingInteraction(
            kind=PendingKind.CHALLENGE,
            stage=PendingStage.DECISION,
            challenge=challenge,
            option=option,
            participant_actor_ids=participant_actor_ids,
            resources=(selected_resource,) if selected_resource is not None else (),
            action_source=action_source,
        )
        self._record(
            "ui_scripted_challenge_check_started",
            {
                "challenge_id": challenge.id,
                "goal_id": route.goal.id,
                "option_id": option.id,
                "participant_actor_ids": list(participant_actor_ids),
                "action_source_id": (
                    action_source.id if action_source is not None else None
                ),
            },
        )
        self._add_message(
            "Próba",
            f"{route.goal.label}: mechanika jest zdefiniowana przez scenariusz.",
        )
        return self._accept_challenge()

    def _submit_trap_action(
        self,
        trap: ExplorationTrap,
        action: ExplorationTrapAction,
    ) -> dict[str, object]:
        if trap_state_for(self.state, trap.id).status != ExplorationTrapStatus.REVEALED:
            raise ValueError("Najpierw trzeba wykryć pułapkę.")
        if action == ExplorationTrapAction.DISARM and trap.required_item_id is not None:
            owner = next(
                (
                    actor
                    for actor in self.exploration.actors
                    if any(
                        item.id == trap.required_item_id and item.available
                        for item in actor.inventory
                    )
                ),
                None,
            )
            if owner is not None:
                self.selected_lead_actor_id = str(owner.id)
        action_label = {
            ExplorationTrapAction.DISARM: "rozbroić",
            ExplorationTrapAction.BYPASS: "bezpiecznie ominąć",
            ExplorationTrapAction.TRIGGER: "celowo uruchomić",
        }[action]
        self.pending = PendingInteraction(
            kind=PendingKind.TRAP,
            stage=PendingStage.DECISION,
            challenge=self.active_challenge,
            trap=trap,
            trap_action=action,
        )
        self._add_message(
            "Pułapka",
            f"Chcecie {action_label} pułapkę: {trap.name}. Potwierdźcie sposób działania.",
        )
        self._record(
            "ui_exploration_trap_action_proposed",
            {"trap_id": trap.id, "action": action.value},
        )
        return self.state_payload()

    def _submit_collection_action(
        self,
        text: str,
        *,
        player_display_text: str,
    ) -> dict[str, object]:
        registry = build_crafting_source_registry(self.state, self.exploration.actors)
        allowed_kinds = frozenset(
            {
                CraftingSourceKind.SCENE_ITEM,
                CraftingSourceKind.SCENE_FIXTURE,
                CraftingSourceKind.TEMPORARY_ITEM,
            }
        )
        direct_matches = match_available_sources(
            registry,
            text,
            allowed_kinds=allowed_kinds,
        )
        candidates = tuple(match.source for match in direct_matches)
        if not candidates:
            discovered = tuple(
                source
                for discovery in self.state.source_discoveries
                if discovery.zone_id == self.current_zone.id
                for source in (registry.source_by_id(discovery.source_id),)
                if source is not None and source.usable and source.kind in allowed_kinds
            )
            if len(discovered) == 1:
                candidates = discovered
            elif discovered:
                return self._reject_collection(
                    player_display_text,
                    "Nie wiadomo, który znaleziony element chcecie zabrać. Wskażcie jego nazwę po /weź.",
                )
        if not candidates:
            return self._reject_collection(
                player_display_text,
                "Nie rozpoznano istniejącego elementu do zabrania. Najpierw znajdźcie go przez /szukaj albo podajcie dokładną nazwę.",
            )
        if len(candidates) > 1:
            labels = ", ".join(source.label for source in candidates)
            return self._reject_collection(
                player_display_text,
                f"Deklaracja wskazuje kilka elementów: {labels}. Przez /weź zabierajcie jeden rodzaj elementu naraz.",
            )
        source = candidates[0]
        owner = next(
            (
                actor
                for actor in self.exploration.actors
                if str(actor.id) == self.selected_lead_actor_id and actor.faction == Faction.ALLY
            ),
            next((actor for actor in self.exploration.actors if actor.faction == Faction.ALLY), None),
        )
        try:
            plan = plan_source_collection(
                source,
                quantity=1,
                owner_actor_id=str(owner.id) if owner is not None else None,
            )
        except ValueError as exc:
            return self._reject_collection(player_display_text, str(exc))
        self.pending = PendingInteraction(
            kind=PendingKind.COLLECTION,
            stage=PendingStage.DECISION,
            collection_plan=plan,
            source_property_labels=self.exploration.crafting_policy.property_labels,
        )
        destination = {
            "actor_inventory": f"ekwipunek postaci {owner.name}" if owner is not None else "ekwipunek postaci",
            "party_treasure": "wspólne łupy drużyny",
            "scenario_quest": "zasoby fabularne scenariusza",
        }[plan.destination.value]
        self._add_message(
            "MG proponuje zabranie",
            f"Chcecie zabrać {source.label} z lokacji {self.current_zone.name} i przenieść do: {destination}.",
        )
        self._record(
            "ui_collection_proposed",
            {
                "source_id": source.id,
                "quantity": 1,
                "destination": plan.destination.value,
                "owner_actor_id": plan.owner_actor_id,
            },
        )
        return self.state_payload()

    def _reject_collection(self, player_text: str, reason: str) -> dict[str, object]:
        self._remember_scene_exchange(player_text, reason, outcome="collection_rejected")
        self._add_message("Nie można zabrać elementu", reason)
        self._record("ui_collection_rejected", {"player_text": player_text, "reason": reason})
        return self.state_payload()

    def _referenced_current_zone_point(self, text: str) -> ExplorationPoint | None:
        normalized = text.lower()
        for point in self.current_zone_points():
            point_words = [word for word in point.name.lower().replace("-", " ").split() if len(word) >= 4]
            if any(word in normalized for word in point_words):
                return point
            if point.npc_interaction is not None and "zwiadow" in normalized and "zwiadow" in point.name.lower():
                return point
        return None

    @property
    def active_challenge(self) -> ExplorationChallenge | None:
        challenge = challenge_for_zone(self.state, self.current_zone.id)
        if challenge is None:
            return None
        if challenge_state_for(self.state, challenge.id).completed:
            return None
        return challenge

    def travel_options(self) -> tuple[ExplorationZone, ...]:
        available_by_id = {zone.id: zone for zone in available_exploration_zones(self.state)}
        return tuple(
            available_by_id[zone.id]
            for zone in self._scene_location_zones()
            if zone.id in available_by_id and zone.id != self.current_zone.id
        )

    def _preview_zone(self) -> ExplorationZone | None:
        if not self.preview_zone_id:
            return None
        return next((zone for zone in self._scene_location_zones() if zone.id == self.preview_zone_id), None)

    def _scenario_asset_root(self) -> Path:
        if self.scenario_path.is_dir():
            return self.scenario_path
        sibling = self.scenario_path.with_suffix("")
        if sibling.is_dir():
            return sibling
        return self.scenario_path.parent

    def _game_asset_root(self) -> Path:
        return Path(__file__).resolve().parents[3] / "assets"

    def travel_to(self, zone_id: str) -> dict[str, object]:
        transition = self.exploration_flow.travel(
            state=self.state,
            current_zone=self.current_zone,
            travel_options=self.travel_options(),
            zone_id=zone_id,
        )
        self.state = transition.state
        self.state = clear_exploration_hidden(self.state)
        self._advance_party_lights(transition.elapsed_minutes)
        self.pending = None
        self.active_point_id = transition.active_point_id
        self.preview_zone_id = transition.preview_zone_id
        self.interaction_result = None
        self.board_selected_goal_id = ""
        self.board_selected_panel = ""
        self.board_selected_action_kind = ""
        self.board_selected_action_id = ""
        self.board_selected_action_confirmed = False
        self.board_actor_selection = None
        self.board_selected_actor_id = ""
        self.board_selected_actor_role = ""
        self.ui_flow_stage = UiFlowStage(transition.stage.value)
        self.exploration_board_selection_active = False
        self.board_message = transition.board_message
        if transition.message_title:
            self._add_message(transition.message_title, transition.message_body)
        self._add_expired_magic_effect_notices(transition.expired_magic_effects)
        self._add_clock_event_notices(transition.triggered_clock_events)
        if transition.event_type:
            self._record(transition.event_type, dict(transition.event_payload))
        if not self._begin_current_zone_paper_map_setup():
            self._detect_passive_traps()
            self._queue_current_zone_npc_setup()
        self._sync_board_leds()
        return self.state_payload()

    def configure_playground_trial(
        self,
        *,
        dummy_count: int,
        armor_class: int,
        hit_points: int,
        speed_feet: int,
        ability_score: int,
        creature_type: str,
        affinity: str,
        damage_type: str,
        condition_immunity: str = "",
    ) -> dict[str, object]:
        if self.exploration.scenario_id != "mechanics_playground":
            raise ValueError("Konfigurator prób jest dostępny tylko w Arenie mechanik.")
        if self.combat_state is not None or self.encounter_setup_flow is not None:
            raise ValueError("Najpierw zresetuj trwającą próbę.")
        if self.pending_encounter is not None:
            raise ValueError("Próba jest już przygotowana. Rozpocznij ją albo użyj resetu.")
        if not 1 <= dummy_count <= 6:
            raise ValueError("Arena obsługuje od 1 do 6 manekinów.")
        if not 5 <= armor_class <= 30:
            raise ValueError("KP manekina musi mieścić się w zakresie 5–30.")
        if not 1 <= hit_points <= 999:
            raise ValueError("Punkty wytrzymałości manekina muszą mieścić się w zakresie 1–999.")
        if not 0 <= speed_feet <= 60 or speed_feet % 5:
            raise ValueError("Szybkość musi wynosić 0–60 stóp i być wielokrotnością 5.")
        if not 1 <= ability_score <= 30:
            raise ValueError("Wartość cech manekina musi mieścić się w zakresie 1–30.")
        allowed_creature_types = {
            "beast", "construct", "dragon", "fey", "fiend", "humanoid",
            "monstrosity", "plant", "undead",
        }
        if creature_type not in allowed_creature_types:
            raise ValueError("Wybrano nieobsługiwany typ stworzenia.")
        if affinity not in {"none", "resistance", "immunity", "vulnerability"}:
            raise ValueError("Wybrano nieobsługiwany profil odporności.")
        parsed_damage_type = DamageType(damage_type)
        allowed_condition_immunities = {
            "", "blinded", "charmed", "deafened", "frightened", "grappled",
            "incapacitated", "paralyzed", "poisoned", "prone", "restrained",
            "stunned", "unconscious",
        }
        if condition_immunity not in allowed_condition_immunities:
            raise ValueError("Wybrano nieobsługiwaną odporność na stan.")
        self.playground_trial_config = PlaygroundTrialConfig(
            dummy_count=dummy_count,
            armor_class=armor_class,
            hit_points=hit_points,
            speed_feet=speed_feet,
            ability_score=ability_score,
            creature_type=creature_type,
            affinity=affinity,
            damage_type=parsed_damage_type,
            condition_immunity=condition_immunity,
        )
        self.state = replace(
            self.state,
            party_position=PartyPosition("combat_arena"),
            flags=set_scene_flag(self.state.flags, "playground_trial_requested", True),
        )
        self.active_point_id = ""
        self.ui_flow_stage = UiFlowStage.LOCATION_ACTIVE
        self._add_message(
            "Arena gotowa",
            (
                f"Ustawiono {dummy_count} manekinów: KP {armor_class}, "
                f"{hit_points} PW, szybkość {speed_feet} stóp. "
                "Rozpocznijcie setup starcia; cele i obszary wybieracie wyłącznie na planszy."
            ),
        )
        self._refresh_pending_encounter()
        self._record("playground_trial_configured", self.playground_trial_config.as_payload())
        self._sync_board_leds()
        return self.state_payload()

    def reset_playground_trial(self) -> dict[str, object]:
        if self.exploration.scenario_id != "mechanics_playground":
            raise ValueError("Reset próby jest dostępny tylko w Arenie mechanik.")
        config = self.playground_trial_config
        self.reset()
        self.playground_trial_config = config
        self.state = replace(
            self.state,
            party_position=PartyPosition("combat_arena"),
        )
        self.ui_flow_stage = UiFlowStage.LOCATION_ACTIVE
        self._add_message(
            "Próba zresetowana",
            "Przywrócono PW, zasoby, czary, manekiny, obiekty i stan eksploracji. Możecie zmienić parametry i uruchomić kolejną próbę.",
        )
        self._record("playground_trial_reset", config.as_payload())
        self._sync_board_leds()
        return self.state_payload()

    def _configure_playground_encounter(self, encounter: LoadedEncounter) -> LoadedEncounter:
        if self.exploration.scenario_id != "mechanics_playground":
            return encounter
        config = self.playground_trial_config
        affinities = DamageAffinityProfile(
            resistances=(config.damage_type,) if config.affinity == "resistance" else (),
            immunities=(config.damage_type,) if config.affinity == "immunity" else (),
            vulnerabilities=(config.damage_type,) if config.affinity == "vulnerability" else (),
        )
        enemies = [actor for actor in encounter.actors if actor.faction == Faction.ENEMY]
        active_enemy_ids = {
            str(actor.id)
            for actor in enemies[:config.dummy_count]
        }
        actors = tuple(
            (
                replace(
                    actor,
                    ac=config.armor_class,
                    hp=config.hit_points,
                    max_hp=config.hit_points,
                    temp_hp=0,
                    speed_feet=config.speed_feet,
                    ability_scores=AbilityScores(
                        strength=config.ability_score,
                        dexterity=config.ability_score,
                        constitution=config.ability_score,
                        intelligence=config.ability_score,
                        wisdom=config.ability_score,
                        charisma=config.ability_score,
                    ),
                    creature_type=config.creature_type,
                    damage_affinities=affinities,
                    condition_immunities=(
                        (config.condition_immunity,)
                        if config.condition_immunity
                        else ()
                    ),
                )
                if actor.faction == Faction.ENEMY
                else actor
            )
            for actor in encounter.actors
            if actor.faction != Faction.ENEMY or str(actor.id) in active_enemy_ids
        )
        return replace(encounter, actors=actors)

    def start_encounter_setup(self) -> dict[str, object]:
        self._refresh_pending_encounter()
        if self.pending_encounter is None:
            raise ValueError("Nie ma aktywnego encountera do przygotowania.")
        trigger = self._trigger_by_id(self.pending_encounter.trigger_id)
        if (
            trigger is not None
            and trigger.opening_policy is not None
            and self.pending_encounter.opening_resolution is None
        ):
            raise ValueError("Najpierw rozstrzygnij rozpoczęcie starcia.")
        encounter = build_encounter_from_scenario(load_scenario(self.pending_encounter.encounter_scenario))
        if self.custom_party:
            encounter = encounter_with_custom_party(
                encounter,
                tuple(
                    actor
                    for actor in self.exploration.actors
                    if actor.faction == Faction.ALLY
                ),
            )
        encounter = encounter_for_party_size(
            encounter,
            sum(actor.faction == Faction.ALLY for actor in encounter.actors),
        )
        encounter = _encounter_with_session_actor_state(encounter, self.exploration.actors)
        encounter = self._configure_playground_encounter(encounter)
        projected_fixtures = fixture_scene_objects(
            self.state,
            zone_id=self.current_zone.id,
        )
        authored_object_ids = {item.id for item in encounter.scene_objects}
        encounter = replace(
            encounter,
            scene_objects=(
                *encounter.scene_objects,
                *(
                    item
                    for item in projected_fixtures
                    if item.id not in authored_object_ids
                ),
            ),
        )
        steps = _build_encounter_setup_steps(encounter)
        if not steps:
            raise ValueError("Scenariusz encountera nie ma elementów do setupu.")
        self.encounter_setup_flow = EncounterSetupFlow(
            encounter=encounter,
            steps=steps,
            player_start_actor_ids=tuple(str(actor.id) for actor in encounter.actors if actor.faction == Faction.ALLY),
        )
        self._add_message(
            "Setup przed walką",
            f"Rozpoczynam setup encountera: {encounter.scenario_name}. Potwierdzajcie kolejne grupy po rozstawieniu figurek.",
        )
        self._sync_board_leds()
        return self.state_payload()

    def resolve_encounter_opening(self) -> dict[str, object]:
        self._refresh_pending_encounter()
        if self.pending_encounter is None:
            raise ValueError("Nie ma aktywnego encountera.")
        if self.pending_encounter.opening_resolution is not None:
            return self.state_payload()
        trigger = self._trigger_by_id(self.pending_encounter.trigger_id)
        if trigger is None or trigger.opening_policy is None:
            raise ValueError("Ten encounter nie definiuje osobnego rozpoczęcia starcia.")
        resolution = resolve_encounter_opening(self.state, trigger.opening_policy)
        self.pending_encounter = replace(self.pending_encounter, opening_resolution=resolution)
        self._add_message(resolution.title, resolution.narration)
        self._record(
            "ui_encounter_opening_resolved",
            {
                "trigger_id": trigger.id,
                "rule_id": resolution.rule_id,
                "outcome": resolution.outcome.value,
                "noise": resolution.noise,
                "completion_tags": list(resolution.completion_tags),
            },
        )
        self.board_message = "Rozpoczęcie starcia rozstrzygnięte. Przejdź do setupu encountera."
        self._sync_board_leds()
        return self.state_payload()

    def resolve_active_combat(self) -> dict[str, object]:
        if self.pending_encounter is None:
            raise ValueError("Nie ma aktywnego encountera do rozstrzygnięcia.")
        if self.combat_state is None:
            raise ValueError("Walka nie została jeszcze rozpoczęta.")
        trigger = self._trigger_by_id(self.pending_encounter.trigger_id)
        if trigger is None:
            raise ValueError(f"Nieznany trigger encountera: {self.pending_encounter.trigger_id}.")
        encounter = self._active_encounter()
        objectives = encounter.objectives if encounter is not None else ()
        updated_objectives = objective_status_after_combat(
            self.combat_state,
            objectives,
        )
        if updated_objectives != objectives and encounter is not None:
            encounter = replace(encounter, objectives=updated_objectives)
            self._replace_active_encounter(encounter)
        encounter_result = self.pending_encounter_result or scene_result(
            self.combat_state,
            updated_objectives,
        )
        if not encounter_result.finished:
            raise ValueError("Encounter nie ma jeszcze końcowego wyniku.")
        outcome = _encounter_outcome_for_result(
            trigger,
            self.pending_encounter.name,
            encounter_result,
        )
        game_over = (
            encounter_result.conclusion
            in {
                SceneConclusionType.DEFEAT,
                SceneConclusionType.RETREAT,
                SceneConclusionType.SURRENDER,
            }
            and trigger.defeat_policy == EncounterDefeatPolicy.GAME_OVER
        )
        visible_points_before = {point.id for point in visible_exploration_points(self.state.points)}
        effects = []
        for effect in outcome.effects:
            effect_result = apply_exploration_effect(self.state, effect)
            self.state = effect_result.state
            self._record_effect_result(effect_result, source="encounter_outcome", raw_effect=effect)
            effects.append(effect_result)
        visible_points_after = {point.id for point in visible_exploration_points(self.state.points)}
        revealed_point_ids = tuple(sorted(visible_points_after - visible_points_before))
        self.resolved_encounter_trigger_ids.add(trigger.id)
        self._record(
            "ui_encounter_resolved",
            {
                "trigger_id": trigger.id,
                "conclusion": encounter_result.conclusion.value,
                "winner": (
                    encounter_result.winner.value
                    if encounter_result.winner is not None
                    else None
                ),
                "completed_objectives": list(encounter_result.completed_objectives),
                "effect_types": [result.effect_type for result in effects],
                "revealed_point_ids": list(revealed_point_ids),
            },
        )
        self._add_message(outcome.title or "Wynik encountera", outcome.body or "Encounter został rozstrzygnięty.")
        self._apply_combat_trigger_events(
            tuple(
                EffectEvent(EffectEventType.ENCOUNTER_ENDED, actor_id=str(actor.id))
                for actor in self.combat_state.actors
            )
        )
        frenzied_actor_ids = {
            effect.actor_id
            for effect in self.active_combat_effects
            if effect.kind == "frenzy"
        }
        for frenzied_actor_id in frenzied_actor_ids:
            frenzied_actor = next(
                (
                    actor
                    for actor in self.combat_state.actors
                    if str(actor.id) == frenzied_actor_id
                ),
                None,
            )
            if frenzied_actor is not None:
                self.combat_state = replace_actor(
                    self.combat_state,
                    increase_exhaustion(frenzied_actor),
                )
        self.combat_state, self.active_combat_effects, expired_effects = expire_combat_effects(
            self.combat_state,
            self.active_combat_effects,
            EffectEvent(EffectEventType.ENCOUNTER_ENDED),
        )
        if expired_effects:
            self._record(
                "ui_effects_expired",
                {
                    "event": EffectEventType.ENCOUNTER_ENDED.value,
                    "effect_ids": [effect.id for effect in expired_effects],
                },
            )
            self._add_message(
                "Efekty encountera wygasły",
                ", ".join(effect.label for effect in expired_effects),
            )
        self._stash_remaining_combat_loot(encounter_result)
        self.exploration = _exploration_with_combat_actor_state(
            self.exploration,
            self.combat_state.actors,
        )
        experience_result = None
        level_up_actors: list[dict[str, object]] = []
        if outcome.experience_points or outcome.experience_points_per_actor:
            experience_result = (
                award_party_experience_per_actor(
                    self.exploration.actors,
                    outcome.experience_points_per_actor,
                    level_cap=3,
                )
                if outcome.experience_points_per_actor
                else award_party_experience(
                    self.exploration.actors,
                    outcome.experience_points,
                    level_cap=3,
                )
            )
            self.exploration = replace(
                self.exploration,
                actors=experience_result.actors,
            )
            custom_party_ids = {
                str(actor.id)
                for actor in self.custom_party
            }
            awarded_actor_ids = set(experience_result.actor_ids)
            level_up_actors = [
                {
                    "id": str(actor.id),
                    "name": actor.name,
                    "level": actor.level,
                    "experience_points": actor.experience_points,
                    "eligible_level": experience_progress(
                        actor,
                        level_cap=3,
                    ).eligible_level,
                    "can_open_level_up": str(actor.id) in custom_party_ids,
                }
                for actor in self.exploration.actors
                if str(actor.id) in awarded_actor_ids
                and experience_progress(actor, level_cap=3).level_up_available
            ]
            self._record(
                "ui_party_experience_awarded",
                {
                    "total_experience": experience_result.total_experience,
                    "experience_per_actor": experience_result.experience_per_actor,
                    "discarded_remainder": experience_result.discarded_remainder,
                    "actor_ids": list(experience_result.actor_ids),
                },
            )
            self._add_message(
                "Doświadczenie",
                (
                    f"Każda postać otrzymuje {experience_result.experience_per_actor} XP."
                ),
            )
            if level_up_actors:
                self._add_message(
                    "Awans dostępny",
                    (
                        "Próg kolejnego poziomu osiągnęli: "
                        + ", ".join(str(actor["name"]) for actor in level_up_actors)
                        + ". Po zakończeniu wyniku otwórz awans wybranej postaci."
                    ),
                )
            if self.custom_party and self.character_progress_sink is not None:
                progressed_ids = {
                    str(actor.id) for actor in self.custom_party
                }
                progressed_actors = tuple(
                    actor
                    for actor in self.exploration.actors
                    if str(actor.id) in progressed_ids
                )
                self.character_progress_sink(progressed_actors)
        exploration_actor_ids = {str(actor.id) for actor in self.exploration.actors}
        encounter_actor_ids = {str(actor.id) for actor in self.combat_state.actors}
        condition_transition = reconcile_conditions_after_encounter(
            exploration_conditions=self.state.condition_states,
            combat_conditions=self.combat_state.condition_states,
            exploration_actor_ids=frozenset(exploration_actor_ids),
            encounter_actor_ids=frozenset(encounter_actor_ids),
        )
        self.combat_state = replace(
            self.combat_state,
            condition_states=tuple(
                condition
                for condition in self.combat_state.condition_states
                if condition not in condition_transition.expired_conditions
            ),
        )
        self.state = replace(
            self.state,
            condition_states=condition_transition.condition_states,
        )
        self._add_expired_condition_notices(
            condition_transition.expired_conditions,
            prefix="Koniec encountera usuwa stan",
        )
        if condition_transition.expired_conditions:
            self._record(
                "ui_conditions_expired",
                {
                    "event": EffectEventType.ENCOUNTER_ENDED.value,
                    "conditions": [
                        {
                            "actor_id": condition.actor_id,
                            "condition": condition.condition.value,
                        }
                        for condition in condition_transition.expired_conditions
                    ],
                },
            )
        self.interaction_result = {
            "title": outcome.title or "Wynik encountera",
            "body": outcome.body or "Encounter został rozstrzygnięty.",
            "unlocked_zones": [],
            "revealed_points": [_point_payload(point) for point in self.state.points if point.id in revealed_point_ids],
            "current_zone": _zone_payload(self.current_zone, self._scenario_asset_root()),
            "next_instruction": outcome.next_instruction or "Zakończ wynik, żeby wrócić do wyboru lokacji.",
            "experience": (
                None
                if experience_result is None
                else {
                    "total": experience_result.total_experience,
                    "per_actor": experience_result.experience_per_actor,
                    "actor_ids": list(experience_result.actor_ids),
                    "level_up_actors": level_up_actors,
                }
            ),
        }
        self.pending_encounter = None
        self.pending_encounter_result = None
        self.encounter_setup_flow = None
        self.encounter_initiative_flow = None
        self.combat_state = None
        self.pending = None
        self.preview_zone_id = ""
        self.active_point_id = ""
        self.ui_flow_stage = (
            UiFlowStage.GAME_OVER
            if game_over
            else UiFlowStage.INTERACTION_RESULT
        )
        self.board_message = (
            "Drużyna została pokonana. Koniec gry."
            if game_over
            else "Encounter rozstrzygnięty. Na planszy podświetlono nowe opcje sceny."
        )
        if game_over:
            self._record(
                "ui_game_over",
                {
                    "trigger_id": trigger.id,
                    "conclusion": encounter_result.conclusion.value,
                },
            )
        self._sync_board_leds()
        return self.state_payload()

    def _stash_remaining_combat_loot(self, result: SceneResult) -> None:
        if self.combat_state is None or result.winner != Faction.ALLY:
            return
        bundles: list[tuple[LootBundle, str | None]] = []
        dropped_item_ids_by_actor: dict[str, set[str]] = {}
        for dropped in self.combat_state.dropped_weapons:
            source_actor = next(
                actor
                for actor in self.combat_state.actors
                if actor.id == dropped.source_actor_id
            )
            dropped_item_ids_by_actor.setdefault(
                str(dropped.source_actor_id),
                set(),
            ).add(dropped.weapon.id)
            if source_actor.faction == Faction.ALLY:
                continue
            bundles.append(
                (
                    LootBundle(
                        id=f"aftermath:{dropped.id}",
                        label=dropped.weapon.name,
                        items=(dropped.weapon,),
                    ),
                    None,
                )
            )
        for actor in self.combat_state.actors:
            if actor.faction == Faction.ALLY or not actor.is_defeated():
                continue
            bundle = loot_bundle_from_actor(
                actor,
                excluded_item_ids=frozenset(
                    dropped_item_ids_by_actor.get(str(actor.id), ())
                ),
            )
            if not bundle.is_empty:
                bundles.append((bundle, None))
        bundles.extend(
            (ground.bundle, None)
            for ground in self.combat_state.battlefield_loot
            if not ground.bundle.is_empty
        )
        if not bundles:
            return

        eligible_ids = [
            str(actor.id)
            for actor in self.combat_state.actors
            if actor.faction == Faction.ALLY and not actor.is_defeated()
        ]
        if self.selected_lead_actor_id in eligible_ids:
            eligible_ids.remove(self.selected_lead_actor_id)
            eligible_ids.insert(0, self.selected_lead_actor_id)
        transferred_items: list[str] = []
        transferred_currency = CurrencyWallet()
        state = self.combat_state
        for bundle, preferred_actor_id in bundles:
            candidate_ids = (
                [preferred_actor_id, *eligible_ids]
                if preferred_actor_id in eligible_ids
                else eligible_ids
            )
            candidate_ids = list(dict.fromkeys(candidate_ids))
            for recipient_id in candidate_ids:
                recipient = next(
                    actor
                    for actor in state.actors
                    if str(actor.id) == recipient_id
                )
                try:
                    transfer = transfer_all_loot(bundle, recipient)
                except ValueError:
                    continue
                state = replace_actor(state, transfer.recipient)
                transferred_items.extend(
                    f"{item.name} ×{item.quantity}" for item in transfer.items
                )
                transferred_currency = transferred_currency.add(transfer.currency)
                break
            else:
                raise ValueError(
                    f"Nie można zakończyć encountera: łup „{bundle.label}” "
                    "przekracza udźwig drużyny. Zabierz wybrane rzeczy albo zostaw je jawnie przed wyjściem."
                )
        self.combat_state = replace(
            state,
            dropped_weapons=(),
            battlefield_loot=(),
        )
        summary = ", ".join(transferred_items)
        if not transferred_currency.is_empty:
            coins = transferred_currency.total_coins
            summary = f"{summary}; {coins} monet" if summary else f"{coins} monet"
        self._add_message(
            "Zabezpieczono łup po walce",
            (
                f"Przed opuszczeniem pola walki drużyna zabiera: {summary}."
                if summary
                else "Drużyna zabezpiecza pozostały łup."
            ),
        )
        self._record(
            "ui_combat_aftermath_loot_stashed",
            {
                "items": transferred_items,
                "currency": transferred_currency.as_payload(),
            },
        )

    def retreat_from_combat(self) -> dict[str, object]:
        return self._declare_combat_conclusion(SceneConclusionType.RETREAT)

    def surrender_combat(self) -> dict[str, object]:
        return self._declare_combat_conclusion(SceneConclusionType.SURRENDER)

    def _declare_combat_conclusion(
        self,
        conclusion: SceneConclusionType,
    ) -> dict[str, object]:
        if self.combat_state is None:
            raise ValueError("Walka nie została rozpoczęta.")
        if self.pending_encounter is None:
            raise ValueError("Nie ma aktywnego encountera.")
        if self.combat_state.status != CombatStatus.ACTIVE:
            raise ValueError("Walka została już zakończona.")
        actor = combat_current_actor(self.combat_state)
        if actor.faction != Faction.ALLY:
            raise ValueError("Odwrót lub kapitulację można zadeklarować w turze bohatera.")
        if self._combat_has_pending_resolution():
            raise ValueError("Najpierw dokończ lub anuluj rozpoczętą akcję.")
        encounter = self._active_encounter()
        self.combat_state, result = conclude_scene(
            self.combat_state,
            conclusion=conclusion,
            objectives=encounter.objectives if encounter is not None else (),
            acting_faction=Faction.ALLY,
        )
        self.pending_encounter_result = result
        self.selected_combat_movement_path = None
        self.combat_targeting_attack_source_id = None
        self._clear_player_pending_choices()
        title = (
            "Odwrót drużyny"
            if conclusion == SceneConclusionType.RETREAT
            else "Kapitulacja drużyny"
        )
        self.board_message = result.message
        self._add_message(title, result.message)
        self._record(
            "ui_combat_encounter_concluded",
            {
                "conclusion": conclusion.value,
                "winner": result.winner.value if result.winner is not None else None,
                "completed_objectives": list(result.completed_objectives),
            },
        )
        self._sync_board_leds()
        return self.state_payload()

    def _combat_has_pending_resolution(self) -> bool:
        if self.combat_targeting_class_feature_action_id is not None:
            return True
        if self.combat_stabilization_method is not None:
            return True
        return any(
            pending is not None
            for pending in (
                self.pending_enemy_turn_intent,
                self.pending_enemy_turn_result,
                self.pending_enemy_turn_ack_result,
                self.pending_enemy_saving_throw,
                self.pending_player_attack,
                self.pending_player_healing,
                self.pending_area_spell,
                self.pending_summon,
                self.pending_magic_movement,
                self.pending_spell_debuff,
                self.pending_spell_dispel,
                self.pending_combat_interaction,
                self.pending_combat_help,
                self.pending_combat_skill_check,
                self.pending_combat_shove,
                self.pending_combat_grapple,
                self.pending_concentration_action,
                self.pending_concentration_check,
                self.pending_combat_ready,
                self.pending_opportunity_movement,
                self.pending_reaction_window,
                self.pending_enemy_opportunity_attack,
                self.pending_ready_attack,
                self.pending_combat_context_menu,
                self.pending_approach_interaction,
                self.pending_approach_pickup,
            )
        )

    def confirm_encounter_setup_step(self) -> dict[str, object]:
        if self.encounter_setup_flow is None:
            return self.start_encounter_setup()
        flow = self.encounter_setup_flow
        step = flow.current_step
        if step is None:
            return self.state_payload()
        if flow.is_player_start_step:
            actor = flow.current_player_start_actor
            actor_name = actor.name if actor is not None else "kolejnego bohatera"
            raise ValueError(f"Ten krok wymaga kliknięcia planszy: wybierz pole startowe dla {actor_name}.")
        self._add_message("Setup potwierdzony", f"Potwierdzono: {step.label}.")
        if flow.current_index + 1 >= len(flow.steps):
            flow.completed = True
            self._seed_precombat_stealth_from_exploration()
            self._add_message(
                "Setup zakończony",
                "Figurki i jawne elementy encountera są rozstawione. Następny krok to ewentualne skradanie, inicjatywa i start walki.",
            )
            self._resume_retry_combat_after_setup()
        else:
            flow.current_index += 1
        self._sync_board_leds()
        return self.state_payload()

    def assign_encounter_player_start_position(self, selected: Coordinate) -> dict[str, object]:
        if self.encounter_setup_flow is None:
            raise ValueError("Setup encountera nie jest aktywny.")
        flow = self.encounter_setup_flow
        if not flow.is_player_start_step:
            raise ValueError("Aktualny krok setupu nie zbiera pól startowych bohaterów.")
        actor = flow.current_player_start_actor
        if actor is None:
            return self._advance_completed_player_start_step()
        remaining = flow.remaining_player_start_positions()
        if selected not in remaining:
            self.board_message = "Kliknij wolne, podświetlone pole startowe dla aktualnego bohatera."
            return self.state_payload()
        updated_actor = replace(actor, position=selected)
        updated_actors = tuple(updated_actor if candidate.id == actor.id else candidate for candidate in flow.encounter.actors)
        flow.encounter = replace(flow.encounter, actors=updated_actors)
        flow.player_start_assignments[str(actor.id)] = selected
        self.board_message = f"Ustawiono {actor.name} na polu {selected.as_tuple()}."
        self._add_message("Pole startowe", f"{actor.name}: {selected.as_tuple()}.")
        self._record(
            "ui_encounter_player_start_assigned",
            {"actor_id": str(actor.id), "position": [selected.col, selected.row]},
        )
        if flow.current_player_start_actor is None:
            return self._advance_completed_player_start_step()
        self._sync_board_leds()
        return self.state_payload()

    def _advance_completed_player_start_step(self) -> dict[str, object]:
        if self.encounter_setup_flow is None:
            return self.state_payload()
        flow = self.encounter_setup_flow
        self._add_message("Setup potwierdzony", "Pola startowe bohaterów zostały przypisane z planszy.")
        if flow.current_index + 1 >= len(flow.steps):
            flow.completed = True
            self._seed_precombat_stealth_from_exploration()
            self._add_message(
                "Setup zakończony",
                "Figurki i jawne elementy encountera są rozstawione. Następny krok to ewentualne skradanie, inicjatywa i start walki.",
            )
            self._resume_retry_combat_after_setup()
        else:
            flow.current_index += 1
        self._sync_board_leds()
        return self.state_payload()

    def _resume_retry_combat_after_setup(self) -> None:
        if self._retry_encounter_combat_state is None:
            return
        self.combat_state = self._retry_encounter_combat_state
        self._retry_encounter_combat_state = None
        self.encounter_initiative_flow = self._retry_encounter_initiative_flow
        self._retry_encounter_initiative_flow = None
        self._add_message(
            "Plansza gotowa",
            "Ponowny setup zakończony. Walka wraca do początku z zachowaną kolejnością inicjatywy.",
        )
        self.board_message = (
            "Setup potwierdzony. Encounter jest ponownie aktywny."
        )

    def start_encounter_initiative(self) -> dict[str, object]:
        if self.encounter_setup_flow is None or not self.encounter_setup_flow.completed:
            raise ValueError("Najpierw zakończ setup encountera.")
        if self.combat_state is not None:
            return self.state_payload()
        encounter = self.encounter_setup_flow.encounter
        opening = self.pending_encounter.opening_resolution if self.pending_encounter is not None else None
        if (
            precombat_stealth_is_available(opening)
            and self.pending_encounter is not None
            and not self.pending_encounter.precombat_stealth_completed
        ):
            raise ValueError("Najpierw zakończ etap skradania przed walką albo świadomie go pomiń.")
        self.state = clear_exploration_hidden(self.state)
        trigger_id = self.pending_encounter.trigger_id if self.pending_encounter is not None else ""
        applicable_edges = {
            edge.beneficiary_actor_id: edge
            for edge in available_encounter_edges(self.state, trigger_id)
            if edge.edge_type == EncounterEdgeType.INITIATIVE_ADVANTAGE
        }
        party_disadvantaged = bool(
            opening is not None
            and opening.outcome == EncounterOpeningOutcome.ENEMIES_SURPRISE_PARTY
        )
        if (
            party_disadvantaged
            and scene_flag(self.state.flags, "short_rest_alarm_active", False)
        ):
            party_disadvantaged = False
            self.state = replace(
                self.state,
                flags=set_scene_flag(
                    self.state.flags,
                    "short_rest_alarm_active",
                    False,
                ),
            )
            self._add_message(
                "Alarm",
                "Alarm ostrzegł drużynę przed napadem; bohaterowie nie są zaskoczeni.",
            )
            self._record(
                "ui_short_rest_alarm_prevented_surprise",
                {"trigger_id": trigger_id},
            )
        party_advantaged = bool(
            opening is not None
            and opening.outcome
            in {
                EncounterOpeningOutcome.PARTY_INITIATIVE_ADVANTAGE,
                EncounterOpeningOutcome.PARTY_INITIATIVE_ADVANTAGE_AND_CAN_HIDE,
            }
        )
        party_roll_mode = (
            RollMode.DISADVANTAGE
            if party_disadvantaged
            else RollMode.ADVANTAGE
            if party_advantaged
            else RollMode.NORMAL
        )
        roll_modes_by_actor_id = {
            str(actor.id): party_roll_mode
            for actor in encounter.actors
            if party_roll_mode != RollMode.NORMAL
            and actor.faction == Faction.ALLY
            and not actor.is_defeated()
        }
        for actor_id in applicable_edges:
            roll_modes_by_actor_id[actor_id] = (
                RollMode.NORMAL
                if roll_modes_by_actor_id.get(actor_id) == RollMode.DISADVANTAGE
                else RollMode.ADVANTAGE
            )
        prompts = build_player_initiative_prompts(
            encounter.actors,
            roll_modes_by_actor_id,
        )
        self.encounter_initiative_flow = EncounterInitiativeFlow(
            encounter=encounter,
            prompts=prompts,
            entries=[],
            edges_by_actor_id=applicable_edges,
        )
        self._add_message(
            "Inicjatywa",
            "Rozpoczyna się walka. Bohaterowie wykonują test inicjatywy po kolei; przeciwnicy rzucają automatycznie."
            + (
                " Rozpoznanie daje wskazanemu bohaterowi przewagę w tym rzucie."
                if applicable_edges
                else ""
            ),
        )
        if not prompts:
            self._finish_encounter_initiative()
        self._sync_board_leds()
        return self.state_payload()

    def submit_encounter_initiative_roll(
        self,
        natural_roll: int,
        natural_roll_2: int | None = None,
        natural_rerolls: tuple[int, ...] = (),
    ) -> dict[str, object]:
        if self.encounter_initiative_flow is None:
            raise ValueError("Inicjatywa encountera nie została rozpoczęta.")
        flow = self.encounter_initiative_flow
        prompt = flow.current_prompt
        if prompt is None:
            return self.state_payload()
        if prompt.request.mode != RollMode.NORMAL and natural_roll_2 is None:
            raise ValueError("Przewaga albo utrudnienie w inicjatywie wymaga podania wyników obu kości d20.")
        roll = resolve_d20_roll(
            D20RollInput(
                prompt.request,
                natural_roll,
                natural_roll_2,
                natural_rerolls,
            )
        )
        entry = InitiativeEntry(
            actor=prompt.actor,
            roll=roll,
            dexterity_modifier=prompt.dexterity_modifier,
            stable_order=_actor_stable_order(flow.encounter, prompt.actor),
        )
        flow.entries.append(entry)
        edge = flow.edges_by_actor_id.get(str(prompt.actor.id))
        if edge is not None:
            self.state = consume_encounter_edge(self.state, edge.id)
            self._record(
                "ui_encounter_edge_consumed",
                {
                    "edge_id": edge.id,
                    "edge_type": edge.edge_type.value,
                    "actor_id": edge.beneficiary_actor_id,
                    "encounter_trigger_id": edge.encounter_trigger_id,
                },
            )
        self._add_message(
            "Rzut inicjatywy",
            f"{prompt.actor.name}: naturalny wynik {_d20_roll_result_text(roll)}, razem {roll.total}."
            + (f" Zużyto: {edge.label}." if edge is not None else ""),
        )
        flow.current_prompt_index += 1
        if flow.current_prompt is None:
            self._finish_encounter_initiative()
        self._sync_board_leds()
        return self.state_payload()

    def _finish_encounter_initiative(self) -> None:
        if self.encounter_initiative_flow is None or self.encounter_initiative_flow.completed:
            return
        flow = self.encounter_initiative_flow
        known_actor_ids = {entry.actor.id for entry in flow.entries}
        opening = self.pending_encounter.opening_resolution if self.pending_encounter is not None else None
        enemies_disadvantaged = bool(
            opening is not None
            and opening.outcome == EncounterOpeningOutcome.PARTY_SURPRISES_ENEMIES
        )
        for actor in flow.encounter.actors:
            if actor.id in known_actor_ids or actor.faction == Faction.ALLY or actor.is_defeated():
                continue
            enemy_mode = RollMode.DISADVANTAGE if enemies_disadvantaged else RollMode.NORMAL
            entry = replace(
                roll_enemy_initiative(actor, self.encounter_rng, enemy_mode),
                stable_order=_actor_stable_order(flow.encounter, actor),
            )
            flow.entries.append(entry)
            self._add_message(
                "Inicjatywa przeciwnika",
                f"{actor.name}: automatyczny wynik {_d20_roll_result_text(entry.roll)}, razem {entry.roll.total}."
                + (" Utrudnienie za zaskoczenie." if enemy_mode == RollMode.DISADVANTAGE else ""),
            )
        order = build_initiative_order(flow.entries)
        flow.order = order
        flow.completed = True
        hidden_states = hidden_states_from_precombat_attempts(
            self.pending_encounter.precombat_stealth_attempts if self.pending_encounter is not None else (),
            flow.encounter.actors,
        )
        self.combat_state = start_combat(
            flow.encounter.actors,
            order,
            hidden_states,
            self.state.condition_states,
        )
        if flow.encounter.enemy_ai_profile is not None:
            party_size = sum(
                actor.faction == Faction.ALLY
                for actor in flow.encounter.actors
            )
            self.combat_state = initialize_enemy_ai(
                self.combat_state,
                profile_id=flow.encounter.enemy_ai_profile.id,
                starting_morale=flow.encounter.enemy_ai_profile.starting_morale(
                    party_size
                ),
                encounter_seed=7,
            )
        if self.current_zone.ambient_light == LightLevel.DARKNESS:
            self.active_combat_effects = apply_active_effect(
                self.active_combat_effects,
                ActiveCombatEffect(
                    id=f"ambient_darkness:{self.current_zone.id}",
                    actor_id="environment",
                    kind="ambient_darkness",
                    label="Niemagiczna ciemność",
                    object_id=f"zone:{self.current_zone.id}",
                    value=0,
                    source=EffectSource(
                        EffectSourceType.SCENE,
                        self.current_zone.id,
                        self.current_zone.name,
                    ),
                    duration=EffectDuration.UNTIL_ENCOUNTER_END,
                ),
            ).active_effects
        if (
            opening is not None
            and opening.outcome == EncounterOpeningOutcome.ENEMIES_SURPRISE_PARTY
        ):
            enemies = tuple(
                actor
                for actor in self.combat_state.actors
                if actor.faction == Faction.ENEMY and not actor.is_defeated()
            )
            erynd = next(
                (
                    actor
                    for actor in self.combat_state.actors
                    if actor_has_feature(actor, "flaw_ambush_survivor")
                    and not actor.is_defeated()
                ),
                None,
            )
            if erynd is not None and enemies:
                source = min(
                    enemies,
                    key=lambda enemy: grid_distance_feet(erynd.position, enemy.position),
                )
                condition_states = add_condition(
                    self.combat_state.condition_states,
                    str(erynd.id),
                    CombatCondition.FRIGHTENED,
                    source_actor_id=str(source.id),
                    source_label="Skaza: Ocalały z zasadzki",
                    duration=EffectDuration.UNTIL_TURN_END,
                    expiration_actor_id=str(erynd.id),
                )
                self.combat_state = replace(
                    self.combat_state,
                    condition_states=condition_states,
                )
                self._add_message(
                    "Skaza Erynda",
                    f"Zasadzka przywołuje dawną traumę: Erynd jest Przerażony przez {source.name} do końca pierwszej tury.",
                )
        for effect in self._timed_combat_effects():
            expired_effects = self.active_combat_effects
            if effect.duration == EffectDuration.CONCENTRATION:
                expired_effects = expire_active_effects(
                    self.active_combat_effects,
                    EffectEvent(
                        EffectEventType.CONCENTRATION_ENDED,
                        actor_id=effect.source_actor_id,
                    ),
                ).active_effects
            self.active_combat_effects = apply_active_effect(
                expired_effects,
                effect,
            ).active_effects
        order_text = ", ".join(entry.actor.name for entry in order.entries)
        self._add_message(
            "Kolejność inicjatywy",
            f"Kolejność została ustalona: {order_text}. Pierwsza tura: {order.current_actor.name}.",
        )
        checkpoint_saved = self._write_encounter_checkpoint()
        if checkpoint_saved is False:
            self._add_message(
                "Checkpoint encountera niedostępny",
                "Nie udało się zapisać początku walki; opcja ponowienia po porażce może być niedostępna.",
            )
        self._sync_board_leds()

    def submit_precombat_stealth_roll(
        self,
        *,
        actor_id: str,
        natural_roll: int,
        natural_roll_2: int | None = None,
    ) -> dict[str, object]:
        if self.encounter_setup_flow is None or not self.encounter_setup_flow.completed:
            raise ValueError("Najpierw zakończ setup encountera.")
        if self.pending_encounter is None:
            raise ValueError("Nie ma aktywnego encountera.")
        if self.encounter_initiative_flow is not None or self.combat_state is not None:
            raise ValueError("Etap skradania zakończył się wraz z rozpoczęciem inicjatywy.")
        if self.pending_encounter.precombat_stealth_completed:
            raise ValueError("Etap skradania przed walką został już zakończony.")
        if not precombat_stealth_is_available(self.pending_encounter.opening_resolution):
            raise ValueError("Okoliczności rozpoczęcia tego starcia nie pozwalają na skradanie przed walką.")

        encounter_actors = self.encounter_setup_flow.encounter.actors
        hiding_actor = next(
            actor for actor in encounter_actors if str(actor.id) == actor_id
        )
        passive_adjustments, automatically_hidden = (
            self._precombat_visibility_adjustments(
                hiding_actor,
                encounter_actors,
            )
        )
        resolution = resolve_precombat_stealth(
            encounter_actors,
            self.pending_encounter.precombat_stealth_attempts,
            actor_id=actor_id,
            natural_roll=natural_roll,
            natural_roll_2=natural_roll_2,
            passive_perception_adjustments=passive_adjustments,
            automatically_hidden_from_actor_ids=automatically_hidden,
            active_effects=self._stealth_effects(),
        )
        self.pending_encounter = replace(
            self.pending_encounter,
            precombat_stealth_attempts=(
                *self.pending_encounter.precombat_stealth_attempts,
                resolution.attempt,
            ),
        )
        actor = next(
            actor
            for actor in self.encounter_setup_flow.encounter.actors
            if str(actor.id) == actor_id
        )
        hidden_names = _actor_names_from_actors(
            self.encounter_setup_flow.encounter.actors,
            resolution.attempt.hidden_from_actor_ids,
        )
        detected_names = _actor_names_from_actors(
            self.encounter_setup_flow.encounter.actors,
            resolution.attempt.detected_by_actor_ids,
        )
        body = f"{actor.name}: wynik Stealth {resolution.attempt.total}."
        if hidden_names:
            body += f" Ukryty przed: {', '.join(hidden_names)}."
        if detected_names:
            body += f" Wykrywają: {', '.join(detected_names)}."
        self._add_message("Skradanie przed walką", body)
        self._record(
            "ui_precombat_stealth_resolved",
            {
                "actor_id": actor_id,
                "natural_roll": resolution.attempt.natural_roll,
                "total": resolution.attempt.total,
                "hidden_from_actor_ids": list(resolution.attempt.hidden_from_actor_ids),
                "detected_by_actor_ids": list(resolution.attempt.detected_by_actor_ids),
            },
        )
        self._sync_board_leds()
        return self.state_payload()

    def _precombat_visibility_adjustments(
        self,
        hiding_actor: Actor,
        encounter_actors: tuple[Actor, ...],
    ) -> tuple[dict[str, int], tuple[str, ...]]:
        passive_adjustments: dict[str, int] = {}
        automatically_hidden: list[str] = []
        for observer in encounter_actors:
            if (
                observer.faction == hiding_actor.faction
                or observer.faction == Faction.NEUTRAL
                or observer.is_defeated()
            ):
                continue
            distance_feet = (
                max(
                    abs(observer.position.col - hiding_actor.position.col),
                    abs(observer.position.row - hiding_actor.position.row),
                )
                * 5
            )
            visibility = exploration_visibility(
                observer,
                ambient_light=self.current_zone.ambient_light,
                distance_feet=distance_feet,
                party=encounter_actors,
            )
            if not visibility.can_see:
                automatically_hidden.append(str(observer.id))
            elif visibility.passive_perception_adjustment:
                passive_adjustments[str(observer.id)] = (
                    visibility.passive_perception_adjustment
                )
        return passive_adjustments, tuple(automatically_hidden)

    def _seed_precombat_stealth_from_exploration(self) -> None:
        if (
            self.encounter_setup_flow is None
            or not self.encounter_setup_flow.completed
            or self.pending_encounter is None
            or not precombat_stealth_is_available(
                self.pending_encounter.opening_resolution
            )
        ):
            return
        encounter_actors = self.encounter_setup_flow.encounter.actors
        attempts = list(self.pending_encounter.precombat_stealth_attempts)
        attempted_ids = {attempt.actor_id for attempt in attempts}
        seeded_ids: list[str] = []
        for hidden in self.state.hidden_actor_states:
            if (
                hidden.zone_id != self.current_zone.id
                or hidden.actor_id in attempted_ids
            ):
                continue
            actor = next(
                (
                    candidate
                    for candidate in encounter_actors
                    if str(candidate.id) == hidden.actor_id
                ),
                None,
            )
            if actor is None or actor.faction != Faction.ALLY or actor.is_defeated():
                continue
            adjustments, automatically_hidden = (
                self._precombat_visibility_adjustments(actor, encounter_actors)
            )
            hiding = resolve_hide(
                (),
                actor,
                encounter_actors,
                hidden.stealth_total,
                passive_perception_adjustments=adjustments,
                automatically_hidden_from_actor_ids=automatically_hidden,
            )
            attempts.append(
                PrecombatStealthAttempt(
                    actor_id=hidden.actor_id,
                    natural_roll=hidden.natural_roll,
                    total=hidden.stealth_total,
                    hidden_from_actor_ids=(
                        hiding.hidden_state.hidden_from_actor_ids
                        if hiding.hidden_state is not None
                        else ()
                    ),
                    detected_by_actor_ids=hiding.detected_by_actor_ids,
                )
            )
            attempted_ids.add(hidden.actor_id)
            seeded_ids.append(hidden.actor_id)
        if not seeded_ids:
            return
        self.pending_encounter = replace(
            self.pending_encounter,
            precombat_stealth_attempts=tuple(attempts),
        )
        self.state = replace(
            self.state,
            hidden_actor_states=tuple(
                item
                for item in self.state.hidden_actor_states
                if item.actor_id not in set(seeded_ids)
            ),
        )
        self._add_message(
            "Ukrycie przeniesione do encountera",
            (
                "Zapisane wyniki Stealth zostały porównane z percepcją "
                "przeciwników po rozstawieniu figurek."
            ),
        )

    def finish_precombat_stealth(self) -> dict[str, object]:
        if self.encounter_setup_flow is None or not self.encounter_setup_flow.completed:
            raise ValueError("Najpierw zakończ setup encountera.")
        if self.pending_encounter is None:
            raise ValueError("Nie ma aktywnego encountera.")
        if not precombat_stealth_is_available(self.pending_encounter.opening_resolution):
            raise ValueError("Ten encounter nie ma etapu skradania przed walką.")
        self.pending_encounter = replace(
            self.pending_encounter,
            precombat_stealth_completed=True,
        )
        attempts = self.pending_encounter.precombat_stealth_attempts
        self._add_message(
            "Skradanie zakończone",
            (
                f"Zapisano próby skradania {len(attempts)} bohaterów. Możecie przejść do inicjatywy."
                if attempts
                else "Drużyna pomija skradanie i przechodzi do inicjatywy."
            ),
        )
        self._record(
            "ui_precombat_stealth_finished",
            {"attempted_actor_ids": [attempt.actor_id for attempt in attempts]},
        )
        self._sync_board_leds()
        return self.state_payload()

    def _clear_player_pending_choices(self) -> None:
        self.pending_state.clear_player_choices()
        self.pending_spell_zone_move_effect_id = ""
        self.combat_targeting_attack_source_id = None
        self.combat_targeting_healing_source_id = None
        self.combat_targeting_class_feature_action_id = None
        self.combat_selected_class_feature_target_id = None
        self.combat_selected_class_feature_target_ids = ()
        self.combat_aux_targeting_mode = None
        self.combat_stabilization_method = None
        self.combat_stabilization_target_id = None
        self.pending_physical_feature_action_id = None

    def start_combat_stabilization_targeting(
        self,
        method: str,
    ) -> dict[str, object]:
        if self.combat_state is None:
            raise ValueError("Walka nie została rozpoczęta.")
        stabilization_method = StabilizationMethod(method)
        actor = combat_current_actor(self.combat_state)
        targets = legal_stabilization_targets(self.combat_state, actor)
        if not targets:
            raise ValueError("Brak legalnego celu stabilizacji.")
        self.combat_stabilization_method = stabilization_method.value
        self.combat_stabilization_target_id = None
        self.pending_combat_context_menu = None
        self.board_message = "Wskaż podświetlonego nieprzytomnego sojusznika."
        self._sync_board_leds()
        return self.state_payload()

    def start_combat_aux_targeting(self, mode: str) -> dict[str, object]:
        allowed = {
            "twinned_attack",
            "twinned_healing",
            "sculpt_spells",
            "careful_spell",
            "heightened_spell",
        }
        if mode not in allowed or not self._combat_aux_targets(mode):
            raise ValueError("Brak legalnych celów dla tego wyboru.")
        self.combat_aux_targeting_mode = mode
        self.board_message = "Zeskanuj planszę i kliknij podświetloną figurkę."
        self._sync_board_leds()
        return self.state_payload()

    def finish_combat_aux_targeting(self) -> dict[str, object]:
        self.combat_aux_targeting_mode = None
        self.board_message = "Zakończono wybór dodatkowych celów."
        self._sync_board_leds()
        return self.state_payload()

    def _combat_aux_targets(self, mode: str) -> tuple[Actor, ...]:
        if self.combat_state is None:
            return ()
        actor = combat_current_actor(self.combat_state)
        encounter = self._active_encounter()
        if mode == "twinned_attack" and self.pending_player_attack and encounter:
            pending = self.pending_player_attack
            source = self._attack_source_by_id(
                actor,
                pending.source_id,
                pending.cast_level,
            )
            return (
                tuple(
                    target
                    for target in start_attack_action(
                        encounter.board,
                        actor,
                        self.combat_state.actors,
                        source,
                        self.combat_state.hidden_states,
                    ).legal_targets
                    if str(target.id) != pending.target_id
                )
                if source is not None
                else ()
            )
        if mode == "twinned_healing" and self.pending_player_healing and encounter:
            source = self._selected_healing_source(actor)
            return (
                tuple(
                    target
                    for target in legal_healing_targets(
                        encounter.board,
                        actor,
                        self.combat_state.actors,
                        source,
                    )
                    if str(target.id) != self.pending_player_healing.target_id
                )
                if source is not None
                else ()
            )
        pending = self.pending_area_spell
        if pending is None:
            return ()
        ids = set(pending.target_ids) | set(pending.protected_target_ids)
        if mode == "sculpt_spells":
            return tuple(
                target
                for target in self.combat_state.actors
                if str(target.id) in ids
                and target.faction == actor.faction
                and target.id != actor.id
            )
        if mode in {"careful_spell", "heightened_spell"}:
            return tuple(
                target
                for target in self.combat_state.actors
                if str(target.id) in ids
            )
        return ()

    def _attack_sources_for_actor(self, actor: Actor) -> tuple:
        wild_shape_source = wild_shape_attack_source(actor)
        if wild_shape_source is not None:
            return (wild_shape_source,)
        if self.combat_state is not None:
            summoned = summoned_state_for_actor(
                self.combat_state.summoned_creatures,
                actor.id,
            )
            if summoned is not None:
                owner = self._actor_by_string_id(
                    str(summoned.owner_actor_id)
                )
                return (
                    summon_attack_source(summoned.definition, owner),
                )
        encounter = self._active_encounter()
        if encounter is None:
            return ()
        reserved_hands = (
            len(grappled_actor_ids(self.combat_state.condition_states, str(actor.id)))
            if self.combat_state is not None
            else 0
        )
        sources = _encounter_attack_sources(
            encounter,
            actor,
            reserved_hands=reserved_hands,
        )
        familiar = next(
            (
                effect
                for effect in self.active_combat_effects
                if effect.source_actor_id == str(actor.id)
                and effect.kind.startswith("familiar:")
            ),
            None,
        )
        if familiar is None:
            return sources
        if familiar.kind == "familiar:raven":
            return tuple(
                replace(
                    source,
                    attack_roll_request=replace(
                        source.attack_roll_request,
                        mode=RollMode.ADVANTAGE,
                    ),
                )
                if source.source_type is AttackSourceType.SPELL
                else source
                for source in sources
            )
        if familiar.kind != "familiar:snake":
            return sources
        snake_attack = AttackSource(
            id="familiar_snake_bite",
            name="Ukąszenie chowańca",
            source_type=AttackSourceType.SPELL,
            range_feet=30,
            attack_kind=AttackKind.RANGED,
            attack_roll_request=D20RollRequest(
                modifiers=(
                    RollModifier(
                        "Atak chowańca",
                        max(0, actor.spell_save_dc - 8),
                        RollModifierType.SPELL,
                        "find_familiar",
                    ),
                ),
            ),
            damage_hint="1k6 trucizny",
            damage_die_sides=6,
            damage_type="poison",
            action_cost=ActionEconomyCost.BONUS_ACTION,
        )
        return (*sources, snake_attack)

    def _selected_attack_source(self, actor: Actor):
        sources = self._attack_sources_for_actor(actor)
        if not sources:
            return None
        selected_id = self.selected_attack_source_ids.get(str(actor.id))
        if selected_id:
            source_id, cast_level, metamagic_ids = _decode_source_selection(selected_id)
            selected = next((source for source in sources if source.id == source_id), None)
            if selected is not None and cast_level is not None:
                selected = attack_source_at_cast_level(selected, cast_level)
            if selected is not None and metamagic_ids:
                selected = apply_metamagic_to_source(actor, selected, metamagic_ids)
            if selected is not None and self._actor_can_use_attack_source(actor, selected):
                return selected
        return next((source for source in sources if self._actor_can_use_attack_source(actor, source)), sources[0])

    def _attack_source_by_id(
        self,
        actor: Actor,
        source_id: str,
        cast_level: int | None = None,
    ):
        sources = self._attack_sources_for_actor(actor)
        if source_id:
            source = next((candidate for candidate in sources if candidate.id == source_id), None)
            if source is not None:
                selected = (
                    attack_source_at_cast_level(source, cast_level)
                    if cast_level is not None
                    else source
                )
                stored = self.selected_attack_source_ids.get(str(actor.id), "")
                stored_id, stored_level, metamagic_ids = _decode_source_selection(stored)
                if (
                    metamagic_ids
                    and stored_id == source_id
                    and stored_level == cast_level
                ):
                    selected = apply_metamagic_to_source(
                        actor,
                        selected,
                        metamagic_ids,
                        validate_resources=False,
                    )
                return selected
        return self._selected_attack_source(actor)

    def _actor_can_use_attack_source(self, actor: Actor, source) -> bool:
        from dnd_board_game.inventory import item_power_available

        if source is None:
            return False
        if not _source_is_prepared(actor, source):
            return False
        source_item_id = getattr(source, "source_item_id", None)
        if source_item_id is not None:
            item = _inventory_item_for_attack_source(actor, source_item_id)
            if item is None or not item_power_available(item) or not item.equipped:
                return False
        resource_pool_id = getattr(source, "resource_pool_id", None)
        if resource_pool_id is not None and not can_spend_actor_resource(
            actor,
            resource_pool_id,
            int(getattr(source, "resource_cost", 1)),
        ):
            return False
        ammunition_type = getattr(source, "ammunition_type", None)
        if ammunition_type is not None and not has_ammunition(actor, ammunition_type):
            return False
        if (
            bool(getattr(source, "loading", False))
            and self.combat_state is not None
            and self.combat_state.turn_action.attack_action_active
            and self.combat_state.turn_action.attacks_used >= 1
        ):
            return False
        return can_consume_spell_resource(
            actor,
            getattr(source, "spell_level", 0),
            spell_id=str(getattr(source, "id", "")),
        )

    def _actor_can_use_healing_source(self, actor: Actor, source: HealingSource | None) -> bool:
        from dnd_board_game.inventory import item_power_available

        if source is None:
            return False
        if not _source_is_prepared(actor, source):
            return False
        source_item_id = getattr(source, "source_item_id", None)
        if source_item_id is not None:
            item = _inventory_item_for_attack_source(actor, source_item_id)
            if item is None or not item_power_available(item) or not item.equipped:
                return False
        if source.resource_pool_id is not None and not can_spend_actor_resource(
            actor,
            source.resource_pool_id,
            source.resource_cost,
        ):
            return False
        if source.id == "goodberry_use":
            return True
        return can_consume_spell_resource(
            actor,
            getattr(source, "spell_level", 0),
            spell_id=str(getattr(source, "id", "")),
        )

    def _healing_sources_for_actor(self, actor: Actor) -> tuple[HealingSource, ...]:
        encounter = self._active_encounter()
        if encounter is None:
            return ()
        sources = encounter.healing_sources_by_actor.get(actor.id, ())
        goodberry = _goodberry_healing_source(actor)
        if goodberry is None:
            return sources
        return (*sources, goodberry)

    def _selected_healing_source(self, actor: Actor) -> HealingSource | None:
        sources = self._healing_sources_for_actor(actor)
        if not sources:
            return None
        selected_id = self.selected_healing_source_ids.get(str(actor.id))
        if selected_id:
            source_id, cast_level, metamagic_ids = _decode_source_selection(selected_id)
            selected = next((source for source in sources if source.id == source_id), None)
            if selected is not None and cast_level is not None:
                selected = healing_source_at_cast_level(selected, cast_level)
            if selected is not None and metamagic_ids:
                selected = apply_metamagic_to_source(actor, selected, metamagic_ids)
            if selected is not None:
                return selected
        return sources[0]

    def cast_exploration_ritual(
        self,
        actor_id: str,
        spell_id: str,
        target_id: str = "",
        *,
        message: str = "",
        trigger_description: str = "",
    ) -> dict[str, object]:
        if self.combat_state is not None:
            raise ValueError("Nie można rozpocząć rytuału podczas walki.")
        if self.ui_flow_stage != UiFlowStage.LOCATION_ACTIVE:
            raise ValueError("Rytuał można rozpocząć podczas aktywnej eksploracji.")
        if self.pending is not None:
            raise ValueError("Najpierw dokończ bieżącą decyzję eksploracyjną.")
        search_result = self._locating_divination_result(spell_id, target_id)
        prepared_target = self._exploration_spell_target(
            spell_id,
            target_id,
            message=message,
            trigger_description=trigger_description,
        )
        if spell_id == "protection_from_poison":
            caster = next(
                actor
                for actor in self.exploration.actors
                if str(actor.id) == actor_id
            )
            target_actor = next(
                (
                    actor
                    for actor in self.exploration.actors
                    if str(actor.id) == prepared_target
                ),
                None,
            )
            if (
                target_actor is None
                or target_actor.faction != caster.faction
                or grid_distance_feet(caster.position, target_actor.position) > 5
            ):
                raise ValueError(
                    "Ochrona przed trucizną wymaga sprzymierzonego celu w zasięgu dotyku."
                )
        result = self.ritual_casting_flow.cast(
            actors=self.exploration.actors,
            state=self.state,
            actor_id=actor_id,
            spell_id=spell_id,
            target_id=prepared_target or (
                self.active_point.id if self.active_point is not None else ""
            ),
        )
        self.exploration = replace(self.exploration, actors=result.actors)
        self.state = result.state
        self.state = clear_exploration_hidden(self.state)
        self._advance_party_lights(result.elapsed_minutes)
        self._add_message(
            "Rytuał",
            (
                f"{result.actor_before.name} rzuca {result.spell_name} jako rytuał. "
                + (
                    f"Cel: {result.target_id}. "
                    if result.target_id
                    else ""
                )
                + f"Upływa {result.elapsed_minutes} minut; slot czaru nie został zużyty."
            ),
        )
        self._add_locating_divination_message(spell_id, search_result)
        self._add_expired_magic_effect_notices(result.expired_effects)
        self._add_clock_event_notices(result.triggered_clock_events)
        self._record(
            "ui_exploration_ritual_cast",
            {
                "actor_id": actor_id,
                "spell_id": spell_id,
                "target_id": result.target_id,
                "elapsed_minutes": result.elapsed_minutes,
            },
        )
        return self.state_payload()

    def cast_exploration_spell(
        self,
        actor_id: str,
        spell_id: str,
        *,
        cast_level: int | None = None,
        target_id: str = "",
        target_ids: tuple[str, ...] = (),
        healing_roll: int | None = None,
        rope_length_feet: int = 60,
        message: str = "",
        trigger_description: str = "",
    ) -> dict[str, object]:
        if self.combat_state is not None:
            raise ValueError("Ten przepływ czaru działa tylko poza walką.")
        if self.ui_flow_stage != UiFlowStage.LOCATION_ACTIVE:
            raise ValueError("Czar można rzucić podczas aktywnej eksploracji.")
        if self.pending is not None:
            raise ValueError("Najpierw dokończ bieżącą decyzję eksploracyjną.")
        search_result = self._locating_divination_result(spell_id, target_id)
        prepared_target = self._exploration_spell_target(
            spell_id,
            target_id,
            message=message,
            trigger_description=trigger_description,
            rope_length_feet=rope_length_feet,
        )
        target = (
            prepared_target
            or (
                self.active_point.id
                if self.active_point is not None
                else self.current_zone.id
            )
        )
        result = self.exploration_spell_casting_flow.cast(
            actors=self.exploration.actors,
            state=self.state,
            actor_id=actor_id,
            spell_id=spell_id,
            cast_level=cast_level,
            target_id=target,
            target_ids=target_ids,
            healing_roll=healing_roll,
        )
        self.exploration = replace(self.exploration, actors=result.actors)
        self.state = result.state
        if spell_id == "see_invisibility":
            self._add_message(
                "Widzenie niewidzialnego",
                (
                    f"{result.actor_before.name} przez godzinę widzi niewidzialne "
                    "istoty i przedmioty tak, jakby były widzialne. Efekt nie "
                    "zdejmuje z nich niewidzialności dla pozostałych postaci."
                ),
            )
        elif spell_id == "rope_trick":
            space = decode_rope_trick(str(result.timed_effect.flag_value))
            self._add_message(
                "Sztuczka z liną",
                (
                    f"Powstaje niewidoczna z zewnątrz przestrzeń na szczycie "
                    f"liny długości {space.rope_length_feet} ft. Mieści do 8 "
                    "istot Medium lub mniejszych; ataki i czary nie przechodzą "
                    "przez wejście. Efekt trwa godzinę."
                ),
            )
        elif spell_id == "protection_from_poison":
            self.state = replace(
                self.state,
                condition_states=remove_condition(
                    self.state.condition_states,
                    target,
                    CombatCondition.POISONED,
                ),
            )
            protected = next(
                actor for actor in self.exploration.actors if str(actor.id) == target
            )
            self._add_message(
                "Ochrona przed trucizną",
                (
                    f"Zneutralizowano aktywną truciznę działającą na {protected.name}. "
                    "Przez godzinę cel ma przewagę na rzuty obronne przeciw zatruciu "
                    "i odporność na obrażenia od trucizny."
                ),
            )
        elif spell_id == "prayer_of_healing":
            healed = ", ".join(
                (
                    f"{item.actor_before.name} +{item.effective_healing} PW "
                    f"({item.hp_before}→{item.hp_after})"
                )
                for item in result.healing_results
            ) or "brak legalnych celów"
            self._advance_party_lights(result.elapsed_minutes)
            self._add_message(
                "Modlitwa leczenia",
                (
                    f"{result.actor_before.name} kończy dziesięciominutową modlitwę. "
                    f"Wynik: {healed}. Zużyto slot {result.cast_level}. poziomu."
                ),
            )
            self._add_expired_magic_effect_notices(result.expired_effects)
            self._add_clock_event_notices(result.triggered_clock_events)
        elif spell_id == "pass_without_trace":
            self._add_message(
                "Przejście bez śladu",
                (
                    f"{result.actor_before.name} utrzymuje aurę w promieniu 30 ft. "
                    "Rzucający oraz sojusznicy pozostający w aurze otrzymują +10 "
                    "do Stealth i nie mogą być tropieni niemagicznie. Efekt wymaga "
                    "koncentracji."
                ),
            )
        else:
            self._add_message(
                "Magia eksploracyjna",
                (
                    f"{result.actor_before.name} rzuca {result.spell_name} "
                    f"na cel/scenę „{target}”. Zapisano znacznik "
                    f"{result.cast_flag}; scenariusz i narrator mogą teraz "
                    "rozstrzygnąć właściwy kontekst."
                ),
            )
        self._add_locating_divination_message(spell_id, search_result)
        self._record(
            "ui_exploration_spell_cast",
            {
                "actor_id": actor_id,
                "spell_id": spell_id,
                "cast_level": result.cast_level,
                "cast_flag": result.cast_flag,
                "target_id": target,
                "expires_at_minute": (
                    result.timed_effect.expires_at_minute
                    if result.timed_effect is not None
                    else None
                ),
            },
        )
        return self.state_payload()

    def enter_rope_trick_space(
        self,
        effect_id: str,
        actor_id: str,
    ) -> dict[str, object]:
        effect = self._rope_trick_effect(effect_id)
        actor = next(
            (
                candidate
                for candidate in self.exploration.actors
                if str(candidate.id) == actor_id
            ),
            None,
        )
        if actor is None:
            raise ValueError("Nieznana postać wchodząca do Sztuczki z liną.")
        updated = enter_rope_trick(effect, actor)
        self.state = apply_timed_magic_effect(self.state, updated)
        self._add_message(
            "Sztuczka z liną",
            f"{actor.name} wspina się po linie i wchodzi do pozawymiarowej przestrzeni.",
        )
        self._record(
            "ui_rope_trick_entered",
            {"effect_id": effect_id, "actor_id": actor_id},
        )
        return self.state_payload()

    def exit_rope_trick_space(
        self,
        effect_id: str,
        actor_id: str,
    ) -> dict[str, object]:
        effect = self._rope_trick_effect(effect_id)
        actor = next(
            (
                candidate
                for candidate in self.exploration.actors
                if str(candidate.id) == actor_id
            ),
            None,
        )
        if actor is None:
            raise ValueError("Nieznana postać wychodząca ze Sztuczki z liną.")
        updated = exit_rope_trick(effect, actor_id)
        self.state = apply_timed_magic_effect(self.state, updated)
        self._add_message(
            "Sztuczka z liną",
            f"{actor.name} schodzi z pozawymiarowej przestrzeni na planszę.",
        )
        self._record(
            "ui_rope_trick_exited",
            {"effect_id": effect_id, "actor_id": actor_id},
        )
        return self.state_payload()

    def _rope_trick_effect(self, effect_id: str) -> TimedMagicEffect:
        effect = next(
            (
                candidate
                for candidate in self.state.magic_effects
                if candidate.id == effect_id
                and candidate.spell_id == "rope_trick"
            ),
            None,
        )
        if effect is None:
            raise ValueError("Ta przestrzeń Sztuczki z liną nie jest aktywna.")
        return effect

    def _exploration_spell_target(
        self,
        spell_id: str,
        target_id: str,
        *,
        message: str,
        trigger_description: str,
        rope_length_feet: int = 60,
    ) -> str:
        if spell_id == "rope_trick":
            anchor_id = target_id.strip() or (
                self.active_point.id
                if self.active_point is not None
                else self.current_zone.id
            )
            return encode_rope_trick(
                RopeTrickSpace(
                    anchor_id=anchor_id,
                    rope_length_feet=rope_length_feet,
                )
            )
        if spell_id != "magic_mouth":
            return target_id.strip()
        object_id = target_id.strip() or (
            self.active_point.id if self.active_point is not None else ""
        )
        return encode_magic_mouth(
            MagicMouthSpecification(
                object_id=object_id,
                message=message,
                trigger_description=trigger_description,
            )
        )

    def _locating_divination_result(self, spell_id: str, query: str):
        kinds = {
            "locate_animals_or_plants": frozenset(
                {DivinationTargetKind.ANIMAL, DivinationTargetKind.PLANT}
            ),
            "locate_object": frozenset({DivinationTargetKind.OBJECT}),
        }.get(spell_id)
        if kinds is None:
            return None
        if not query.strip():
            raise ValueError("Wpisz znany gatunek albo nazwę szukanego celu.")
        origin = self.state.party_position.marker_position
        if origin is None and self.active_point is not None:
            origin = self.active_point.positions[0]
        return locate_authored_target(
            self.state.points,
            query=query,
            allowed_kinds=kinds,
            origin=origin or Coordinate(0, 0),
            maximum_distance_feet=(
                5 * 5280 if spell_id == "locate_animals_or_plants" else 1000
            ),
            blocked_by_lead=spell_id == "locate_object",
        )

    def _add_locating_divination_message(self, spell_id: str, result) -> None:
        if spell_id not in {"locate_animals_or_plants", "locate_object"}:
            return
        if result is None:
            self._add_message(
                "Wynik dywinacji",
                "W zasięgu czaru nie wyczuwasz pasującego celu.",
            )
            return
        self._add_message(
            "Wynik dywinacji",
            (
                f"Najbliższy pasujący cel znajduje się {result.distance_feet} ft "
                f"stąd, kierunek: {result.direction}."
            ),
        )

    def _timed_magic_effect_view(
        self,
        effect: TimedMagicEffect,
    ) -> dict[str, object]:
        payload = _timed_magic_effect_payload(
            effect,
            elapsed_minutes=self.state.elapsed_minutes,
        )
        if effect.spell_id != "locate_object":
            if effect.spell_id == "magic_mouth":
                specification = decode_magic_mouth(str(effect.flag_value))
                payload["value_label"] = (
                    f"Obiekt: {specification.object_id} · wyzwalacz: "
                    f"{specification.trigger_description}"
                )
                payload["magic_mouth"] = {
                    "object_id": specification.object_id,
                    "message": specification.message,
                    "trigger_description": specification.trigger_description,
                }
            elif effect.spell_id == "rope_trick":
                space = decode_rope_trick(str(effect.flag_value))
                actor_names = {
                    str(actor.id): actor.name
                    for actor in self.exploration.actors
                }
                payload["value_label"] = (
                    f"{len(space.occupant_actor_ids)}/8 osób · "
                    f"lina {space.rope_length_feet} ft"
                )
                payload["rope_trick"] = {
                    "anchor_id": space.anchor_id,
                    "rope_length_feet": space.rope_length_feet,
                    "occupant_actor_ids": list(space.occupant_actor_ids),
                    "occupant_names": [
                        actor_names.get(actor_id, actor_id)
                        for actor_id in space.occupant_actor_ids
                    ],
                    "rope_pulled_inside": space.rope_pulled_inside,
                }
            return payload
        result = self._locating_divination_result(
            effect.spell_id,
            str(effect.flag_value),
        )
        if result is None:
            payload["value_label"] = "Brak pasującego celu w zasięgu 1000 ft"
            return payload
        payload["value_label"] = (
            f"{result.distance_feet} ft · {result.direction}"
        )
        payload["divination"] = {
            "query": str(effect.flag_value),
            "distance_feet": result.distance_feet,
            "direction": result.direction,
        }
        return payload

    def _timed_combat_effects(self) -> tuple[ActiveCombatEffect, ...]:
        """Adapt exploration spells whose rules remain relevant in combat."""

        adapted: list[ActiveCombatEffect] = []
        for effect in self.state.magic_effects:
            if effect.spell_id == "pass_without_trace":
                adapted.append(
                    ActiveCombatEffect(
                        id=f"exploration:{effect.id}",
                        actor_id=effect.actor_id,
                        kind="stealth_bonus_aura",
                        label=effect.label,
                        object_id=f"spell:{effect.spell_id}",
                        value=10,
                        source_actor_id=effect.actor_id,
                        source=EffectSource(
                            EffectSourceType.SPELL,
                            effect.spell_id,
                            effect.label,
                        ),
                        duration=EffectDuration.CONCENTRATION,
                        stacking_key=f"concentration:{effect.actor_id}",
                    )
                )
            elif effect.spell_id == "protection_from_poison":
                adapted.append(
                    ActiveCombatEffect(
                        id=f"exploration:{effect.id}",
                        actor_id=str(effect.flag_value),
                        kind="protection_from_poison",
                        label=effect.label,
                        object_id=f"spell:{effect.spell_id}",
                        value=0,
                        source_actor_id=effect.actor_id,
                        source=EffectSource(
                            EffectSourceType.SPELL,
                            effect.spell_id,
                            effect.label,
                        ),
                        duration=EffectDuration.UNTIL_ENCOUNTER_END,
                        stacking_key=f"protection_from_poison:{effect.flag_value}",
                    )
                )
            elif effect.spell_id == "rope_trick":
                space = decode_rope_trick(str(effect.flag_value))
                for actor_id in space.occupant_actor_ids:
                    adapted.append(
                        ActiveCombatEffect(
                            id=f"exploration:{effect.id}:{actor_id}",
                            actor_id=actor_id,
                            kind="extradimensional_space",
                            label=effect.label,
                            object_id=f"spell:{effect.spell_id}:{effect.id}",
                            value=0,
                            source_actor_id=effect.actor_id,
                            source=EffectSource(
                                EffectSourceType.SPELL,
                                effect.spell_id,
                                effect.label,
                            ),
                            duration=EffectDuration.UNTIL_ENCOUNTER_END,
                            stacking_key=f"extradimensional_space:{actor_id}",
                        )
                    )
            elif effect.spell_id == "see_invisibility":
                adapted.append(
                    ActiveCombatEffect(
                        id=f"exploration:{effect.id}",
                        actor_id=effect.actor_id,
                        kind="see_invisibility",
                        label=effect.label,
                        object_id=f"spell:{effect.spell_id}",
                        value=0,
                        source_actor_id=effect.actor_id,
                        source=EffectSource(
                            EffectSourceType.SPELL,
                            effect.spell_id,
                            effect.label,
                        ),
                        duration=EffectDuration.UNTIL_ENCOUNTER_END,
                        stacking_key=f"see_invisibility:{effect.actor_id}",
                    )
                )
        return tuple(adapted)

    def _stealth_effects(self) -> tuple[ActiveCombatEffect, ...]:
        if self.combat_state is not None:
            return self.active_combat_effects
        effects = self.active_combat_effects
        for effect in self._timed_combat_effects():
            effects = apply_active_effect(effects, effect).active_effects
        return effects

    def select_combat_attack_source(
        self,
        source_id: str,
        cast_level: int | None = None,
        metamagic_ids: tuple[str, ...] = (),
    ) -> dict[str, object]:
        if self.combat_state is None:
            raise ValueError("Walka nie została rozpoczęta.")
        actor = combat_current_actor(self.combat_state)
        source = next(
            (
                candidate
                for candidate in self._attack_sources_for_actor(actor)
                if candidate.id == source_id
            ),
            None,
        )
        _validate_selected_cast_level(actor, source, cast_level)
        selected_source = (
            attack_source_at_cast_level(source, cast_level)
            if source is not None and cast_level is not None
            else source
        )
        if selected_source is not None:
            selected_source = apply_metamagic_to_source(
                actor,
                selected_source,
                metamagic_ids,
            )
        transition = self.player_combat_action_flow.select_attack_source(
            state=self.combat_state,
            sources=tuple(
                selected_source if candidate.id == source_id else candidate
                for candidate in self._attack_sources_for_actor(actor)
            ),
            source_id=source_id,
        )
        self._clear_player_pending_choices()
        self.selected_attack_source_ids[transition.actor_id] = _encode_cast_source_id(
            transition.source_id,
            cast_level,
            metamagic_ids,
        )
        self.combat_targeting_attack_source_id = transition.source_id
        self.board_message = transition.board_message
        self._add_message(transition.message_title, transition.message_body)
        self._record(transition.event_type, dict(transition.event_payload))
        self._sync_board_leds()
        return self.state_payload()

