    def select_multi_target_spell_target(
        self,
        target_id: str,
    ) -> dict[str, object]:
        pending = self.pending_multi_target_damage_spell
        if pending is None:
            raise ValueError("Nie ma czaru oczekującego na cele.")
        self.pending_multi_target_damage_spell = (
            self.player_multi_target_spell_flow.select_target(
                pending,
                target_id,
            )
        )
        selected = len(
            self.pending_multi_target_damage_spell.selected_target_ids
        )
        self.board_message = (
            f"Wybrano cele {selected}/"
            f"{self.pending_multi_target_damage_spell.projectile_count}."
        )
        self._sync_board_leds()
        return self.state_payload()

    def clear_multi_target_spell_targets(self) -> dict[str, object]:
        pending = self.pending_multi_target_damage_spell
        if pending is None:
            raise ValueError("Nie ma czaru oczekującego na cele.")
        self.pending_multi_target_damage_spell = (
            self.player_multi_target_spell_flow.clear_targets(pending)
        )
        self.board_message = "Wyczyszczono wybór celów pocisków."
        self._sync_board_leds()
        return self.state_payload()

    def confirm_multi_target_damage_spell(
        self,
        die_rolls: tuple[int, ...],
        natural_rolls: tuple[int, ...] = (),
    ) -> dict[str, object]:
        pending = self.pending_multi_target_damage_spell
        if pending is None:
            raise ValueError("Nie ma czaru oczekującego na rozstrzygnięcie.")
        if self.combat_state is None:
            raise ValueError("Walka nie została rozpoczęta.")
        actor = combat_current_actor(self.combat_state)
        encounter = self._active_encounter()
        if encounter is None:
            raise ValueError("Brak danych encountera dla aktywnej walki.")
        action = _combat_action_by_id(encounter, actor, pending.action_id)
        if action is None:
            raise ValueError("Nie znaleziono źródła oczekującego czaru.")
        allocations = tuple(
            ProjectileAllocation(
                target_id,
                int(die_roll),
                (
                    int(natural_rolls[index])
                    if index < len(natural_rolls)
                    else None
                ),
            )
            for index, (target_id, die_roll) in enumerate(zip(
                pending.selected_target_ids,
                die_rolls,
                strict=False,
            ))
        )
        transition = self.player_multi_target_spell_flow.confirm(
            state=self.combat_state,
            action=action,
            pending=pending,
            allocations=allocations,
        )
        for target_id in pending.selected_target_ids:
            target = next(
                (
                    candidate
                    for candidate in self.combat_state.actors
                    if str(candidate.id) == target_id
                ),
                None,
            )
            if target is not None:
                self._animate_ranged_projectile(actor, target)
        return self._apply_multi_target_spell_transition(transition)

    def cancel_multi_target_damage_spell(self) -> dict[str, object]:
        pending = self.pending_multi_target_damage_spell
        if pending is None:
            raise ValueError("Nie ma czaru oczekującego na anulowanie.")
        if self.combat_state is None:
            raise ValueError("Walka nie została rozpoczęta.")
        transition = self.player_multi_target_spell_flow.cancel(
            state=self.combat_state,
            pending=pending,
        )
        return self._apply_multi_target_spell_transition(transition)

    def _apply_multi_target_spell_transition(
        self,
        transition,
    ) -> dict[str, object]:
        self.combat_state = transition.state
        self.pending_multi_target_damage_spell = transition.pending
        if transition.board_message:
            self.board_message = transition.board_message
        self._add_message(transition.message_title, transition.message_body)
        self._record(transition.event_type, dict(transition.event_payload))
        if transition.scene_flag_changes:
            flags = self.state.flags
            for key, value in transition.scene_flag_changes:
                flags = set_scene_flag(flags, key, value)
            self.state = replace(self.state, flags=flags)
        self._apply_combat_trigger_events(
            tuple(
                EffectEvent(
                    EffectEventType.DAMAGE_TAKEN,
                    actor_id=str(applied.actor_after.id),
                )
                for applied in transition.applied_damages
                if applied.damage.total_applied > 0
            )
        )
        for applied in transition.applied_damages:
            self._maybe_prompt_concentration_check(applied)
            if self.pending_concentration_check is not None:
                break
        self._sync_board_leds()
        return self.state_payload()

    def _queue_physical_feature_prompt(
        self,
        action_id: str,
    ) -> dict[str, object]:
        if self.combat_state is None:
            raise ValueError("Walka nie została rozpoczęta.")
        actor = combat_current_actor(self.combat_state)
        available = {
            feature_action_id
            for feature in actor.features
            for feature_action_id in feature.action_ids
        }
        if action_id == "cunning_action":
            if not actor_has_feature(actor, "cunning_action"):
                raise ValueError("Aktywna postać nie posiada Sprytnej akcji.")
        elif action_id in {
            "second_wind",
            "sacred_weapon",
            "turn_the_unholy",
            "turn_undead",
            "wild_shape",
            "pact_weapon",
        }:
            if action_id not in available:
                raise ValueError("Aktywna postać nie posiada tej akcji klasowej.")
        elif action_id == "divine_smite":
            pending = self.pending_player_attack
            if (
                not actor_has_feature(actor, "divine_smite")
                or pending is None
                or pending.stage != "damage_roll"
                or not pending.hit
            ):
                raise ValueError(
                    "Divine Smite można zagrać dopiero po potwierdzonym "
                    "trafieniu bronią w zwarciu."
                )
            source = self._attack_source_by_id(
                actor,
                pending.source_id,
                pending.cast_level,
            )
            if (
                source is None
                or source.source_type != AttackSourceType.WEAPON
                or source.attack_kind != AttackKind.MELEE
            ):
                raise ValueError("Divine Smite wymaga trafienia bronią w zwarciu.")
            if not available_cast_levels(actor, 1):
                raise ValueError("Brak dostępnego slotu dla Divine Smite.")
        elif action_id == "deflect_missiles":
            window = self.pending_reaction_window
            if (
                window is None
                or window.current_option.kind != ReactionKind.DEFLECT_MISSILES
            ):
                raise ValueError(
                    "Deflect Missiles można zagrać wyłącznie po ujawnieniu "
                    "obrażeń trafiającego ataku dystansowego bronią."
                )
        else:
            raise ValueError("Ta karta nie korzysta z promptu cechy klasowej.")

        if action_id not in {"divine_smite", "deflect_missiles"}:
            self._clear_player_pending_choices()
        else:
            # These cards decorate an already pending hit/reaction. Clearing
            # player choices here would erase the window they are required to use.
            self.pending_physical_feature_action_id = None
        self.pending_physical_feature_action_id = action_id
        instructions = {
            "second_wind": "Rzuć k10 i wpisz wynik leczenia.",
            "sacred_weapon": "Wybierz wyposażoną broń, którą uświęcasz.",
            "turn_the_unholy": (
                "Wpisz rzuty obronne Mądrości podświetlonych czartów i nieumarłych."
            ),
            "turn_undead": "Wpisz rzuty obronne Mądrości podświetlonych nieumarłych.",
            "wild_shape": "Wybierz jedną z trzech bojowych form bestii.",
            "cunning_action": "Wybierz Sprint, Odwrót albo Ukrycie jako akcję bonusową.",
            "pact_weapon": "Wybierz jedną z trzech form przywoływanej broni paktu.",
            "divine_smite": "Wybierz poziom dostępnego slotu czaru.",
            "deflect_missiles": "Rzuć k10 i wpisz wynik redukcji pocisku.",
        }
        self.board_message = f"{player_label(action_id)}: {instructions[action_id]}"
        self._record(
            "ui_physical_feature_prompt_opened",
            {"actor_id": str(actor.id), "action_id": action_id},
        )
        self._sync_board_leds()
        return self.state_payload()

    def cancel_physical_feature_prompt(self) -> dict[str, object]:
        if self.pending_physical_feature_action_id is None:
            raise ValueError("Nie ma oczekującej karty cechy klasowej.")
        action_id = self.pending_physical_feature_action_id
        self.pending_physical_feature_action_id = None
        self.board_message = f"Anulowano kartę: {player_label(action_id)}."
        self._record(
            "ui_physical_feature_prompt_cancelled",
            {"action_id": action_id},
        )
        self._sync_board_leds()
        return self.state_payload()

    def apply_physical_metamagic(self, action_id: str) -> dict[str, object]:
        """Attach a scanned Metamagic card to the spell already being prepared."""

        if self.combat_state is None:
            raise ValueError("Walka nie została rozpoczęta.")
        if action_id not in PHYSICAL_METAMAGIC_ACTION_IDS:
            raise ValueError("Nieznana karta Metamagii.")
        if action_id == "metamagic_empowered":
            return self.activate_empowered_spell()

        caster = combat_current_actor(self.combat_state)
        caster_id = str(caster.id)

        def validated_attack_source(
            source_id: str,
            cast_level: int | None,
            metamagic_ids: tuple[str, ...],
        ):
            source = next(
                (
                    candidate
                    for candidate in self._attack_sources_for_actor(caster)
                    if candidate.id == source_id
                ),
                None,
            )
            if source is None or source.source_type != AttackSourceType.SPELL:
                raise ValueError("Metamagia wymaga przygotowanego czaru.")
            if cast_level is not None:
                source = attack_source_at_cast_level(source, cast_level)
            apply_metamagic_to_source(caster, source, metamagic_ids)
            return source

        if self.combat_targeting_attack_source_id is not None:
            encoded = self.selected_attack_source_ids.get(caster_id, "")
            source_id, cast_level, current = _decode_source_selection(encoded)
            if action_id in current:
                raise ValueError("Ta Metamagia jest już przypisana do przygotowanego czaru.")
            validated_attack_source(source_id, cast_level, (*current, action_id))
            self.selected_attack_source_ids[caster_id] = _encode_cast_source_id(
                source_id,
                cast_level,
                (*current, action_id),
            )
        elif self.combat_targeting_healing_source_id is not None:
            encoded = self.selected_healing_source_ids.get(caster_id, "")
            source_id, cast_level, current = _decode_source_selection(encoded)
            source = next(
                (
                    candidate
                    for candidate in self._healing_sources_for_actor(caster)
                    if candidate.id == source_id
                ),
                None,
            )
            if source is None or source.source_type != HealingSourceType.SPELL:
                raise ValueError("Metamagia wymaga przygotowanego czaru.")
            if cast_level is not None:
                source = healing_source_at_cast_level(source, cast_level)
            apply_metamagic_to_source(caster, source, (*current, action_id))
            if action_id in current:
                raise ValueError("Ta Metamagia jest już przypisana do przygotowanego czaru.")
            self.selected_healing_source_ids[caster_id] = _encode_cast_source_id(
                source_id,
                cast_level,
                (*current, action_id),
            )
        elif self.pending_player_attack is not None:
            pending = self.pending_player_attack
            validated_attack_source(
                pending.source_id,
                pending.cast_level,
                (*pending.metamagic_ids, action_id),
            )
            if action_id in pending.metamagic_ids:
                raise ValueError("Ta Metamagia jest już przypisana do przygotowanego czaru.")
            self.pending_player_attack = replace(
                pending,
                metamagic_ids=(*pending.metamagic_ids, action_id),
            )
        elif self.pending_area_spell is not None:
            pending = self.pending_area_spell
            validated_attack_source(
                pending.source_id,
                pending.cast_level,
                (*pending.metamagic_ids, action_id),
            )
            if action_id in pending.metamagic_ids:
                raise ValueError("Ta Metamagia jest już przypisana do przygotowanego czaru.")
            self.pending_area_spell = replace(
                pending,
                metamagic_ids=(*pending.metamagic_ids, action_id),
            )
        elif self.pending_player_healing is not None:
            pending = self.pending_player_healing
            source = next(
                (
                    candidate
                    for candidate in self._healing_sources_for_actor(caster)
                    if candidate.id == pending.source_id
                ),
                None,
            )
            if source is None or source.source_type != HealingSourceType.SPELL:
                raise ValueError("Metamagia wymaga przygotowanego czaru.")
            if pending.cast_level is not None:
                source = healing_source_at_cast_level(source, pending.cast_level)
            apply_metamagic_to_source(
                caster,
                source,
                (*pending.metamagic_ids, action_id),
            )
            if action_id in pending.metamagic_ids:
                raise ValueError("Ta Metamagia jest już przypisana do przygotowanego czaru.")
            self.pending_player_healing = replace(
                pending,
                metamagic_ids=(*pending.metamagic_ids, action_id),
            )
        else:
            raise ValueError(
                "Najpierw zagraj kartę czaru i przygotuj jego użycie, a dopiero potem zeskanuj Metamagię."
            )

        self.board_message = (
            f"{player_label(action_id)} przypisane do przygotowanego czaru. "
            "Dokończ wybór celów i rzut; koszt zostanie pobrany przy rozstrzygnięciu."
        )
        self._add_message("Metamagia", self.board_message)
        self._record(
            "ui_physical_metamagic_attached",
            {"caster_id": caster_id, "metamagic_id": action_id},
        )
        self._sync_board_leds()
        return self.state_payload()

    def use_combat_class_feature(
        self,
        action_id: str,
        *,
        natural_roll: int | None = None,
        target_id: str = "",
        points: int = 0,
        mode: str = "",
        slot_level: int = 0,
        source_item_id: str = "",
        form_id: str = "",
        saving_rolls: tuple[tuple[str, int], ...] = (),
        allocations: tuple[tuple[str, int], ...] = (),
    ) -> dict[str, object]:
        if self.combat_state is None:
            raise ValueError("Walka nie została rozpoczęta.")
        actor = combat_current_actor(self.combat_state)
        available = {
            feature_action_id
            for feature in actor.features
            for feature_action_id in feature.action_ids
        }
        if action_id == "cunning_action":
            if not actor_has_feature(actor, "cunning_action"):
                raise ValueError("Aktywna postać nie posiada Sprytnej akcji.")
            if mode == "dash":
                return self.use_combat_dash()
            if mode == "disengage":
                return self.use_combat_disengage()
            if mode == "hide":
                return self.start_combat_hide()
            raise ValueError("Sprytna akcja wymaga wyboru: Sprint, Odwrót albo Ukrycie.")
        if action_id not in available:
            raise ValueError("Aktywna postać nie posiada tej akcji klasowej.")
        self._clear_player_pending_choices()
        title = "Cecha klasowa"
        if action_id == "second_wind":
            if natural_roll is None:
                raise ValueError("Second Wind wymaga wyniku k10.")
            result = resolve_second_wind(self.combat_state, int(natural_roll))
            self.combat_state = result.state
            body = (
                f"{actor.name} używa Second Wind i odzyskuje "
                f"{result.healing.amount} PW."
            )
        elif action_id == "action_surge":
            result = resolve_action_surge(self.combat_state)
            self.combat_state = result.state
            body = f"{actor.name} używa Action Surge i odzyskuje akcję."
        elif action_id in {"defensive_stance", "instinctive_dodge"}:
            resource_id, label = (
                ("defensive_stance_uses", "Pozycja obronna")
                if action_id == "defensive_stance"
                else ("instinctive_dodge_uses", "Unik instynktowny")
            )
            result = resolve_limited_dodge(
                self.combat_state,
                self.active_combat_effects,
                feature_id=action_id,
                resource_id=resource_id,
                label=label,
            )
            self.combat_state = result.state
            self.active_combat_effects = result.active_effects
            body = (
                f"{actor.name} używa {label}. Ataki przeciw tej postaci mają "
                "utrudnienie do początku jej następnej tury."
            )
        elif action_id in {"exploit_weakness", "patient_shot"}:
            resource_id, label = (
                ("trick_uses", "Wykorzystanie słabości")
                if action_id == "exploit_weakness"
                else ("instinct", "Strzelecka cierpliwość")
            )
            result = resolve_archetype_attack_focus(
                self.combat_state,
                self.active_combat_effects,
                feature_id=action_id,
                resource_id=resource_id,
                label=label,
            )
            self.combat_state = result.state
            self.active_combat_effects = result.active_effects
            body = (
                f"{actor.name} używa {label}. Następny atak w tej turze ma przewagę."
            )
        elif action_id == "rage":
            result = resolve_rage(
                self.combat_state,
                self.active_combat_effects,
            )
            self.combat_state = result.state
            self.active_combat_effects = result.active_effects
            if result.activated:
                body = f"{actor.name} wpada w Rage."
            else:
                body = f"{actor.name} ręcznie kończy Rage."
                if result.exhaustion_added:
                    body += " Frenzy dodaje 1 poziom Wyczerpania."
        elif action_id == "reckless_attack":
            result = resolve_reckless_attack(
                self.combat_state,
                self.active_combat_effects,
            )
            self.combat_state = result.state
            self.active_combat_effects = result.active_effects
            body = f"{actor.name} deklaruje Reckless Attack."
        elif action_id == "bardic_inspiration":
            result = resolve_bardic_inspiration(
                self.combat_state,
                self.active_combat_effects,
                target_id=target_id,
            )
            self.combat_state = result.state
            self.active_combat_effects = result.active_effects
            body = (
                f"{actor.name} daje {result.target.name} Bardic Inspiration "
                f"k{result.die_sides}."
            )
        elif action_id == "lay_on_hands":
            result = resolve_lay_on_hands(
                self.combat_state,
                target_id,
                int(points),
            )
            self.combat_state = result.state
            body = (
                f"{actor.name} leczy {result.target_after.name} za "
                f"{result.healing.amount} PW przez Lay on Hands."
            )
        elif action_id == "preserve_life":
            selected = allocations or (
                ((target_id, int(points)),)
                if target_id and points
                else ()
            )
            result = resolve_preserve_life(
                self.combat_state,
                tuple(
                    PreserveLifeAllocation(actor_id, healing)
                    for actor_id, healing in selected
                ),
            )
            self.combat_state = result.state
            body = (
                f"{actor.name} używa Preserve Life i rozdziela "
                f"{result.healing_spent} PW."
            )
        elif action_id == "patient_defense":
            result = resolve_patient_defense(
                self.combat_state,
                self.active_combat_effects,
            )
            self.combat_state = result.state
            self.active_combat_effects = result.active_effects
            body = f"{actor.name} wydaje 1 Ki na Patient Defense."
        elif action_id == "step_of_the_wind":
            result = resolve_step_of_the_wind(
                self.combat_state,
                self.active_combat_effects,
            )
            self.combat_state = result.state
            self.active_combat_effects = result.active_effects
            body = f"{actor.name} wydaje 1 Ki na Step of the Wind."
        elif action_id == "font_of_magic":
            result = resolve_font_of_magic(
                self.combat_state,
                mode=mode,
                slot_level=int(slot_level),
            )
            self.combat_state = result.state
            if mode == "slot_to_points":
                body = (
                    f"{actor.name} zamienia slot {slot_level}. poziomu na "
                    f"{result.conversion.sorcery_points_changed} Sorcery Points."
                )
            else:
                body = (
                    f"{actor.name} tworzy tymczasowy slot {slot_level}. poziomu "
                    f"za {-result.conversion.sorcery_points_changed} Sorcery Points."
                )
        elif action_id == "martial_arts_bonus_attack":
            result = resolve_martial_arts_bonus_attack(self.combat_state)
            self.combat_state = result.state
            body = (
                f"{actor.name} wydaje bonus action i może wykonać "
                "jeden Unarmed Strike."
            )
        elif action_id == "flurry_of_blows":
            result = resolve_flurry_of_blows(self.combat_state)
            self.combat_state = result.state
            self.active_combat_effects = (
                *tuple(
                    effect
                    for effect in self.active_combat_effects
                    if not (
                        effect.actor_id == str(actor.id)
                        and effect.kind == "flurry_of_blows"
                    )
                ),
                ActiveCombatEffect(
                    id=f"flurry-of-blows:{actor.id}",
                    actor_id=str(actor.id),
                    kind="flurry_of_blows",
                    label="Flurry of Blows",
                    object_id="class_feature:flurry_of_blows",
                    value=2,
                    source_actor_id=str(actor.id),
                    duration=EffectDuration.UNTIL_TURN_END,
                    expiration_actor_id=str(actor.id),
                ),
            )
            body = (
                f"{actor.name} wydaje 1 Ki i może wykonać "
                "dwa Unarmed Strikes."
            )
        elif action_id == "divine_sense":
            encounter = self._active_encounter()
            result = resolve_divine_sense(
                self.combat_state,
                board=encounter.board if encounter is not None else None,
            )
            self.combat_state = result.state
            detected = ", ".join(result.detected_creature_types)
            body = (
                f"{actor.name} używa Divine Sense. Wykryte typy: {detected}."
                if detected
                else f"{actor.name} używa Divine Sense i nie wykrywa żadnej obecności."
            )
        elif action_id == "sacred_weapon":
            result = resolve_sacred_weapon(
                self.combat_state,
                self.active_combat_effects,
                weapon_item_id=source_item_id,
            )
            self.combat_state = result.state
            self.active_combat_effects = result.active_effects
            body = (
                f"{actor.name} uświęca broń {result.weapon_item_id}; "
                f"premia do trafienia +{result.attack_bonus}."
            )
        elif action_id == "wild_shape":
            result = resolve_wild_shape(
                self.combat_state,
                form_id=form_id,
            )
            self.combat_state = result.state
            body = (
                f"{actor.name} wraca do swojej normalnej postaci."
                if result.reverted
                else (
                    f"{actor.name} przyjmuje formę "
                    f"{result.actor_after.wild_shape.form_name}."
                )
            )
        elif action_id in {"turn_undead", "turn_the_unholy"}:
            encounter = self._active_encounter()
            result = resolve_channel_turn(
                self.combat_state,
                action_id=action_id,
                saving_rolls=dict(saving_rolls),
                board=encounter.board if encounter is not None else None,
            )
            self.combat_state = result.state
            body = (
                f"{actor.name} używa "
                f"{'Turn Undead' if action_id == 'turn_undead' else 'Turn the Unholy'}. "
                f"Odpędzeni: {len(result.turned_target_ids)}, "
                f"udane rzuty obronne: {len(result.successful_save_target_ids)}."
            )
        elif action_id == "primeval_awareness":
            result = resolve_primeval_awareness(
                self.combat_state,
                slot_level=int(slot_level),
            )
            self.combat_state = result.state
            detected = ", ".join(result.detected_creature_types)
            body = (
                f"{actor.name} wyczuwa typy: {detected}. "
                f"Efekt trwa {result.duration_minutes} min."
                if detected
                else (
                    f"{actor.name} nie wyczuwa właściwych typów istot. "
                    f"Efekt trwa {result.duration_minutes} min."
                )
            )
        elif action_id == "frenzy":
            result = resolve_frenzy(
                self.combat_state,
                self.active_combat_effects,
            )
            self.combat_state = result.state
            self.active_combat_effects = result.active_effects
            body = (
                f"{actor.name} aktywuje Szał bojowy. Dodatkowy atak będzie dostępny od następnej tury; po zakończeniu Szału otrzyma 1 poziom Wyczerpania."
                if result.activated
                else f"{actor.name} wydaje akcję dodatkową na dodatkowy atak z Szału bojowego."
            )
        elif action_id == "pact_weapon":
            if form_id not in PACT_WEAPON_FORM_IDS:
                raise ValueError("Nieznana forma Pact Weapon.")
            item_data = _read_item_definition(self.scenario_path, form_id)
            weapon = _inventory_item_from_item_data(
                item_data,
                quantity=1,
                equipped=False,
                source_ref=form_id,
                property_catalog=_load_item_property_catalog(self.scenario_path),
            )
            result = resolve_pact_weapon(self.combat_state, weapon)
            self.combat_state = result.state
            body = (
                f"{actor.name} przywołuje Pact Weapon w formie "
                f"{weapon.name}."
            )
        else:
            raise ValueError(
                "Ta akcja klasowa jest widoczna, ale wymaga dedykowanego "
                "okna reakcji albo rozstrzygnięcia ataku."
            )
        self._clear_player_pending_choices()
        self.board_message = body
        self._add_message(title, body)
        self._record(
            "ui_combat_class_feature_used",
            {
                "actor_id": str(actor.id),
                "action_id": action_id,
                "target_id": target_id,
                "points": int(points),
            },
        )
        self._sync_board_leds()
        return self.state_payload()

    def start_combat_class_feature_targeting(
        self,
        action_id: str,
    ) -> dict[str, object]:
        if self.combat_state is None:
            raise ValueError("Walka nie została rozpoczęta.")
        actor = combat_current_actor(self.combat_state)
        available = {
            feature_action_id
            for feature in actor.features
            for feature_action_id in feature.action_ids
        }
        if action_id not in available:
            raise ValueError("Aktywna postać nie posiada tej akcji klasowej.")
        if action_id not in {"bardic_inspiration", "lay_on_hands", "preserve_life"}:
            raise ValueError("Ta cecha nie korzysta jeszcze z tego trybu wyboru.")
        targets = self._class_feature_board_targets(action_id, actor)
        if not targets:
            raise ValueError(f"Brak legalnego celu: {player_label(action_id)}.")
        self._clear_player_pending_choices()
        self.combat_targeting_attack_source_id = None
        self.combat_targeting_class_feature_action_id = action_id
        self.combat_selected_class_feature_target_id = None
        self.combat_selected_class_feature_target_ids = ()
        self.board_message = (
            f"{player_label(action_id)}: zeskanuj planszę i kliknij "
            "podświetloną figurkę legalnego celu. "
            + (
                "Koszt po wyborze: akcja bonusowa i 1 użycie Inspiracji."
                if action_id == "bardic_inspiration"
                else "Koszt po potwierdzeniu: akcja i 1 użycie Boskiej Mocy."
                if action_id == "preserve_life"
                else "Koszt zostanie pokazany przed potwierdzeniem."
            )
        )
        self._record(
            "ui_combat_class_feature_targeting_started",
            {
                "actor_id": str(actor.id),
                "action_id": action_id,
                "target_ids": [str(target.id) for target in targets],
            },
        )
        self._sync_board_leds()
        return self.state_payload()

    def cancel_combat_class_feature_targeting(self) -> dict[str, object]:
        if self.combat_targeting_class_feature_action_id is None:
            raise ValueError("Nie trwa wybór celu cechy klasowej.")
        self.combat_targeting_class_feature_action_id = None
        self.combat_selected_class_feature_target_id = None
        self.combat_selected_class_feature_target_ids = ()
        self.board_message = "Anulowano wybór celu cechy klasowej."
        self._sync_board_leds()
        return self.state_payload()

    def _class_feature_board_targets(
        self,
        action_id: str,
        actor: Actor,
    ) -> tuple[Actor, ...]:
        if self.combat_state is None:
            return ()
        if action_id == "lay_on_hands":
            return tuple(
                target
                for target in self.combat_state.actors
                if target.faction == actor.faction
                and not target.is_defeated()
                and target.hp < target.max_hp
                and grid_distance_feet(actor.position, target.position) <= 5
            )
        if action_id == "preserve_life":
            return tuple(
                target
                for target in self.combat_state.actors
                if target.faction == actor.faction
                and not target.is_defeated()
                and target.hp * 2 < target.max_hp
                and grid_distance_feet(actor.position, target.position) <= 30
            )
        if action_id != "bardic_inspiration":
            return ()
        inspired_ids = {
            effect.actor_id
            for effect in self.active_combat_effects
            if effect.kind == "bardic_inspiration"
        }
        return tuple(
            target
            for target in self.combat_state.actors
            if target.faction == actor.faction
            and target.id != actor.id
            and not target.is_defeated()
            and str(target.id) not in inspired_ids
            and grid_distance_feet(actor.position, target.position) <= 60
        )

    def start_long_cast(
        self,
        action_id: str,
        *,
        cast_level: int | None = None,
    ) -> dict[str, object]:
        if self.combat_state is None:
            raise ValueError("Walka nie została rozpoczęta.")
        actor = combat_current_actor(self.combat_state)
        if actor.faction != Faction.ALLY:
            raise ValueError("To nie jest tura bohatera.")
        action = self._long_cast_action(actor, action_id)
        transition = self.long_casting_flow.start(
            state=self.combat_state,
            active_effects=self.active_combat_effects,
            action=action,
            cast_level=cast_level,
        )
        self._clear_player_pending_choices()
        return self._apply_long_cast_transition(transition)

    def start_summon(
        self,
        action_id: str,
        *,
        cast_level: int | None = None,
    ) -> dict[str, object]:
        if self.combat_state is None:
            raise ValueError("Walka nie została rozpoczęta.")
        actor = combat_current_actor(self.combat_state)
        if actor.faction != Faction.ALLY:
            raise ValueError("To nie jest tura bohatera.")
        encounter = self._active_encounter()
        if encounter is None:
            raise ValueError("Brak danych encountera dla aktywnej walki.")
        action = _combat_action_by_id(encounter, actor, action_id)
        if action is None or action.action_type != "summon":
            raise ValueError("Nieznany czar przywołania.")
        transition = self.summoning_flow.prepare(
            board=encounter.board,
            state=self.combat_state,
            active_effects=self.active_combat_effects,
            action=action,
            cast_level=cast_level,
        )
        self._clear_player_pending_choices()
        return self._apply_summoning_transition(transition)

    def confirm_summon(self, *, col: int, row: int) -> dict[str, object]:
        pending = self.pending_summon
        if pending is None or self.combat_state is None:
            raise ValueError("Nie ma przywołania do potwierdzenia.")
        actor = combat_current_actor(self.combat_state)
        encounter = self._active_encounter()
        if encounter is None:
            raise ValueError("Brak danych encountera dla aktywnej walki.")
        action = _combat_action_by_id(encounter, actor, pending.action_id)
        if action is None:
            raise ValueError("Nieznany czar przywołania.")
        transition = self.summoning_flow.confirm(
            board=encounter.board,
            state=self.combat_state,
            active_effects=self.active_combat_effects,
            action=action,
            pending=pending,
            position=Coordinate(int(col), int(row)),
        )
        return self._apply_summoning_transition(transition)

    def cancel_summon(self) -> dict[str, object]:
        pending = self.pending_summon
        if pending is None or self.combat_state is None:
            raise ValueError("Nie ma przywołania do anulowania.")
        transition = self.summoning_flow.cancel(
            state=self.combat_state,
            active_effects=self.active_combat_effects,
            pending=pending,
        )
        return self._apply_summoning_transition(transition)

    def start_magic_movement(
        self,
        action_id: str,
        *,
        cast_level: int | None = None,
    ) -> dict[str, object]:
        if self.combat_state is None:
            raise ValueError("Walka nie została rozpoczęta.")
        actor = combat_current_actor(self.combat_state)
        if actor.faction != Faction.ALLY:
            raise ValueError("To nie jest tura bohatera.")
        encounter = self._active_encounter()
        if encounter is None:
            raise ValueError("Brak danych encountera dla aktywnej walki.")
        action = _combat_action_by_id(encounter, actor, action_id)
        if action is None or action.action_type != "spell_movement":
            raise ValueError("Nieznany czar przemieszczający.")
        transition = self.magic_movement_flow.prepare(
            board=encounter.board,
            state=self.combat_state,
            action=action,
            cast_level=cast_level,
            scene_objects=encounter.scene_objects,
            active_effects=self.active_combat_effects,
        )
        self._clear_player_pending_choices()
        return self._apply_magic_movement_transition(transition)

    def confirm_magic_movement(
        self,
        *,
        col: int | None = None,
        row: int | None = None,
        target_id: str | None = None,
    ) -> dict[str, object]:
        pending = self.pending_magic_movement
        if pending is None or self.combat_state is None:
            raise ValueError("Nie ma magicznego ruchu do potwierdzenia.")
        actor = combat_current_actor(self.combat_state)
        encounter = self._active_encounter()
        if encounter is None:
            raise ValueError("Brak danych encountera dla aktywnej walki.")
        action = _combat_action_by_id(encounter, actor, pending.action_id)
        if action is None:
            raise ValueError("Nieznany czar przemieszczający.")
        position = (
            Coordinate(int(col), int(row))
            if col is not None and row is not None
            else None
        )
        transition = self.magic_movement_flow.confirm(
            board=encounter.board,
            state=self.combat_state,
            action=action,
            pending=pending,
            rng=self.encounter_rng,
            position=position,
            target_id=target_id,
            scene_objects=encounter.scene_objects,
            active_effects=self.active_combat_effects,
        )
        return self._apply_magic_movement_transition(transition)

    def cancel_magic_movement(self) -> dict[str, object]:
        pending = self.pending_magic_movement
        if pending is None or self.combat_state is None:
            raise ValueError("Nie ma magicznego ruchu do anulowania.")
        transition = self.magic_movement_flow.cancel(
            state=self.combat_state,
            pending=pending,
        )
        return self._apply_magic_movement_transition(transition)

    def start_moonbeam_move(self, effect_id: str) -> dict[str, object]:
        if self.combat_state is None:
            raise ValueError("Walka nie została rozpoczęta.")
        actor = combat_current_actor(self.combat_state)
        effect = next(
            (
                candidate
                for candidate in self.active_combat_effects
                if candidate.id == effect_id
                and candidate.kind.startswith("ongoing_damage_zone:")
            ),
            None,
        )
        if effect is None or effect.source_actor_id != str(actor.id):
            raise ValueError("Nie możesz przesunąć tej strefy czaru.")
        self._clear_player_pending_choices()
        self.pending_spell_zone_move_effect_id = effect.id
        maximum_distance = (
            30
            if effect.object_id == "combat_action:flaming_sphere"
            else 60
        )
        self.board_message = (
            f"{effect.label}: zeskanuj planszę i kliknij nowy środek "
            f"w odległości do {maximum_distance} ft od obecnej strefy."
        )
        self._sync_board_leds()
        return self.state_payload()

    def confirm_moonbeam_move(self, position: Coordinate) -> dict[str, object]:
        if self.combat_state is None or not self.pending_spell_zone_move_effect_id:
            raise ValueError("Nie ma oczekującego przesunięcia Księżycowego promienia.")
        encounter = self._active_encounter()
        if encounter is None:
            raise ValueError("Brak danych encountera dla aktywnej walki.")
        result = move_moonbeam_zone(
            self.combat_state,
            self.active_combat_effects,
            effect_id=self.pending_spell_zone_move_effect_id,
            destination=position,
            board=encounter.board,
        )
        self.combat_state = result.state
        self.active_combat_effects = result.active_effects
        self.pending_spell_zone_move_effect_id = ""
        self.board_message = (
            f"Strefę czaru przesunięto na {position.as_tuple()}."
        )
        self._add_message("Przesunięcie strefy", self.board_message)
        self._sync_board_leds()
        return self.state_payload()

    def _moonbeam_move_positions(self) -> tuple[Coordinate, ...]:
        if not self.pending_spell_zone_move_effect_id:
            return ()
        encounter = self._active_encounter()
        if encounter is None:
            return ()
        effect = next(
            (
                candidate
                for candidate in self.active_combat_effects
                if candidate.id == self.pending_spell_zone_move_effect_id
            ),
            None,
        )
        if effect is None or effect.anchor_position is None:
            return ()
        maximum_distance = (
            30
            if effect.object_id == "combat_action:flaming_sphere"
            else 60
        )
        return tuple(
            Coordinate(col, row)
            for row in range(encounter.board.dimensions.rows)
            for col in range(encounter.board.dimensions.cols)
            if grid_distance_feet(
                effect.anchor_position,
                Coordinate(col, row),
            )
            <= maximum_distance
        )

    def start_spell_debuff(
        self,
        action_id: str,
        *,
        cast_level: int | None = None,
    ) -> dict[str, object]:
        if self.combat_state is None:
            raise ValueError("Walka nie została rozpoczęta.")
        actor = combat_current_actor(self.combat_state)
        if actor.faction != Faction.ALLY:
            raise ValueError("To nie jest tura bohatera.")
        encounter = self._active_encounter()
        if encounter is None:
            raise ValueError("Brak danych encountera dla aktywnej walki.")
        action = _combat_action_by_id(encounter, actor, action_id)
        if action is None or action.action_type != "spell_debuff":
            raise ValueError("Nieznany czar debuffujący.")
        transition = self.spell_debuff_flow.prepare(
            board=encounter.board,
            state=self.combat_state,
            action=action,
            cast_level=cast_level,
            active_effects=self.active_combat_effects,
        )
        self._clear_player_pending_choices()
        return self._apply_spell_debuff_transition(transition)

    def confirm_spell_debuff(
        self,
        *,
        target_id: str,
        condition: str = "",
    ) -> dict[str, object]:
        pending = self.pending_spell_debuff
        if pending is None or self.combat_state is None:
            raise ValueError("Nie ma debuffu do potwierdzenia.")
        actor = combat_current_actor(self.combat_state)
        encounter = self._active_encounter()
        if encounter is None:
            raise ValueError("Brak danych encountera dla aktywnej walki.")
        action = _combat_action_by_id(encounter, actor, pending.action_id)
        if action is None:
            raise ValueError("Nieznany czar debuffujący.")
        transition = self.spell_debuff_flow.confirm(
            board=encounter.board,
            state=self.combat_state,
            action=action,
            pending=pending,
            target_id=target_id,
            rng=self.encounter_rng,
            condition=condition,
            active_effects=self.active_combat_effects,
        )
        return self._apply_spell_debuff_transition(transition)

    def select_spell_debuff_condition(
        self,
        condition: str,
    ) -> dict[str, object]:
        pending = self.pending_spell_debuff
        if pending is None or self.combat_state is None:
            raise ValueError("Nie ma debuffu oczekującego na wariant.")
        actor = combat_current_actor(self.combat_state)
        action = _combat_action_by_id(
            self._active_encounter(),
            actor,
            pending.action_id,
        )
        allowed = {
            candidate.value for candidate in action.condition_options
        } if action is not None else set()
        if condition not in allowed:
            raise ValueError("Wybrany wariant stanu nie jest dostępny.")
        self.pending_spell_debuff = replace(
            pending,
            selected_condition=condition,
        )
        self.board_message = (
            f"Wybrano efekt: {condition_label(CombatCondition(condition))}. "
            "Teraz wskaż cel na planszy."
        )
        return self.state_payload()

    def cancel_spell_debuff(self) -> dict[str, object]:
        pending = self.pending_spell_debuff
        if pending is None or self.combat_state is None:
            raise ValueError("Nie ma debuffu do anulowania.")
        transition = self.spell_debuff_flow.cancel(
            state=self.combat_state,
            pending=pending,
        )
        return self._apply_spell_debuff_transition(transition)

    def _apply_spell_debuff_transition(
        self,
        transition: SpellDebuffTransition,
        *,
        sync_board: bool = True,
    ) -> dict[str, object]:
        self.combat_state = transition.state
        if transition.concentration_effect is not None:
            source_actor_id = transition.concentration_effect.source_actor_id
            expiration = expire_active_effects(
                self.active_combat_effects,
                EffectEvent(
                    EffectEventType.CONCENTRATION_ENDED,
                    actor_id=source_actor_id,
                ),
            )
            self.active_combat_effects = apply_active_effect(
                expiration.active_effects,
                transition.concentration_effect,
            ).active_effects
            self._remove_orphaned_concentration_conditions()
        if transition.scene_flag_changes:
            flags = self.state.flags
            for key, value in transition.scene_flag_changes:
                flags = set_scene_flag(flags, key, value)
            self.state = replace(self.state, flags=flags)
        self.pending_spell_debuff = transition.pending
        self.selected_combat_movement_path = None
        self.board_message = transition.message_body
        self._add_message(transition.message_title, transition.message_body)
        self._record(transition.event_type, dict(transition.event_payload))
        if sync_board:
            self._sync_board_leds()
        return self.state_payload()

