    def _combat_interaction_positions(self, encounter: LoadedEncounter, actor: Actor) -> tuple[Coordinate, ...]:
        if self.combat_state is None:
            return ()
        return self.combat_scene_interaction_flow.positions(
            state=self.combat_state,
            scene_objects=encounter.scene_objects,
            actor=actor,
        )

    def _combat_interaction_hint_positions(
        self,
        encounter: LoadedEncounter,
        actor: Actor,
        movement: MovementRangeResult,
    ) -> tuple[Coordinate, ...]:
        if self.combat_state is None:
            return ()
        return self.combat_scene_interaction_flow.hint_positions(
            state=self.combat_state,
            scene_objects=encounter.scene_objects,
            actor=actor,
            reachable_tiles=movement.reachable_tiles,
        )

    def _scene_object_by_id(self, encounter: LoadedEncounter, object_id: str):
        return scene_object_by_id(encounter.scene_objects, object_id)

    def _expire_invalid_combat_effects(self) -> None:
        if self.combat_state is None or not self.active_combat_effects:
            return
        encounter = self._active_encounter()
        scene_objects = encounter.scene_objects if encounter is not None else ()
        transition = self.combat_scene_interaction_flow.expire_invalid_effects(
            state=self.combat_state,
            scene_objects=scene_objects,
            active_effects=self.active_combat_effects,
        )
        self.combat_state = transition.state
        self.active_combat_effects = transition.active_effects
        if transition.expired_effects:
            labels = ", ".join(effect.label for effect in transition.expired_effects)
            self._add_message("Efekty", f"Wygasły efekty pozycyjne: {labels}.")

    def _expire_warding_bonds(self) -> None:
        if self.combat_state is None:
            return
        actors = {
            str(actor.id): actor
            for actor in self.combat_state.actors
        }
        expired = tuple(
            effect
            for effect in self.active_combat_effects
            if effect.kind == "warding_bond"
            and (
                effect.actor_id not in actors
                or effect.source_actor_id not in actors
                or actors[effect.actor_id].is_defeated()
                or actors[str(effect.source_actor_id)].is_defeated()
                or grid_distance_feet(
                    actors[effect.actor_id].position,
                    actors[str(effect.source_actor_id)].position,
                )
                > 60
            )
        )
        if not expired:
            return
        expired_ids = {effect.id for effect in expired}
        self.active_combat_effects = tuple(
            effect
            for effect in self.active_combat_effects
            if effect.id not in expired_ids
        )
        self._add_message(
            "Więź ochronna",
            "Więź ochronna kończy się: uczestnik upadł albo oddalił się ponad 60 ft.",
        )

    def _apply_spike_growth_movement_damage(
        self,
        actor_id: str,
        path,
    ) -> None:
        if self.combat_state is None:
            return
        from dnd_board_game.combat import (
            spike_growth_damage_dice_count,
            spike_growth_damaging_steps,
        )
        damaging_steps = spike_growth_damaging_steps(
            path.path,
            self.active_combat_effects,
        )
        if damaging_steps <= 0:
            return
        actor = self._actor_by_string_id(actor_id)
        amount = sum(
            self.encounter_rng.randint(1, 4)
            for _ in range(
                spike_growth_damage_dice_count(
                    path.path,
                    self.active_combat_effects,
                )
            )
        )
        applied = apply_damage_result(
            actor,
            resolve_damage(
                (
                    DamageComponentInput(
                        amount,
                        "piercing",
                        "Kolczaste zarośla",
                    ),
                )
            ),
        )
        self.combat_state = replace_actor(
            self.combat_state,
            applied.actor_after,
        )
        self._add_message(
            "Kolczaste zarośla",
            (
                f"{actor.name} przechodzi {damaging_steps * 5} ft przez kolce "
                f"i otrzymuje {applied.damage.total_applied} obrażeń kłutych."
            ),
        )

    def _apply_moonbeam_entry_damage(self, actor_id: str, path) -> None:
        if self.combat_state is None or len(path.path) < 2:
            return
        zones = tuple(
            effect
            for effect in self.active_combat_effects
            if effect.kind.startswith("ongoing_damage_zone:")
            and effect.anchor_position is not None
        )
        actor = self._actor_by_string_id(actor_id)
        for zone in zones:
            marker_kind = f"moonbeam_triggered:{zone.id}"
            if any(
                effect.actor_id == actor_id and effect.kind == marker_kind
                for effect in self.active_combat_effects
            ):
                continue
            started_inside = (
                grid_distance_feet(path.path[0], zone.anchor_position)
                <= zone.value
            )
            entered = any(
                grid_distance_feet(position, zone.anchor_position) <= zone.value
                for position in path.path[1:]
            )
            if started_inside or not entered:
                continue
            _, count_raw, sides_raw, damage_type, save_ability, save_mode = (
                zone.kind.split(":", 5)
            )
            amount = sum(
                self.encounter_rng.randint(1, int(sides_raw))
                for _ in range(int(count_raw))
            )
            caster = next(
                (
                    candidate
                    for candidate in self.combat_state.actors
                    if str(candidate.id) == zone.source_actor_id
                ),
                None,
            )
            save = resolve_spell_save(
                actor,
                ability=save_ability,
                dc=(caster.spell_save_dc if caster is not None else 10),
                natural_roll=self.encounter_rng.randint(1, 20),
                condition_states=self.combat_state.condition_states,
                combat_actors=self.combat_state.actors,
            )
            if save.success:
                amount = amount // 2 if save_mode == "half" else 0
            applied = apply_damage_result(
                actor,
                resolve_damage(
                    (DamageComponentInput(amount, damage_type, zone.label),)
                ),
            )
            self.combat_state = replace_actor(
                self.combat_state,
                applied.actor_after,
            )
            marker = ActiveCombatEffect(
                id=f"{marker_kind}:{actor_id}",
                actor_id=actor_id,
                kind=marker_kind,
                label=f"{zone.label} — rozstrzygnięto wejście",
                object_id=zone.object_id,
                value=0,
                duration=EffectDuration.UNTIL_TURN_START,
                expiration_actor_id=actor_id,
            )
            self.active_combat_effects = apply_active_effect(
                self.active_combat_effects,
                marker,
            ).active_effects
            self._add_message(
                zone.label,
                (
                    f"{actor.name} po raz pierwszy w tej turze wchodzi w obszar "
                    f"i otrzymuje {applied.damage.total_applied} obrażeń {damage_type}."
                ),
            )
            actor = applied.actor_after

    def _apply_web_entry_save(self, actor_id: str, path) -> None:
        if self.combat_state is None or len(path.path) < 2:
            return
        from dnd_board_game.combat import (
            resolve_web_save,
            web_zone_contains,
            web_zones,
        )

        for zone in web_zones(self.active_combat_effects):
            if web_zone_contains(zone, path.path[0]):
                continue
            if not any(web_zone_contains(zone, position) for position in path.path[1:]):
                continue
            resolution = resolve_web_save(
                self.combat_state,
                actor_id=actor_id,
                zone=zone,
                rng=self.encounter_rng,
            )
            self.combat_state = resolution.state
            if resolution.saving_throw is None:
                continue
            outcome = (
                "zostaje Unieruchomiony"
                if resolution.restrained
                else "unika lepkich nici"
            )
            self._add_message(
                "Sieć",
                (
                    f"{resolution.saving_throw.actor_name}: Dex "
                    f"{resolution.saving_throw.total} przeciw ST "
                    f"{resolution.saving_throw.dc} — {outcome}."
                ),
            )
            break

    def _apply_zone_of_truth_entry_save(self, actor_id: str, path) -> None:
        if self.combat_state is None or len(path.path) < 2:
            return
        from dnd_board_game.combat import (
            resolve_zone_of_truth_save,
            zone_of_truth_contains,
            zone_of_truth_zones,
        )

        for zone in zone_of_truth_zones(self.active_combat_effects):
            if zone_of_truth_contains(zone, path.path[0]):
                continue
            if not zone_of_truth_contains(zone, path.path[-1]):
                continue
            resolution = resolve_zone_of_truth_save(
                self.combat_state,
                self.active_combat_effects,
                actor_id=actor_id,
                zone=zone,
                rng=self.encounter_rng,
            )
            self.active_combat_effects = resolution.active_effects
            if resolution.saving_throw is not None:
                self._add_zone_of_truth_save_message(resolution.saving_throw, resolution.bound)
            break

    def _add_zone_of_truth_save_message(self, saving_throw, bound: bool) -> None:
        self._add_message(
            "Strefa prawdy — wynik znany rzucającemu",
            (
                f"{saving_throw.actor_name}: Charisma {saving_throw.total} "
                f"przeciw ST {saving_throw.dc} — "
                + (
                    "porażka; nie może świadomie kłamać."
                    if bound
                    else "sukces; efekt jeszcze go nie wiąże."
                )
            ),
        )

    def _expire_turn_start_effects(self) -> None:
        if self.combat_state is None or not self.active_combat_effects or self.combat_state.status.value != "active":
            return
        actor = combat_current_actor(self.combat_state)
        from dnd_board_game.combat import (
            resolve_web_save,
            web_zone_contains,
            web_zones,
        )

        for zone in web_zones(self.active_combat_effects):
            if not web_zone_contains(zone, actor.position):
                continue
            web = resolve_web_save(
                self.combat_state,
                actor_id=str(actor.id),
                zone=zone,
                rng=self.encounter_rng,
            )
            self.combat_state = web.state
            if web.saving_throw is not None:
                outcome = (
                    "zostaje Unieruchomiony"
                    if web.restrained
                    else "opiera się sieci"
                )
                self._add_message(
                    "Sieć",
                    (
                        f"{actor.name}: Dex {web.saving_throw.total} przeciw "
                        f"ST {web.saving_throw.dc} — {outcome}."
                    ),
                )
            break
        from dnd_board_game.combat import (
            resolve_zone_of_truth_save,
            zone_of_truth_contains,
            zone_of_truth_zones,
        )

        for zone in zone_of_truth_zones(self.active_combat_effects):
            if not zone_of_truth_contains(zone, actor.position):
                continue
            truth = resolve_zone_of_truth_save(
                self.combat_state,
                self.active_combat_effects,
                actor_id=str(actor.id),
                zone=zone,
                rng=self.encounter_rng,
            )
            self.active_combat_effects = truth.active_effects
            if truth.saving_throw is not None:
                self._add_zone_of_truth_save_message(
                    truth.saving_throw,
                    truth.bound,
                )
            break
        for effect in tuple(self.active_combat_effects):
            targeted = (
                effect.actor_id == str(actor.id)
                and effect.kind.startswith("ongoing_damage:")
            )
            zoned = (
                effect.kind.startswith("ongoing_damage_zone:")
                and effect.anchor_position is not None
                and grid_distance_feet(actor.position, effect.anchor_position)
                <= effect.value
            )
            if not targeted and not zoned:
                continue
            _, count_raw, sides_raw, damage_type, save_ability, save_mode = (
                effect.kind.split(":", 5)
            )
            rolled_damage = sum(
                self.encounter_rng.randint(1, int(sides_raw))
                for _ in range(int(count_raw))
            )
            save_payload = None
            if save_ability != "-":
                caster = next(
                    (
                        candidate
                        for candidate in self.combat_state.actors
                        if str(candidate.id) == effect.source_actor_id
                    ),
                    None,
                )
                save = resolve_spell_save(
                    actor,
                    ability=save_ability,
                    dc=(caster.spell_save_dc if caster is not None else 10),
                    natural_roll=self.encounter_rng.randint(1, 20),
                    condition_states=self.combat_state.condition_states,
                    combat_actors=self.combat_state.actors,
                )
                save_payload = save.as_payload()
                if save.success:
                    rolled_damage = (
                        rolled_damage // 2 if save_mode == "half" else 0
                    )
            applied = apply_damage_result(
                actor,
                resolve_damage(
                    (
                        DamageComponentInput(
                            rolled_damage,
                            damage_type,
                            effect.label,
                        ),
                    )
                ),
            )
            self.combat_state = replace_actor(
                self.combat_state,
                applied.actor_after,
            )
            actor = combat_current_actor(self.combat_state)
            self._add_message(
                "Efekt okresowy",
                (
                    f"{effect.label}: {actor.name} otrzymuje "
                    f"{applied.damage.total_applied} obrażeń {damage_type}."
                ),
            )
            self._record(
                "ui_combat_ongoing_spell_damage",
                {
                    "effect_id": effect.id,
                    "actor_id": str(actor.id),
                    "damage": applied.damage.total_applied,
                    "damage_type": damage_type,
                    "save": save_payload,
                },
            )
        heroism = next(
            (
                effect
                for effect in self.active_combat_effects
                if effect.actor_id == str(actor.id)
                and effect.kind == "heroism_temp_hp"
            ),
            None,
        )
        if heroism is not None:
            self.combat_state = replace_actor(
                self.combat_state,
                replace(actor, temp_hp=max(actor.temp_hp, heroism.value)),
            )
            actor = combat_current_actor(self.combat_state)
        before = self.active_combat_effects
        self.active_combat_effects = expire_turn_start_effects(self.active_combat_effects, str(actor.id))
        if before != self.active_combat_effects:
            self._add_expired_effects_message(f"Wygasły efekty początku tury: {actor.name}", before, self.active_combat_effects)

    def _expire_turn_end_effects(self, actor: Actor) -> None:
        if not self.active_combat_effects:
            return
        rage = next(
            (
                effect
                for effect in self.active_combat_effects
                if effect.actor_id == str(actor.id) and effect.kind == "rage"
            ),
            None,
        )
        if rage is not None:
            active_this_cycle = any(
                effect.actor_id == str(actor.id)
                and effect.kind == "rage_activity"
                for effect in self.active_combat_effects
            )
            duration = next(
                (
                    effect
                    for effect in self.active_combat_effects
                    if effect.actor_id == str(actor.id)
                    and effect.kind == "rage_duration"
                ),
                None,
            )
            ten_rounds_elapsed = (
                duration is not None
                and self.combat_state is not None
                and self.combat_state.round_number - duration.value >= 9
            )
            if actor.is_defeated() or not active_this_cycle or ten_rounds_elapsed:
                reason = (
                    "utrata przytomności"
                    if actor.is_defeated()
                    else "upłynęła 1 minuta"
                    if ten_rounds_elapsed
                    else "brak ataku na wroga i brak otrzymanych obrażeń"
                )
                self._end_rage(str(actor.id), reason=reason)
        before = self.active_combat_effects
        self.active_combat_effects = expire_turn_end_effects(self.active_combat_effects, str(actor.id))
        if before != self.active_combat_effects:
            self._add_expired_effects_message(f"Wygasły efekty końca tury: {actor.name}", before, self.active_combat_effects)

    def _mark_rage_activity(self, actor_id: str, *, label: str) -> None:
        if not any(
            effect.actor_id == actor_id and effect.kind == "rage"
            for effect in self.active_combat_effects
        ):
            return
        self.active_combat_effects = (
            *tuple(
                effect
                for effect in self.active_combat_effects
                if not (
                    effect.actor_id == actor_id
                    and effect.kind == "rage_activity"
                )
            ),
            ActiveCombatEffect(
                id=f"rage-activity:{actor_id}",
                actor_id=actor_id,
                kind="rage_activity",
                label=label,
                object_id="class_feature:rage",
                value=1,
                source_actor_id=actor_id,
                duration=EffectDuration.UNTIL_TURN_END,
                expiration_actor_id=actor_id,
            ),
        )

    def _end_rage(self, actor_id: str, *, reason: str) -> None:
        frenzied = any(
            effect.actor_id == actor_id and effect.kind == "frenzy"
            for effect in self.active_combat_effects
        )
        before = self.active_combat_effects
        self.active_combat_effects = tuple(
            effect
            for effect in self.active_combat_effects
            if not (
                effect.actor_id == actor_id
                and effect.kind
                in {"rage", "rage_duration", "rage_activity", "frenzy", "frenzy_pending"}
            )
        )
        if frenzied and self.combat_state is not None:
            actor = next(
                (
                    candidate
                    for candidate in self.combat_state.actors
                    if str(candidate.id) == actor_id
                ),
                None,
            )
            if actor is not None:
                self.combat_state = replace_actor(
                    self.combat_state,
                    increase_exhaustion(actor),
                )
        if before != self.active_combat_effects:
            actor_name = next(
                (
                    actor.name
                    for actor in (
                        self.combat_state.actors
                        if self.combat_state is not None
                        else self.exploration.actors
                    )
                    if str(actor.id) == actor_id
                ),
                actor_id,
            )
            suffix = " Otrzymuje 1 poziom Wyczerpania za Frenzy." if frenzied else ""
            self._add_message(
                "Rage zakończony",
                f"{actor_name}: {reason}.{suffix}",
            )

    def _add_expired_effects_message(
        self,
        prefix: str,
        before: tuple[ActiveCombatEffect, ...],
        after: tuple[ActiveCombatEffect, ...],
    ) -> None:
        after_ids = {effect.id for effect in after}
        expired = [effect for effect in before if effect.id not in after_ids]
        labels = ", ".join(effect.label for effect in expired) or "efekt"
        self._add_message("Efekty", f"{prefix}: {labels}.")

    def _add_expired_effect_notices(
        self,
        notices: tuple[ExpiredCombatEffects, ...],
    ) -> None:
        for notice in notices:
            labels = ", ".join(effect.label for effect in notice.effects) or "efekt"
            self._add_message("Efekty", f"{notice.message_prefix}: {labels}.")

    def _add_expired_magic_effect_notices(
        self,
        effects: tuple[TimedMagicEffect, ...],
    ) -> None:
        for effect in effects:
            self._add_message(
                "Efekt magiczny wygasł",
                f"Kończy się działanie efektu {effect.label}.",
            )

    def _add_expired_condition_notices(
        self,
        conditions: tuple[ConditionState, ...],
        *,
        prefix: str,
    ) -> None:
        actor_names = {
            str(actor.id): actor.name
            for actor in (
                self.combat_state.actors
                if self.combat_state is not None
                else self.exploration.actors
            )
        }
        for condition in conditions:
            actor_name = actor_names.get(condition.actor_id, condition.actor_id)
            self._add_message(
                "Stan wygasł",
                f"{prefix}: {actor_name} — {condition_label(condition.condition)}.",
            )

    def _add_clock_event_notices(self, events) -> None:
        for event in events:
            self._add_message(event.label, event.narration)
            self._record(
                "ui_scenario_clock_event_triggered",
                {
                    "event_id": event.id,
                    "at_minute": event.at_minute,
                    "elapsed_minutes": self.state.elapsed_minutes,
                    "effect_types": [
                        str(effect.get("type", ""))
                        for effect in event.effects
                    ],
                },
            )

    def _new_clock_events_between(
        self,
        before: ExplorationState,
        after: ExplorationState,
    ):
        return tuple(
            event
            for event in after.clock_policy.events
            if not bool(scene_flag(before.flags, event.marker_flag, False))
            and bool(scene_flag(after.flags, event.marker_flag, False))
        )

    def _advance_scenario_time(
        self,
        minutes: int,
        *,
        source: str,
    ):
        result = advance_exploration_time(self.state, minutes)
        self.state = result.state
        if minutes:
            self.state = clear_exploration_hidden(self.state)
        self._advance_party_lights(minutes)
        self._add_expired_magic_effect_notices(result.expired_effects)
        self._add_clock_event_notices(result.triggered_clock_events)
        if minutes:
            self._record(
                "ui_scenario_time_advanced",
                {
                    "source": source,
                    "minutes": minutes,
                    "elapsed_minutes": self.state.elapsed_minutes,
                },
            )
        return result

    def _add_trigger_activation_notices(self, activations) -> None:
        for activation in activations:
            actor = next(
                (
                    candidate
                    for candidate in (
                        self.combat_state.actors
                        if self.combat_state is not None
                        else self.exploration.actors
                    )
                    if str(candidate.id) == activation.owner_actor_id
                ),
                None,
            )
            actor_name = actor.name if actor is not None else activation.owner_actor_id
            body = (
                f"{actor_name}: {activation.trigger.label} — temporary HP "
                f"{activation.previous_temp_hp} → {activation.current_temp_hp}."
            )
            self._add_message("Aktywowano cechę", body)
            self._record(
                "ui_actor_trigger_activated",
                {
                    "actor_id": activation.owner_actor_id,
                    "trigger_id": activation.trigger.id,
                    "event_type": activation.trigger.event_type.value,
                    "effect_kind": activation.trigger.effect_kind.value,
                    "changed": activation.changed,
                    "previous_temp_hp": activation.previous_temp_hp,
                    "current_temp_hp": activation.current_temp_hp,
                },
            )

    def _apply_combat_trigger_events(self, events: tuple[EffectEvent, ...]) -> None:
        if self.combat_state is None or not events:
            return
        resolution = resolve_combat_trigger_events(self.combat_state, events)
        condition_states = resolution.state.condition_states
        for event in events:
            condition_states, _expired = expire_condition_states(
                condition_states,
                event,
            )
        self.combat_state = replace(
            resolution.state,
            condition_states=condition_states,
        )
        self._add_trigger_activation_notices(resolution.activations)

    def _add_recharge_notices(self, results) -> None:
        for result in results:
            pool = actor_resource_pool(result.actor_after, result.resource_id)
            if pool is None or pool.recharge is None:
                continue
            outcome = "odnowiona" if result.recharged else "nadal niedostępna"
            self._add_message(
                "Recharge",
                (
                    f"{result.actor_after.name}: {pool.label} — d{pool.recharge.die_sides} "
                    f"{result.natural_roll}, wymaga {pool.recharge.minimum_roll}+; {outcome}."
                ),
            )
            self._record(
                "ui_actor_resource_recharge_rolled",
                {
                    "actor_id": str(result.actor_after.id),
                    "resource_id": result.resource_id,
                    "natural_roll": result.natural_roll,
                    "minimum_roll": pool.recharge.minimum_roll,
                    "recharged": result.recharged,
                    "current": pool.current,
                    "maximum": pool.maximum,
                },
            )

    def resolve_enemy_turn(self) -> dict[str, object]:
        if self.combat_state is None:
            raise ValueError("Walka nie została rozpoczęta.")
        encounter = self._active_encounter()
        if encounter is None:
            raise ValueError("Brak danych encountera dla aktywnej walki.")
        if self.pending_enemy_turn_intent is None:
            transition = self.enemy_turn_flow.plan(
                state=self.combat_state,
                board=encounter.board,
                attack_sources_by_actor=encounter.attack_sources_by_actor,
                multiattack_sources_by_actor=encounter.multiattack_sources_by_actor,
                scene_objects=encounter.scene_objects,
                ai_profile=encounter.enemy_ai_profile,
                ai_roles=dict(encounter.enemy_ai_roles),
                ai_zone_positions=_enemy_ai_zone_map(encounter),
            )
            self.pending_enemy_turn_intent = transition.intent
            self.board_message = transition.board_message
            self._add_message(transition.message_title, transition.message_body)
            self._record(transition.event_type, dict(transition.event_payload))
            self._sync_board_leds()
            return self.state_payload()
        intent = self.pending_enemy_turn_intent
        self.pending_enemy_turn_intent = None
        transition = self.enemy_turn_flow.resolve(
            state=self.combat_state,
            intent=intent,
            board=encounter.board,
            attack_sources_by_actor=encounter.attack_sources_by_actor,
            multiattack_sources_by_actor=encounter.multiattack_sources_by_actor,
            active_effects=self.active_combat_effects,
            rng=self.encounter_rng,
            scene_objects=encounter.scene_objects,
        )
        result = transition.result
        if transition.kind == EnemyTurnTransitionKind.FINISHED:
            return self._finish_pending_enemy_turn(result)
        self.pending_enemy_turn_result = result
        self.pending_state.counterspell_reaction_resolved = None
        self.pending_state.cutting_words_reaction_resolved = None
        self.pending_state.cutting_words_reaction_stage = ""
        self.pending_state.defensive_spell_reaction_resolved = None
        self.pending_state.retaliation_spell_reaction_resolved = None
        self.pending_state.deflect_missiles_reaction_resolved = None
        self.board_message = transition.board_message
        if transition.kind == EnemyTurnTransitionKind.REACTION:
            assert transition.reaction_window is not None
            self.pending_reaction_window = transition.reaction_window
            self._activate_current_reaction_option()
        if transition.message_title:
            self._add_message(transition.message_title, transition.message_body)
        if transition.event_type:
            self._record(transition.event_type, dict(transition.event_payload))
        self._sync_board_leds()
        return self.state_payload()

    def _commit_pending_enemy_turn(self, result=None) -> dict[str, object]:
        if self.combat_state is None:
            raise ValueError("Walka nie została rozpoczęta.")
        result = result or self.pending_enemy_turn_result
        if result is None:
            raise ValueError("Brak oczekującej tury przeciwnika do potwierdzenia.")
        if (
            self.pending_reaction_window is not None
            and self.pending_reaction_window.current_option.kind
            in (
                ReactionKind.SPELL_COUNTER,
                ReactionKind.CUTTING_WORDS,
                ReactionKind.DEFENSIVE_SPELL,
                ReactionKind.DEFLECT_MISSILES,
                ReactionKind.RETALIATION_SPELL,
            )
        ):
            raise ValueError("Najpierw rozstrzygnij albo pomiń oczekującą reakcję.")
        if (
            result is self.pending_enemy_turn_result
            and self._maybe_open_counterspell_reaction()
        ):
            return self.state_payload()
        if (
            result is self.pending_enemy_turn_result
            and self._maybe_open_cutting_words_reaction()
        ):
            return self.state_payload()
        if (
            result is self.pending_enemy_turn_result
            and self._maybe_open_defensive_spell_reaction()
        ):
            return self.state_payload()
        if (
            result is self.pending_enemy_turn_result
            and self._maybe_open_deflect_missiles_reaction()
        ):
            return self.state_payload()
        if (
            result is self.pending_enemy_turn_result
            and self._maybe_open_retaliation_spell_reaction()
        ):
            return self.state_payload()
        if result.source is not None and result.target is not None:
            self._animate_ranged_projectile(
                result.moved_enemy or result.enemy,
                result.target,
                result.source,
            )
        transition = self.combat_turn_finalization.commit_enemy_result(
            result=result,
            active_effects=self.active_combat_effects,
        )
        self.combat_state = transition.state
        self.active_combat_effects = transition.active_effects
        self.selected_combat_movement_path = None
        self.pending_enemy_turn_intent = None
        self.pending_enemy_turn_result = None
        self.pending_reaction_window = None
        self.pending_state.counterspell_reaction_resolved = None
        self.pending_state.cutting_words_reaction_resolved = None
        self.pending_state.cutting_words_reaction_stage = ""
        self.pending_state.defensive_spell_reaction_resolved = None
        self.pending_state.retaliation_spell_reaction_resolved = None
        self.pending_state.deflect_missiles_reaction_resolved = None
        self.pending_enemy_opportunity_attack = None
        self.pending_ready_attack = None
        self.pending_approach_interaction = None
        self.pending_approach_pickup = None
        self.pending_enemy_turn_ack_result = transition.result
        if transition.result.saving_throw_request is not None and transition.result.target is not None:
            request = transition.result.saving_throw_request
            self.pending_enemy_saving_throw = PendingEnemySavingThrow(
                target_id=transition.result.target.id,
                source_id=transition.result.source.id if transition.result.source is not None else "",
                request=request,
            )
            self.board_message = (
                f"{transition.result.target.name}: rzuć fizyczne d20 na "
                f"{request.as_payload()['ability_label']} przeciw ST {request.dc} i wpisz wynik."
            )
            self._add_message("Rzut obronny", self.board_message)
        else:
            self.pending_enemy_saving_throw = None
            self.board_message = transition.board_message
        self._record(transition.event_type, dict(transition.event_payload))
        trigger_events = []
        if result.movement_path is not None and result.moved_enemy is not None:
            trigger_events.append(
                EffectEvent(
                    EffectEventType.ACTOR_MOVED,
                    actor_id=str(result.enemy.id),
                    position=result.moved_enemy.position,
                )
            )
        if result.applied_damage is not None:
            target_id = str(result.applied_damage.actor_after.id)
            if result.applied_damage.damage.total_applied > 0:
                self._mark_rage_activity(
                    target_id,
                    label="Rage podtrzymany otrzymanymi obrażeniami",
                )
            if result.applied_damage.actor_after.is_defeated():
                self._end_rage(target_id, reason="utrata przytomności")
            if result.attack_resolution is not None and result.attack_resolution.hit:
                trigger_events.append(
                    EffectEvent(
                        EffectEventType.ATTACK_HIT,
                        actor_id=str(result.enemy.id),
                        target_actor_id=target_id,
                    )
                )
            if result.applied_damage.damage.total_applied > 0:
                trigger_events.append(
                    EffectEvent(
                        EffectEventType.DAMAGE_TAKEN,
                        actor_id=target_id,
                        target_actor_id=str(result.enemy.id),
                    )
                )
        self._apply_combat_trigger_events(tuple(trigger_events))
        self.pending_enemy_turn_ack_result = replace(
            transition.result,
            state=self.combat_state,
        )
        if result.applied_damage is not None:
            self._maybe_prompt_concentration_check(result.applied_damage)
        self._sync_board_leds()
        return self.state_payload()

    def _activate_current_reaction_option(self) -> None:
        window = self.pending_reaction_window
        self.pending_enemy_opportunity_attack = None
        self.pending_ready_attack = None
        if window is None:
            return
        option = window.current_option
        if option.kind == ReactionKind.READY_ATTACK:
            if option.effect_id is None:
                raise ValueError("Ready reaction requires an effect id.")
            self.pending_ready_attack = PendingReadyAttack(
                readied_actor_id=option.reactor_actor_id,
                target_id=option.target_actor_id,
                effect_id=option.effect_id,
                trigger=option.trigger_event,
                stage=window.stage.value,
                natural_roll=window.natural_roll,
                natural_rolls=window.natural_rolls,
                total=window.total,
                hit=window.hit,
                critical=window.critical,
            )
        elif option.kind == ReactionKind.OPPORTUNITY_ATTACK:
            self.pending_enemy_opportunity_attack = PendingEnemyOpportunityAttack(
                target_id=option.target_actor_id,
                threat_actor_ids=(option.reactor_actor_id,),
                stage=window.stage.value,
                natural_roll=window.natural_roll,
                natural_rolls=window.natural_rolls,
                total=window.total,
                hit=window.hit,
                critical=window.critical,
            )

    def _maybe_open_cutting_words_reaction(self) -> bool:
        if (
            self.combat_state is None
            or self.pending_enemy_turn_result is None
            or self.pending_reaction_window is not None
            or self.pending_state.cutting_words_reaction_resolved is True
        ):
            return False
        encounter = self._active_encounter()
        if encounter is None:
            return False
        damage_stage = self.pending_state.cutting_words_reaction_stage == "damage"
        options = (
            self.class_feature_reaction_flow.cutting_words_damage_options(
                board=encounter.board,
                state=self.combat_state,
                enemy_result=self.pending_enemy_turn_result,
            )
            if damage_stage
            else self.class_feature_reaction_flow.cutting_words_options(
                board=encounter.board,
                state=self.combat_state,
                enemy_result=self.pending_enemy_turn_result,
            )
        )
        if not options:
            if not damage_stage:
                self.pending_state.cutting_words_reaction_stage = "damage"
                return self._maybe_open_cutting_words_reaction()
            self.pending_state.cutting_words_reaction_resolved = True
            return False
        self.pending_reaction_window = open_reaction_window(
            interrupted_actor_id=str(self.pending_enemy_turn_result.enemy.id),
            trigger_event=options[0].trigger_event,
            options=options,
        )
        option = options[0]
        bard = self._actor_by_string_id(option.reactor_actor_id)
        shown_total = (
            self.pending_enemy_turn_result.damage.total_before_reduction
            if damage_stage and self.pending_enemy_turn_result.damage is not None
            else self.pending_enemy_turn_result.attack_roll.total
        )
        shown_label = "obrażeniom" if damage_stage else "wynikowi ataku"
        self.board_message = (
            f"{bard.name} może użyć Cutting Words przeciw {shown_label} "
            f"{shown_total}. Rzuć k{option.value} albo pomiń reakcję."
        )
        self._add_message("Cutting Words", self.board_message)
        self._record(
            "ui_combat_cutting_words_offered",
            {
                "actor_id": option.reactor_actor_id,
                "attacker_id": option.target_actor_id,
                "die_sides": option.value,
                "resolution_stage": (
                    "damage_roll_revealed" if damage_stage else "attack_roll_revealed"
                ),
                "shown_total": shown_total,
            },
        )
        self._sync_board_leds()
        return True

    def resolve_cutting_words_reaction(self, *, die_roll: int) -> dict[str, object]:
        if self.combat_state is None or self.pending_enemy_turn_result is None:
            raise ValueError("Brak oczekującego wrogiego ataku.")
        window = self.pending_reaction_window
        if window is None or window.current_option.kind != ReactionKind.CUTTING_WORDS:
            raise ValueError("Brak oczekującej reakcji Cutting Words.")
        option = window.current_option
        resolution = self.class_feature_reaction_flow.apply_cutting_words(
            state=self.combat_state,
            enemy_result=self.pending_enemy_turn_result,
            option=option,
            die_roll=int(die_roll),
        )
        self.combat_state = resolution.state
        self.pending_enemy_turn_result = resolution.result
        self.pending_state.cutting_words_reaction_resolved = True
        self.pending_reaction_window = None
        self._add_message("Cutting Words", resolution.message)
        self._record(
            "ui_combat_cutting_words_resolved",
            {
                "actor_id": option.reactor_actor_id,
                "attacker_id": option.target_actor_id,
                "die_roll": resolution.die_roll,
                "previous_attack_total": resolution.previous_attack_total,
                "attack_total": resolution.attack_total,
                "prevented_hit": resolution.prevented_hit,
                "resolution_stage": resolution.resolution_stage,
                "previous_damage_total": resolution.previous_damage_total,
                "damage_total": resolution.damage_total,
            },
        )
        return self._commit_pending_enemy_turn(resolution.result)

    def skip_cutting_words_reaction(self) -> dict[str, object]:
        window = self.pending_reaction_window
        if window is None or window.current_option.kind != ReactionKind.CUTTING_WORDS:
            raise ValueError("Brak oczekującej reakcji Cutting Words.")
        skipped_actor_id = window.current_option.reactor_actor_id
        next_window = advance_reaction_window(
            window,
            available_reactor_ids={
                str(actor.id)
                for actor in self.combat_state.actors
                if reaction_available_for(self.combat_state, actor)
            }
            if self.combat_state is not None
            else (),
        )
        self._record(
            "ui_combat_cutting_words_skipped",
            {"actor_id": skipped_actor_id},
        )
        if next_window is not None:
            self.pending_reaction_window = next_window
            option = next_window.current_option
            bard = self._actor_by_string_id(option.reactor_actor_id)
            self.board_message = (
                f"{bard.name} także może użyć Cutting Words. "
                f"Rzuć k{option.value} albo pomiń reakcję."
            )
            return self.state_payload()
        self.pending_reaction_window = None
        if self.pending_state.cutting_words_reaction_stage != "damage":
            self.pending_state.cutting_words_reaction_stage = "damage"
            return self._commit_pending_enemy_turn()
        self.pending_state.cutting_words_reaction_resolved = True
        return self._commit_pending_enemy_turn()

    def _maybe_open_deflect_missiles_reaction(self) -> bool:
        if (
            self.combat_state is None
            or self.pending_enemy_turn_result is None
            or self.pending_reaction_window is not None
            or self.pending_state.deflect_missiles_reaction_resolved is True
        ):
            return False
        option = self.class_feature_reaction_flow.deflect_missiles_option(
            state=self.combat_state,
            enemy_result=self.pending_enemy_turn_result,
        )
        if option is None:
            self.pending_state.deflect_missiles_reaction_resolved = True
            return False
        self.pending_reaction_window = open_reaction_window(
            interrupted_actor_id=str(self.pending_enemy_turn_result.enemy.id),
            trigger_event=option.trigger_event,
            options=(option,),
        )
        monk = self._actor_by_string_id(option.reactor_actor_id)
        self.board_message = (
            f"{monk.name} został trafiony pociskiem. Rzuć k10 dla "
            "Deflect Missiles albo pomiń reakcję."
        )
        self._add_message("Deflect Missiles", self.board_message)
        self._record(
            "ui_combat_deflect_missiles_offered",
            {
                "actor_id": option.reactor_actor_id,
                "attacker_id": option.target_actor_id,
                "incoming_damage": option.value,
            },
        )
        self._sync_board_leds()
        return True

    def resolve_deflect_missiles_reaction(
        self,
        *,
        die_roll: int,
    ) -> dict[str, object]:
        if self.combat_state is None or self.pending_enemy_turn_result is None:
            raise ValueError("Brak oczekującego trafienia pociskiem.")
        window = self.pending_reaction_window
        if window is None or window.current_option.kind != ReactionKind.DEFLECT_MISSILES:
            raise ValueError("Brak oczekującej reakcji Deflect Missiles.")
        option = window.current_option
        resolution = self.class_feature_reaction_flow.apply_deflect_missiles(
            state=self.combat_state,
            enemy_result=self.pending_enemy_turn_result,
            option=option,
            die_roll=int(die_roll),
        )
        self.pending_physical_feature_action_id = None
        self.combat_state = resolution.state
        self.pending_enemy_turn_result = resolution.result
        self.pending_state.deflect_missiles_reaction_resolved = True
        self._add_message("Deflect Missiles", resolution.message)
        self._record(
            "ui_combat_deflect_missiles_resolved",
            {
                "actor_id": option.reactor_actor_id,
                "attacker_id": option.target_actor_id,
                "die_roll": resolution.die_roll,
                "reduction": resolution.reduction,
                "damage_before": resolution.damage_before,
                "damage_after": resolution.damage_after,
                "caught": resolution.caught,
                "can_return_projectile": resolution.can_return_projectile,
            },
        )
        if resolution.can_return_projectile:
            self.pending_reaction_window = replace(
                window,
                stage=ReactionStage.ATTACK_ROLL,
            )
            self.board_message = (
                "Pocisk został złapany. Możesz wydać 1 Ki, aby odrzucić go "
                "w ramach tej samej reakcji, albo zakończyć reakcję."
            )
            self._add_message(
                "Deflect Missiles",
                self.board_message,
            )
            return self.state_payload()
        self.pending_reaction_window = None
        return self._commit_pending_enemy_turn(resolution.result)

    def skip_deflect_missiles_reaction(self) -> dict[str, object]:
        window = self.pending_reaction_window
        if window is None or window.current_option.kind != ReactionKind.DEFLECT_MISSILES:
            raise ValueError("Brak oczekującej reakcji Deflect Missiles.")
        self.pending_state.deflect_missiles_reaction_resolved = True
        self.pending_reaction_window = None
        self.pending_physical_feature_action_id = None
        self._record(
            "ui_combat_deflect_missiles_skipped",
            {"actor_id": window.current_option.reactor_actor_id},
        )
        return self._commit_pending_enemy_turn()

    def return_deflected_missile(
        self,
        *,
        natural_roll: int,
        natural_roll_2: int | None = None,
    ) -> dict[str, object]:
        if self.combat_state is None or self.pending_enemy_turn_result is None:
            raise ValueError("Brak złapanego pocisku do odrzucenia.")
        window = self.pending_reaction_window
        if (
            window is None
            or window.current_option.kind != ReactionKind.DEFLECT_MISSILES
            or window.stage != ReactionStage.ATTACK_ROLL
        ):
            raise ValueError("Deflect Missiles nie oczekuje rzutu odrzucanym pociskiem.")
        encounter = self._active_encounter()
        if encounter is None:
            raise ValueError("Brak danych encountera dla aktywnej walki.")
        damage = self.pending_enemy_turn_result.damage
        if damage is None or not damage.components:
            raise ValueError("Nie można ustalić typu obrażeń złapanego pocisku.")
        option = window.current_option
        returned = self.class_feature_reaction_flow.return_deflected_missile(
            board=encounter.board,
            state=self.combat_state,
            actor_id=option.reactor_actor_id,
            target_id=option.target_actor_id,
            damage_type=damage.components[0].damage_type,
            natural_roll=int(natural_roll),
            natural_roll_2=natural_roll_2,
        )
        self.combat_state = returned.state
        merged_state = replace(
            self.pending_enemy_turn_result.state,
            spent_reaction_actor_ids=returned.state.spent_reaction_actor_ids,
        )
        monk_after = self._actor_by_string_id(option.reactor_actor_id)
        merged_state = replace_actor(merged_state, monk_after)
        self.pending_enemy_turn_result = replace(
            self.pending_enemy_turn_result,
            state=merged_state,
        )
        self._add_message("Odrzucony pocisk", returned.message)
        self._record(
            "ui_combat_deflected_missile_attack",
            {
                "actor_id": option.reactor_actor_id,
                "target_id": option.target_actor_id,
                "natural_roll": returned.attack_roll.natural_roll,
                "natural_rolls": list(returned.attack_roll.natural_rolls),
                "total": returned.attack_roll.total,
                "hit": returned.hit,
                "critical": returned.critical,
            },
        )
        if not returned.hit:
            self.pending_reaction_window = None
            return self._commit_pending_enemy_turn(self.pending_enemy_turn_result)
        self.pending_reaction_window = replace(
            window,
            stage=ReactionStage.DAMAGE_ROLL,
            natural_roll=returned.attack_roll.natural_roll,
            natural_rolls=returned.attack_roll.natural_rolls,
            total=returned.attack_roll.total,
            hit=True,
            critical=returned.critical,
        )
        self.board_message = _damage_roll_instruction(
            returned.source,
            critical=returned.critical,
        )
        return self.state_payload()

    def submit_deflected_missile_damage(
        self,
        *,
        damage: int,
    ) -> dict[str, object]:
        if self.combat_state is None or self.pending_enemy_turn_result is None:
            raise ValueError("Brak trafienia odrzuconym pociskiem.")
        window = self.pending_reaction_window
        if (
            window is None
            or window.current_option.kind != ReactionKind.DEFLECT_MISSILES
            or window.stage != ReactionStage.DAMAGE_ROLL
        ):
            raise ValueError("Deflect Missiles nie oczekuje obrażeń odrzuconego pocisku.")
        if damage < 0:
            raise ValueError("Obrażenia nie mogą być ujemne.")
        incoming = self.pending_enemy_turn_result.damage
        if incoming is None or not incoming.components:
            raise ValueError("Nie można ustalić typu obrażeń złapanego pocisku.")
        target = next(
            actor
            for actor in self.pending_enemy_turn_result.state.actors
            if str(actor.id) == window.current_option.target_actor_id
        )
        damage_result = resolve_damage(
            (
                DamageComponentInput(
                    int(damage),
                    incoming.components[0].damage_type,
                    "Odrzucony pocisk",
                ),
            )
        )
        applied = apply_damage_result(
            target,
            damage_result,
            critical=window.critical,
        )
        updated_enemy_state = replace_actor(
            self.pending_enemy_turn_result.state,
            applied.actor_after,
        )
        self.pending_enemy_turn_result = replace(
            self.pending_enemy_turn_result,
            state=updated_enemy_state,
        )
        self._add_message(
            "Odrzucony pocisk",
            (
                f"{target.name}: HP {applied.hp_before} → {applied.hp_after}; "
                f"obrażenia {applied.damage.total_applied}."
            ),
        )
        self._record(
            "ui_combat_deflected_missile_damage",
            {
                "actor_id": window.current_option.reactor_actor_id,
                "target_id": window.current_option.target_actor_id,
                "damage": applied.damage.total_applied,
                "hp_before": applied.hp_before,
                "hp_after": applied.hp_after,
            },
        )
        self.pending_reaction_window = None
        return self._commit_pending_enemy_turn(self.pending_enemy_turn_result)

    def _maybe_open_defensive_spell_reaction(self) -> bool:
        if (
            self.combat_state is None
            or self.pending_enemy_turn_result is None
            or self.pending_reaction_window is not None
            or self.pending_state.defensive_spell_reaction_resolved is True
        ):
            return False
        encounter = self._active_encounter()
        if encounter is None:
            return False
        option = self.defensive_spell_reaction_flow.option(
            state=self.combat_state,
            enemy_result=self.pending_enemy_turn_result,
            actions_by_actor=encounter.combat_actions_by_actor,
        )
        if option is None:
            self.pending_state.defensive_spell_reaction_resolved = True
            return False
        self.pending_reaction_window = open_reaction_window(
            interrupted_actor_id=str(self.pending_enemy_turn_result.enemy.id),
            trigger_event=option.trigger_event,
            options=(option,),
        )
        actor = self._actor_by_string_id(option.reactor_actor_id)
        attack_total = self.pending_enemy_turn_result.attack_roll.total
        self.board_message = (
            f"{actor.name} został trafiony wynikiem {attack_total}. "
            f"Rzuć {option.label} (+{option.value} AC) albo pomiń reakcję."
        )
        self._add_message("Reakcja obronna", self.board_message)
        self._record(
            "ui_combat_defensive_spell_offered",
            {
                "actor_id": option.reactor_actor_id,
                "attacker_id": option.target_actor_id,
                "spell_id": option.effect_id,
                "attack_total": attack_total,
                "ac_bonus": option.value,
            },
        )
        self._sync_board_leds()
        return True

    def _maybe_open_retaliation_spell_reaction(self) -> bool:
        result = self.pending_enemy_turn_result
        if (
            self.combat_state is None
            or result is None
            or self.pending_reaction_window is not None
            or self.pending_state.retaliation_spell_reaction_resolved is True
            or result.applied_damage is None
            or result.applied_damage.damage.total_applied <= 0
            or result.target is None
        ):
            return False
        encounter = self._active_encounter()
        if encounter is None:
            return False
        reactor = next(
            (
                actor
                for actor in result.state.actors
                if str(actor.id) == result.target.id
            ),
            None,
        )
        if (
            reactor is None
            or reactor.is_defeated()
            or not reaction_available_for(result.state, reactor)
        ):
            self.pending_state.retaliation_spell_reaction_resolved = True
            return False
        action = next(
            (
                candidate
                for candidate in encounter.combat_actions_by_actor.get(
                    reactor.id,
                    (),
                )
                if candidate.action_type == "reaction_damage"
                and can_consume_spell_resource(
                    reactor,
                    candidate.spell_level,
                    spell_id=candidate.id,
                )
                and (
                    (validation := actor_spell_cast_validation(
                        reactor,
                        candidate.id,
                        condition_states=result.state.condition_states,
                        active_effects=self.active_combat_effects,
                    ))
                    is None
                    or validation.valid
                )
            ),
            None,
        )
        if action is None:
            self.pending_state.retaliation_spell_reaction_resolved = True
            return False
        option = ReactionOption(
            id=f"retaliation-spell:{reactor.id}:{action.id}",
            kind=ReactionKind.RETALIATION_SPELL,
            reactor_actor_id=str(reactor.id),
            target_actor_id=str(result.enemy.id),
            trigger_event="actor_damaged_by_enemy",
            effect_id=action.id,
            label=action.label,
            value=action.damage_die_sides,
            spell_level=action.spell_level,
        )
        self.pending_reaction_window = open_reaction_window(
            interrupted_actor_id=str(result.enemy.id),
            trigger_event=option.trigger_event,
            options=(option,),
        )
        self.board_message = (
            f"{reactor.name} otrzymał obrażenia od {result.enemy.name}. "
            f"Może użyć reakcji: {action.label}."
        )
        self._add_message("Reakcja ofensywna", self.board_message)
        self._sync_board_leds()
        return True

    def cast_retaliation_spell_reaction(self) -> dict[str, object]:
        result = self.pending_enemy_turn_result
        window = self.pending_reaction_window
        if (
            result is None
            or window is None
            or window.current_option.kind != ReactionKind.RETALIATION_SPELL
        ):
            raise ValueError("Brak oczekującej ofensywnej reakcji czarem.")
        encounter = self._active_encounter()
        if encounter is None:
            raise ValueError("Brak aktywnego encountera.")
        option = window.current_option
        reactor = next(
            actor
            for actor in result.state.actors
            if str(actor.id) == option.reactor_actor_id
        )
        action = next(
            candidate
            for candidate in encounter.combat_actions_by_actor.get(
                reactor.id,
                (),
            )
            if candidate.id == option.effect_id
        )
        validation = actor_spell_cast_validation(
            reactor,
            action.id,
            condition_states=result.state.condition_states,
            active_effects=self.active_combat_effects,
        )
        if validation is not None:
            if not validation.valid:
                raise ValueError(" ".join(validation.errors))
            cast_level = validation.cast_level
        else:
            cast_level = min(available_cast_levels(reactor, action.spell_level))
        reaction = use_actor_reaction(result.state, reactor)
        if not reaction.accepted:
            raise ValueError(reaction.message)
        reactor_after_reaction = _actor_by_string_id_from_state(
            reaction.state,
            str(reactor.id),
        )
        spell_use = consume_spell_resource(
            reactor_after_reaction,
            action.spell_level,
            cast_level,
            spell_id=action.id,
        )
        updated_state = replace_actor(reaction.state, spell_use.actor_after)
        enemy = next(
            actor
            for actor in updated_state.actors
            if actor.id == result.enemy.id
        )
        save = resolve_spell_save(
            enemy,
            ability=action.save_ability or "dexterity",
            dc=reactor.spell_save_dc,
            natural_roll=self.encounter_rng.randint(1, 20),
            condition_states=updated_state.condition_states,
            combat_actors=updated_state.actors,
        )
        dice_count = int(action.ongoing_damage_dice_count) + max(
            0,
            cast_level - action.spell_level,
        ) * int(action.upcast_value_per_level)
        amount = sum(
            self.encounter_rng.randint(1, action.damage_die_sides)
            for _ in range(dice_count)
        )
        if save.success:
            amount //= 2
        applied = apply_damage_result(
            enemy,
            resolve_damage(
                (
                    DamageComponentInput(
                        amount,
                        action.damage_type,
                        action.label,
                    ),
                )
            ),
        )
        updated_state = replace_actor(updated_state, applied.actor_after)
        updated_result = replace(
            result,
            state=updated_state,
            enemy=applied.actor_after,
            moved_enemy=(
                applied.actor_after if result.moved_enemy is not None else None
            ),
        )
        self.pending_enemy_turn_result = updated_result
        self.pending_state.retaliation_spell_reaction_resolved = True
        self.pending_reaction_window = None
        self._add_message(
            "Reakcja ofensywna",
            (
                f"{reactor.name} rzuca {action.label}; {enemy.name} otrzymuje "
                f"{applied.damage.total_applied} obrażeń {action.damage_type} "
                f"(save {save.total}/{reactor.spell_save_dc})."
            ),
        )
        return self._commit_pending_enemy_turn(updated_result)

    def skip_retaliation_spell_reaction(self) -> dict[str, object]:
        window = self.pending_reaction_window
        if (
            window is None
            or window.current_option.kind != ReactionKind.RETALIATION_SPELL
        ):
            raise ValueError("Brak oczekującej ofensywnej reakcji czarem.")
        self.pending_state.retaliation_spell_reaction_resolved = True
        self.pending_reaction_window = None
        return self._commit_pending_enemy_turn()

    def _maybe_open_counterspell_reaction(self) -> bool:
        if (
            self.combat_state is None
            or self.pending_enemy_turn_result is None
            or self.pending_reaction_window is not None
            or self.pending_state.counterspell_reaction_resolved is True
        ):
            return False
        encounter = self._active_encounter()
        if encounter is None:
            return False
        option = self.counterspell_reaction_flow.option(
            board=encounter.board,
            state=self.combat_state,
            enemy_result=self.pending_enemy_turn_result,
            actions_by_actor=encounter.combat_actions_by_actor,
        )
        if option is None:
            self.pending_state.counterspell_reaction_resolved = True
            return False
        self.pending_reaction_window = open_reaction_window(
            interrupted_actor_id=str(self.pending_enemy_turn_result.enemy.id),
            trigger_event=option.trigger_event,
            options=(option,),
        )
        actor = self._actor_by_string_id(option.reactor_actor_id)
        source = self.pending_enemy_turn_result.source
        source_name = source.name if source is not None else "wrogi czar"
        self.board_message = (
            f"{actor.name} widzi rzucany czar {source_name}. "
            f"Rzuć {option.label} albo pomiń reakcję."
        )
        self._add_message("Kontrczar", self.board_message)
        self._record(
            "ui_combat_counterspell_offered",
            {
                "actor_id": option.reactor_actor_id,
                "caster_id": option.target_actor_id,
                "spell_id": option.effect_id,
                "cast_levels": list(option.cast_levels),
            },
        )
        self._sync_board_leds()
        return True

    def cast_counterspell_reaction(self, *, cast_level: int) -> dict[str, object]:
        if self.combat_state is None or self.pending_enemy_turn_result is None:
            raise ValueError("Brak oczekującego wrogiego czaru.")
        window = self.pending_reaction_window
        if (
            window is None
            or window.current_option.kind != ReactionKind.SPELL_COUNTER
            or window.stage != ReactionStage.CHOICE
        ):
            raise ValueError("Brak oczekującego wyboru Kontrczaru.")
        encounter = self._active_encounter()
        if encounter is None:
            raise ValueError("Brak danych encountera dla aktywnej walki.")
        option = window.current_option
        resolution = self.counterspell_reaction_flow.cast(
            state=self.combat_state,
            enemy_result=self.pending_enemy_turn_result,
            option=option,
            cast_level=int(cast_level),
            actions_by_actor=encounter.combat_actions_by_actor,
        )
        self.combat_state = resolution.state
        self.pending_enemy_turn_result = resolution.result
        self._add_message("Kontrczar", resolution.message)
        if resolution.countered:
            self.pending_state.counterspell_reaction_resolved = True
            self.pending_reaction_window = None
            self._record(
                "ui_combat_counterspell_cast",
                {
                    "actor_id": option.reactor_actor_id,
                    "caster_id": option.target_actor_id,
                    "spell_id": option.effect_id,
                    "cast_level": resolution.cast_level,
                    "countered": True,
                    "automatic": True,
                },
            )
            return self._commit_pending_enemy_turn()
        self.pending_reaction_window = replace(
            window,
            stage=ReactionStage.ABILITY_CHECK,
            dc=resolution.check_dc,
            modifier=resolution.check_modifier,
            cast_level=resolution.cast_level,
        )
        self.board_message = resolution.message
        return self.state_payload()

    def submit_counterspell_check(self, *, natural_roll: int) -> dict[str, object]:
        if self.combat_state is None or self.pending_enemy_turn_result is None:
            raise ValueError("Brak oczekującego testu Kontrczaru.")
        window = self.pending_reaction_window
        if (
            window is None
            or window.current_option.kind != ReactionKind.SPELL_COUNTER
            or window.stage != ReactionStage.ABILITY_CHECK
            or window.cast_level is None
        ):
            raise ValueError("Brak oczekującego testu Kontrczaru.")
        source = self.pending_enemy_turn_result.source
        if source is None:
            raise ValueError("Brak źródła przerywanego czaru.")
        interrupted_level = int(source.cast_level or source.spell_level)
        option = window.current_option
        resolution = self.counterspell_reaction_flow.resolve_check(
            state=self.combat_state,
            enemy_result=self.pending_enemy_turn_result,
            caster_id=option.reactor_actor_id,
            cast_level=window.cast_level,
            interrupted_spell_level=interrupted_level,
            natural_roll=int(natural_roll),
        )
        self.pending_enemy_turn_result = resolution.result
        self.pending_state.counterspell_reaction_resolved = True
        self.pending_reaction_window = None
        self._add_message("Kontrczar", resolution.message)
        self._record(
            "ui_combat_counterspell_check",
            {
                "actor_id": option.reactor_actor_id,
                "caster_id": option.target_actor_id,
                "cast_level": resolution.cast_level,
                "natural_roll": natural_roll,
                "total": resolution.check_roll.total if resolution.check_roll else None,
                "dc": resolution.check_dc,
                "countered": resolution.countered,
            },
        )
        return self._commit_pending_enemy_turn()

    def skip_counterspell_reaction(self) -> dict[str, object]:
        window = self.pending_reaction_window
        if window is None or window.current_option.kind != ReactionKind.SPELL_COUNTER:
            raise ValueError("Brak oczekującego Kontrczaru.")
        self.pending_state.counterspell_reaction_resolved = True
        self.pending_reaction_window = None
        self._record(
            "ui_combat_counterspell_skipped",
            {
                "actor_id": window.current_option.reactor_actor_id,
                "spell_id": window.current_option.effect_id,
            },
        )
        return self._commit_pending_enemy_turn()

    def cast_defensive_spell_reaction(self) -> dict[str, object]:
        if self.combat_state is None or self.pending_enemy_turn_result is None:
            raise ValueError("Brak oczekującego ataku dla reakcji obronnej.")
        window = self.pending_reaction_window
        if window is None or window.current_option.kind != ReactionKind.DEFENSIVE_SPELL:
            raise ValueError("Brak oczekującego czaru obronnego.")
        encounter = self._active_encounter()
        if encounter is None:
            raise ValueError("Brak danych encountera dla aktywnej walki.")
        option = window.current_option
        resolution = self.defensive_spell_reaction_flow.cast(
            state=self.combat_state,
            enemy_result=self.pending_enemy_turn_result,
            active_effects=self.active_combat_effects,
            option=option,
            actions_by_actor=encounter.combat_actions_by_actor,
        )
        self.combat_state = resolution.state
        self.active_combat_effects = resolution.active_effects
        self.pending_enemy_turn_result = resolution.result
        self.pending_state.defensive_spell_reaction_resolved = True
        self.pending_reaction_window = None
        self._add_message("Reakcja obronna", resolution.message)
        self._record(
            "ui_combat_defensive_spell_cast",
            {
                "actor_id": option.reactor_actor_id,
                "attacker_id": option.target_actor_id,
                "spell_id": option.effect_id,
                "prevented_hit": resolution.prevented_hit,
                "armor_class": resolution.result.target.ac,
            },
        )
        return self._commit_pending_enemy_turn(resolution.result)

    def skip_defensive_spell_reaction(self) -> dict[str, object]:
        window = self.pending_reaction_window
        if window is None or window.current_option.kind != ReactionKind.DEFENSIVE_SPELL:
            raise ValueError("Brak oczekującego czaru obronnego.")
        self.pending_state.defensive_spell_reaction_resolved = True
        self.pending_reaction_window = None
        self._record(
            "ui_combat_defensive_spell_skipped",
            {
                "actor_id": window.current_option.reactor_actor_id,
                "spell_id": window.current_option.effect_id,
            },
        )
        return self._commit_pending_enemy_turn()

    def _ensure_reaction_window(self, kind: ReactionKind) -> ReactionWindow:
        window = self.pending_reaction_window
        if window is not None:
            if window.current_option.kind != kind:
                raise ValueError("Aktualne okno reakcji oczekuje innego rodzaju reakcji.")
            return window
        if kind == ReactionKind.READY_ATTACK:
            pending = self.pending_ready_attack
            if pending is None:
                raise ValueError("Nie ma oczekującej przygotowanej akcji.")
            options = (
                ReactionOption(
                    id=f"ready:{pending.effect_id}:{pending.target_id}",
                    kind=kind,
                    reactor_actor_id=pending.readied_actor_id,
                    target_actor_id=pending.target_id,
                    trigger_event=pending.trigger,
                    effect_id=pending.effect_id,
                    label="Ready",
                ),
            )
            interrupted_actor_id = pending.target_id
            trigger_event = pending.trigger
        else:
            pending = self.pending_enemy_opportunity_attack
            if pending is None:
                raise ValueError("Nie ma oczekującego ataku okazyjnego.")
            options = tuple(
                ReactionOption(
                    id=f"opportunity:{actor_id}:{pending.target_id}",
                    kind=kind,
                    reactor_actor_id=actor_id,
                    target_actor_id=pending.target_id,
                    trigger_event="enemy_leaves_reach",
                    label="Atak okazyjny",
                )
                for actor_id in pending.threat_actor_ids
            )
            interrupted_actor_id = pending.target_id
            trigger_event = "enemy_leaves_reach"
        opened = open_reaction_window(
            interrupted_actor_id=interrupted_actor_id,
            trigger_event=trigger_event,
            options=options,
        )
        assert opened is not None
        stage = ReactionStage(pending.stage)
        self.pending_reaction_window = replace(
            opened,
            current_index=(
                pending.current_index
                if isinstance(pending, PendingEnemyOpportunityAttack)
                else 0
            ),
            stage=stage,
            natural_roll=pending.natural_roll,
            natural_rolls=pending.natural_rolls,
            total=pending.total,
            hit=pending.hit,
            critical=pending.critical,
        )
        return self.pending_reaction_window

    def _advance_reaction_window_or_resume_enemy(self) -> dict[str, object]:
        window = self.pending_reaction_window
        if window is None:
            self.pending_enemy_opportunity_attack = None
            self.pending_ready_attack = None
            self._resume_enemy_turn_after_reaction_prompt()
            return self.state_payload()
        if self.combat_state is None:
            raise ValueError("Walka nie została rozpoczęta.")
        available_ids = {
            str(actor.id)
            for actor in self.combat_state.actors
            if reaction_available_for(self.combat_state, actor)
        }
        self.pending_reaction_window = advance_reaction_window(
            window,
            available_reactor_ids=available_ids,
        )
        self._activate_current_reaction_option()
        if self.pending_reaction_window is None:
            self._record(
                "ui_combat_reaction_window_closed",
                {
                    "interrupted_actor_id": window.interrupted_actor_id,
                    "trigger_event": window.trigger_event,
                },
            )
            self._resume_enemy_turn_after_reaction_prompt()
            return self.state_payload()
        option = self.pending_reaction_window.current_option
        reactor = self._actor_by_string_id(option.reactor_actor_id)
        target = self._actor_by_string_id(option.target_actor_id)
        self.board_message = (
            f"{target.name}: kolejna reakcja — {reactor.name}, {option.label.lower()}."
        )
        self._record(
            "ui_combat_reaction_advanced",
            {
                "option_id": option.id,
                "kind": option.kind.value,
                "reactor_actor_id": option.reactor_actor_id,
                "target_actor_id": option.target_actor_id,
            },
        )
        self._sync_board_leds()
        return self.state_payload()

    def submit_enemy_saving_throw(
        self,
        natural_roll: int,
        natural_roll_2: int | None = None,
        natural_rerolls: tuple[int, ...] = (),
        bardic_inspiration_roll: int | None = None,
        bless_roll: int | None = None,
    ) -> dict[str, object]:
        if self.combat_state is None:
            raise ValueError("Walka nie została rozpoczęta.")
        if self.pending_enemy_saving_throw is None:
            raise ValueError("Brak oczekującego rzutu obronnego przeciw efektowi przeciwnika.")
        result = self.pending_enemy_turn_ack_result
        if result is None:
            raise ValueError("Brak wyniku tury przeciwnika dla rzutu obronnego.")
        target = self._actor_by_string_id(self.pending_enemy_saving_throw.target_id)
        inspiration = next(
            (
                effect
                for effect in self.active_combat_effects
                if effect.actor_id == str(target.id)
                and effect.kind == "bardic_inspiration"
            ),
            None,
        )
        additional_modifiers: tuple[RollModifier, ...] = ()
        if bardic_inspiration_roll is not None:
            if inspiration is None:
                raise ValueError("Postać nie ma Bardic Inspiration.")
            if not 1 <= bardic_inspiration_roll <= inspiration.value:
                raise ValueError(
                    f"Wynik Bardic Inspiration musi mieścić się w zakresie "
                    f"1–{inspiration.value}."
                )
            additional_modifiers = (
                RollModifier(
                    inspiration.label,
                    bardic_inspiration_roll,
                    RollModifierType.FEATURE,
                    stacking_key="bardic_inspiration",
                ),
            )
        bless = next(
            (
                effect
                for effect in self.active_combat_effects
                if effect.actor_id == str(target.id)
                and effect.kind in {
                    "bless_roll_bonus",
                    "resistance_roll_bonus",
                }
            ),
            None,
        )
        if bless_roll is not None:
            if bless is None or not 1 <= bless_roll <= bless.value:
                raise ValueError("Nieprawidłowy wynik kości Bless.")
            additional_modifiers = (
                *additional_modifiers,
                RollModifier(
                    bless.label,
                    bless_roll,
                    RollModifierType.SPELL,
                    stacking_key=bless.id,
                ),
            )
        transition = self.enemy_turn_flow.resolve_player_saving_throw(
            result=result,
            natural_roll=natural_roll,
            natural_roll_2=natural_roll_2,
            natural_rerolls=natural_rerolls,
            additional_modifiers=additional_modifiers,
            active_effects=self.active_combat_effects,
        )
        self.combat_state = transition.result.state
        self.pending_enemy_turn_ack_result = transition.result
        self.pending_enemy_saving_throw = None
        if inspiration is not None and bardic_inspiration_roll is not None:
            self.active_combat_effects = tuple(
                effect
                for effect in self.active_combat_effects
                if effect.id != inspiration.id
            )
        if (
            bless is not None
            and bless.kind == "resistance_roll_bonus"
            and bless_roll is not None
        ):
            self.active_combat_effects = tuple(
                effect
                for effect in self.active_combat_effects
                if effect.id != bless.id
            )
        self.board_message = transition.board_message
        self._add_message(transition.message_title, transition.message_body)
        self._record(transition.event_type, dict(transition.event_payload))
        if transition.result.applied_damage is not None:
            applied = transition.result.applied_damage
            if applied.damage.total_applied > 0:
                self._apply_combat_trigger_events(
                    (
                        EffectEvent(
                            EffectEventType.DAMAGE_TAKEN,
                            actor_id=str(applied.actor_after.id),
                            target_actor_id=str(transition.result.enemy.id),
                        ),
                    )
                )
                self.pending_enemy_turn_ack_result = replace(
                    transition.result,
                    state=self.combat_state,
                )
            self._maybe_prompt_concentration_check(transition.result.applied_damage)
        self._sync_board_leds()
        return self.state_payload()

    def start_enemy_opportunity_attack(self) -> dict[str, object]:
        window = self._ensure_reaction_window(ReactionKind.OPPORTUNITY_ATTACK)
        pending = self.pending_enemy_opportunity_attack
        if pending is None or pending.stage != "choice":
            raise ValueError("Nie ma ataku okazyjnego bohatera do rozpoczęcia.")
        attacker = self._actor_by_string_id(pending.attacker_id)
        target = self._actor_by_string_id(pending.target_id)
        encounter = self._active_encounter()
        if encounter is None:
            raise ValueError("Brak danych encountera dla aktywnej walki.")
        source = encounter.attack_sources_by_actor.get(attacker.id)
        if source is None:
            raise ValueError(f"Aktor {attacker.name} nie ma zdefiniowanego ataku.")
        source = self._effective_attack_source(attacker, source, target)
        self.pending_reaction_window = start_current_reaction(window)
        self._activate_current_reaction_option()
        self.board_message = f"{attacker.name} wykonuje atak okazyjny przeciwko {target.name}. Wpisz rzut d20."
        self._add_message("Atak okazyjny", f"{attacker.name} reaguje atakiem okazyjnym. {roll_instruction(source.attack_roll_request).message}")
        self._record(
            "ui_combat_enemy_opportunity_started",
            {"attacker_id": pending.attacker_id, "target_id": pending.target_id},
        )
        self._sync_board_leds()
        return self.state_payload()

    def skip_enemy_opportunity_attack(self) -> dict[str, object]:
        self._ensure_reaction_window(ReactionKind.OPPORTUNITY_ATTACK)
        pending = self.pending_enemy_opportunity_attack
        if pending is None or pending.stage != "choice":
            raise ValueError("Nie ma ataku okazyjnego bohatera do pominięcia.")
        attacker = self._actor_by_string_id(pending.attacker_id)
        self._add_message("Atak okazyjny", f"{attacker.name} nie używa reakcji.")
        self._record(
            "ui_combat_enemy_opportunity_skipped",
            {"attacker_id": pending.attacker_id, "target_id": pending.target_id},
        )
        return self._advance_enemy_opportunity_or_resume_preview()

    def submit_enemy_opportunity_attack_roll(self, *, natural_roll: int, natural_roll_2: int | None = None) -> dict[str, object]:
        window = self._ensure_reaction_window(ReactionKind.OPPORTUNITY_ATTACK)
        pending = self.pending_enemy_opportunity_attack
        if pending is None or pending.stage != "attack_roll":
            raise ValueError("Nie ma oczekującego rzutu ataku okazyjnego.")
        if self.combat_state is None:
            raise ValueError("Walka nie została rozpoczęta.")
        encounter = self._active_encounter()
        if encounter is None:
            raise ValueError("Brak danych encountera dla aktywnej walki.")
        reaction = self.player_reaction_flow.resolve_attack_roll(
            state=self.combat_state,
            attacker_id=pending.attacker_id,
            target_id=pending.target_id,
            attack_sources_by_actor=encounter.attack_sources_by_actor,
            active_effects=self.active_combat_effects,
            natural_roll=natural_roll,
            natural_roll_2=natural_roll_2,
        )
        self.combat_state = reaction.state
        self.active_combat_effects = reaction.active_effects
        self._mark_rage_activity(
            pending.attacker_id,
            label="Rage podtrzymany atakiem reakcyjnym",
        )
        self.pending_enemy_turn_result = self._enemy_turn_result_with_spent_reactions()
        self._record(
            "ui_combat_enemy_opportunity_attack_roll",
            {
                "attacker_id": pending.attacker_id,
                "target_id": pending.target_id,
                "natural_roll": reaction.attack_roll.natural_roll,
                "natural_rolls": list(reaction.attack_roll.natural_rolls),
                "total": reaction.attack_roll.total,
                "hit": reaction.hit,
                "critical": reaction.critical,
            },
        )
        if not reaction.hit:
            self.pending_reaction_window = record_current_reaction_attack(
                window,
                natural_roll=reaction.attack_roll.natural_roll,
                natural_rolls=reaction.attack_roll.natural_rolls,
                total=reaction.attack_roll.total,
                hit=False,
                critical=False,
            )
            self._add_message("Atak okazyjny", reaction.message)
            return self._advance_enemy_opportunity_or_resume_preview()
        self._apply_combat_trigger_events(
            (
                EffectEvent(
                    EffectEventType.ATTACK_HIT,
                    actor_id=pending.attacker_id,
                    target_actor_id=pending.target_id,
                ),
            )
        )
        if self.pending_enemy_turn_result is not None:
            self.pending_enemy_turn_result = (
                self._enemy_turn_result_with_spent_reactions()
            )
        self.pending_reaction_window = record_current_reaction_attack(
            window,
            natural_roll=reaction.attack_roll.natural_roll,
            natural_rolls=reaction.attack_roll.natural_rolls,
            total=reaction.attack_roll.total,
            hit=True,
            critical=reaction.critical,
        )
        self._activate_current_reaction_option()
        self._add_message(
            "Atak okazyjny",
            (
                f"{reaction.message} "
                f"{_damage_roll_instruction(reaction.source, critical=reaction.critical)}"
            ),
        )
        self._sync_board_leds()
        return self.state_payload()

    def submit_enemy_opportunity_damage_roll(
        self,
        *,
        damage: int | None = None,
        component_totals: Mapping[str, int] | None = None,
    ) -> dict[str, object]:
        self._ensure_reaction_window(ReactionKind.OPPORTUNITY_ATTACK)
        pending = self.pending_enemy_opportunity_attack
        if pending is None or pending.stage != "damage_roll":
            raise ValueError("Nie ma oczekujących obrażeń ataku okazyjnego.")
        if self.combat_state is None:
            raise ValueError("Walka nie została rozpoczęta.")
        encounter = self._active_encounter()
        if encounter is None:
            raise ValueError("Brak danych encountera dla aktywnej walki.")
        damage_resolution = self.player_reaction_flow.apply_damage(
            state=self.combat_state,
            attacker_id=pending.attacker_id,
            target_id=pending.target_id,
            attack_sources_by_actor=encounter.attack_sources_by_actor,
            active_effects=self.active_combat_effects,
            damage=damage,
            component_totals=component_totals,
            critical=pending.critical,
        )
        applied_damage = damage_resolution.applied_damage
        updated_target = applied_damage.actor_after
        self.combat_state = damage_resolution.state
        self.pending_enemy_turn_result = self._enemy_turn_result_with_updated_actor(updated_target)
        attacker = self._actor_by_string_id(pending.attacker_id)
        message = f"{attacker.name} trafia atakiem okazyjnym. {_damage_application_message(applied_damage)}"
        self._record(
            "ui_combat_enemy_opportunity_damage",
            {
                "attacker_id": pending.attacker_id,
                "target_id": pending.target_id,
                "damage": applied_damage.damage.total_applied,
                "damage_result": _applied_damage_payload(applied_damage),
            },
        )
        reaction_events = []
        if applied_damage.damage.total_applied > 0:
            reaction_events.append(
                EffectEvent(
                    EffectEventType.DAMAGE_TAKEN,
                    actor_id=pending.target_id,
                    target_actor_id=pending.attacker_id,
                )
            )
        self._apply_combat_trigger_events(tuple(reaction_events))
        if self.pending_enemy_turn_result is not None:
            self.pending_enemy_turn_result = replace(
                self.pending_enemy_turn_result,
                state=self.combat_state,
            )
        if applied_damage.defeated_by_damage:
            self.pending_reaction_window = None
            self.pending_enemy_opportunity_attack = None
            self.pending_enemy_turn_result = None
            self.pending_enemy_turn_intent = None
            self.pending_enemy_turn_ack_result = None
            self._add_message("Atak okazyjny", f"{message} Ruch przeciwnika zostaje przerwany.")
            self._expire_turn_end_effects(updated_target)
            self.combat_state = finish_turn(self.combat_state)
            self._expire_turn_start_effects()
            self.board_message = f"{updated_target.name} pada od ataku okazyjnego. Tura przeciwnika zakończona."
            self._record("ui_combat_enemy_opportunity_defeated_enemy", {"enemy_id": pending.target_id})
            self._maybe_prompt_concentration_check(applied_damage)
            self._sync_board_leds()
            return self.state_payload()
        self._maybe_prompt_concentration_check(applied_damage)
        self._add_message("Atak okazyjny", message)
        return self._advance_enemy_opportunity_or_resume_preview()

    def _advance_enemy_opportunity_or_resume_preview(self) -> dict[str, object]:
        self._ensure_reaction_window(ReactionKind.OPPORTUNITY_ATTACK)
        return self._advance_reaction_window_or_resume_enemy()

    def start_ready_attack(self) -> dict[str, object]:
        window = self._ensure_reaction_window(ReactionKind.READY_ATTACK)
        pending = self.pending_ready_attack
        if pending is None or pending.stage != "choice":
            raise ValueError("Nie ma przygotowanej akcji do rozpoczęcia.")
        attacker = self._actor_by_string_id(pending.readied_actor_id)
        target = self._actor_by_string_id(pending.target_id)
        encounter = self._active_encounter()
        if encounter is None:
            raise ValueError("Brak danych encountera dla aktywnej walki.")
        source = encounter.attack_sources_by_actor.get(attacker.id)
        if source is None:
            raise ValueError(f"Aktor {attacker.name} nie ma zdefiniowanego ataku.")
        source = self._effective_attack_source(attacker, source, target)
        self.pending_reaction_window = start_current_reaction(window)
        self._activate_current_reaction_option()
        self.board_message = f"{attacker.name} używa przygotowanej akcji przeciwko {target.name}. Wpisz rzut d20."
        self._add_message("Ready", f"{attacker.name} używa przygotowanej akcji. {roll_instruction(source.attack_roll_request).message}")
        self._record(
            "ui_combat_ready_attack_started",
            {"attacker_id": pending.readied_actor_id, "target_id": pending.target_id, "trigger": pending.trigger},
        )
        self._sync_board_leds()
        return self.state_payload()

    def skip_ready_attack(self) -> dict[str, object]:
        self._ensure_reaction_window(ReactionKind.READY_ATTACK)
        pending = self.pending_ready_attack
        if pending is None or pending.stage != "choice":
            raise ValueError("Nie ma przygotowanej akcji do pominięcia.")
        attacker = self._actor_by_string_id(pending.readied_actor_id)
        self._add_message("Ready", f"{attacker.name} nie używa przygotowanej akcji.")
        self._record(
            "ui_combat_ready_attack_skipped",
            {"attacker_id": pending.readied_actor_id, "target_id": pending.target_id, "trigger": pending.trigger},
        )
        return self._advance_reaction_window_or_resume_enemy()

    def submit_ready_attack_roll(self, *, natural_roll: int, natural_roll_2: int | None = None) -> dict[str, object]:
        window = self._ensure_reaction_window(ReactionKind.READY_ATTACK)
        pending = self.pending_ready_attack
        if pending is None or pending.stage != "attack_roll":
            raise ValueError("Nie ma oczekującego rzutu przygotowanej akcji.")
        if self.combat_state is None:
            raise ValueError("Walka nie została rozpoczęta.")
        encounter = self._active_encounter()
        if encounter is None:
            raise ValueError("Brak danych encountera dla aktywnej walki.")
        reaction = self.player_reaction_flow.resolve_attack_roll(
            state=self.combat_state,
            attacker_id=pending.readied_actor_id,
            target_id=pending.target_id,
            attack_sources_by_actor=encounter.attack_sources_by_actor,
            active_effects=self.active_combat_effects,
            natural_roll=natural_roll,
            natural_roll_2=natural_roll_2,
            consumed_effect_id=pending.effect_id,
        )
        self.combat_state = reaction.state
        self.active_combat_effects = reaction.active_effects
        self._mark_rage_activity(
            pending.readied_actor_id,
            label="Rage podtrzymany atakiem reakcyjnym",
        )
        self.pending_enemy_turn_result = self._enemy_turn_result_with_spent_reactions()
        self._record(
            "ui_combat_ready_attack_roll",
            {
                "attacker_id": pending.readied_actor_id,
                "target_id": pending.target_id,
                "natural_roll": reaction.attack_roll.natural_roll,
                "natural_rolls": list(reaction.attack_roll.natural_rolls),
                "total": reaction.attack_roll.total,
                "hit": reaction.hit,
                "critical": reaction.critical,
            },
        )
        if not reaction.hit:
            self.pending_reaction_window = record_current_reaction_attack(
                window,
                natural_roll=reaction.attack_roll.natural_roll,
                natural_rolls=reaction.attack_roll.natural_rolls,
                total=reaction.attack_roll.total,
                hit=False,
                critical=False,
            )
            self._add_message("Ready", reaction.message)
            return self._advance_reaction_window_or_resume_enemy()
        self._apply_combat_trigger_events(
            (
                EffectEvent(
                    EffectEventType.ATTACK_HIT,
                    actor_id=pending.readied_actor_id,
                    target_actor_id=pending.target_id,
                ),
            )
        )
        if self.pending_enemy_turn_result is not None:
            self.pending_enemy_turn_result = replace(
                self.pending_enemy_turn_result,
                state=self.combat_state,
            )
        self.pending_reaction_window = record_current_reaction_attack(
            window,
            natural_roll=reaction.attack_roll.natural_roll,
            natural_rolls=reaction.attack_roll.natural_rolls,
            total=reaction.attack_roll.total,
            hit=True,
            critical=reaction.critical,
        )
        self._activate_current_reaction_option()
        self._add_message(
            "Ready",
            (
                f"{reaction.message} "
                f"{_damage_roll_instruction(reaction.source, critical=reaction.critical)}"
            ),
        )
        self._sync_board_leds()
        return self.state_payload()

