def _long_cast_payload(cast) -> dict[str, object] | None:
    if cast is None:
        return None
    return {
        "caster_id": str(cast.caster_id),
        "spell_id": cast.spell_id,
        "label": cast.label,
        "cast_level": cast.cast_level,
        "required_actions": cast.required_actions,
        "completed_actions": cast.completed_actions,
        "remaining_actions": max(
            0,
            cast.required_actions - cast.completed_actions,
        ),
        "started_round": cast.started_round,
        "last_progress_round": cast.last_progress_round,
        "progress_percent": round(
            cast.completed_actions * 100 / cast.required_actions
        ),
    }


def _actor_portrait_url(actor: Actor) -> str | None:
    portrait = actor.portrait.strip().lstrip("/")
    if portrait.startswith("character_uploads/"):
        filename = portrait.removeprefix("character_uploads/")
        return f"/character-portraits/{filename}" if filename else None
    return f"/game-assets/{portrait}" if portrait else None


def _active_light_payload(actor: Actor) -> dict[str, object] | None:
    light = actor.active_light
    if light is None:
        return None
    return {
        "source_item_id": light.source_item_id,
        "source_name": light.source_name,
        "bright_distance_feet": light.current_bright_distance_feet,
        "dim_additional_feet": light.current_dim_additional_feet,
        "remaining_minutes": light.remaining_minutes,
        "shape": light.shape.value,
        "hood_lowered": light.hood_lowered,
    }


def _combat_actor_payload(
    actor: Actor,
    active_combat_effects: tuple[ActiveCombatEffect, ...] = (),
    *,
    turn_action: TurnActionState | None = None,
    movement_remaining_feet: int | None = None,
) -> dict[str, object]:
    concentration_effects = [
        effect.as_payload()
        for effect in active_combat_effects
        if effect.source_actor_id == str(actor.id) and effect.kind.startswith("concentration_")
    ]
    concentration = (
        {
            **concentration_effects[0],
            "target_actor_ids": [
                effect.get("target_actor_id")
                for effect in concentration_effects
                if effect.get("target_actor_id")
            ],
            "target_count": len(concentration_effects),
        }
        if concentration_effects
        else None
    )
    actor_effects = [effect.as_payload() for effect in active_combat_effects if effect.actor_id == str(actor.id)]
    return {
        "id": str(actor.id),
        "name": actor.name,
        "faction": actor.faction.value,
        "defeated": actor.is_defeated(),
        "portrait_url": _actor_portrait_url(actor),
        "size": actor.size.value,
        "size_label": creature_size_label_pl(actor.size),
        "damage_affinities": _damage_affinities_payload(actor),
        "senses": actor.senses.as_payload(),
        "condition_immunities": list(actor.condition_immunities),
        "triggers": [
            {
                "id": trigger.id,
                "label": trigger.label,
                "event_type": trigger.event_type.value,
                "effect_kind": trigger.effect_kind.value,
                "value": trigger.value,
            }
            for trigger in actor.triggers
        ],
        "features": [_feature_grant_payload(feature) for feature in actor.features],
        "background_permissions": list(actor_background_permission_ids(actor)),
        "ranger_exploration": {
            "favored_enemy_creature_type": favored_enemy_creature_type(actor),
            "natural_explorer_terrain": natural_explorer_terrain(actor),
        },
        "mobility_traits": {
            "climbing_cost_for_10_feet": climbing_movement_cost(
                actor,
                10,
                active_combat_effects,
            ),
            "can_climb_walls_and_ceilings": any(
                effect.actor_id == str(actor.id)
                and effect.kind == "spider_climb"
                for effect in active_combat_effects
            ),
            "jump_distances": {
                "running_long_feet": jump_distances(actor, active_combat_effects).running_long_jump_feet,
                "standing_long_feet": jump_distances(actor, active_combat_effects).standing_long_jump_feet,
                "running_high_feet": jump_distances(actor, active_combat_effects).running_high_jump_feet,
                "standing_high_feet": jump_distances(actor, active_combat_effects).standing_high_jump_feet,
            },
        },
        "hp": actor.hp,
        "max_hp": actor.max_hp,
        "effective_max_hp": effective_max_hit_points(actor),
        "exhaustion_level": actor.exhaustion_level,
        "temp_hp": actor.temp_hp,
        "wild_shape": (
            {
                "form_id": actor.wild_shape.form_id,
                "form_name": actor.wild_shape.form_name,
                "remaining_minutes": actor.wild_shape.remaining_minutes,
                "normal_form_hp": actor.wild_shape.original_hp,
                "normal_form_max_hp": actor.wild_shape.original_max_hp,
            }
            if actor.wild_shape is not None
            else None
        ),
        "ac": combat_armor_class(actor, active_combat_effects),
        "base_ac": actor.ac,
        "equipment_ac_bonus": effective_armor_class(actor) - actor.ac,
        "position": [actor.position.col, actor.position.row],
        "defeated": actor.is_defeated(),
        "dead": actor.is_dead(),
        "unconscious": actor.is_unconscious(),
        "death_save_required": actor.needs_death_save(),
        "death_saves": {
            "successes": actor.death_saves.successes,
            "failures": actor.death_saves.failures,
            "stable": actor.death_saves.stable,
            "dead": actor.death_saves.dead,
        },
        "spell_slots": [
            {"level": slot.level, "remaining": slot.remaining, "maximum": slot.maximum}
            for slot in actor.spell_slots
        ],
        "spell_save_dc": actor.spell_save_dc,
        "spells": [_spell_payload(actor, spell) for spell in actor.spells],
        "resource_pools": [
            {
                "id": pool.id,
                "label": pool.label,
                "current": pool.current,
                "maximum": pool.maximum,
                "recovery": pool.recovery.value,
                "recharge": (
                    None
                    if pool.recharge is None
                    else {
                        "die_sides": pool.recharge.die_sides,
                        "minimum_roll": pool.recharge.minimum_roll,
                    }
                ),
            }
            for pool in actor.resource_pools
        ],
        "proficiency_bonus": actor.proficiency_bonus,
        "level": actor.level,
        "experience_points": actor.experience_points,
        "proficiencies": {
            "saving_throws": list(actor.proficiencies.saving_throws),
            "skills": list(actor.proficiencies.skills),
            "expertise": list(actor.proficiencies.expertise),
            "weapons": list(actor.proficiencies.weapons),
            "armor": list(actor.proficiencies.armor),
            "tools": list(actor.proficiencies.tools),
        },
        "inventory": [inventory_item_payload(item) for item in actor.inventory],
        "active_light": _active_light_payload(actor),
        "currency": actor.currency.as_payload(),
        "carrying": carrying_payload(actor),
        "hands": hand_loadout_payload(actor.inventory),
        "effects": actor_effects,
        "concentration": concentration,
        "status_chips": _combat_actor_status_chips(
            actor,
            actor_effects=actor_effects,
            concentration=concentration,
            turn_action=turn_action,
            movement_remaining_feet=movement_remaining_feet,
        ),
    }


def _combat_actor_payload_with_conditions(
    actor: Actor,
    state: CombatState,
    active_combat_effects: tuple[ActiveCombatEffect, ...] = (),
    *,
    turn_action: TurnActionState | None = None,
    movement_remaining_feet: int | None = None,
) -> dict[str, object]:
    payload = _combat_actor_payload(
        actor,
        active_combat_effects,
        turn_action=turn_action,
        movement_remaining_feet=movement_remaining_feet,
    )
    conditions = tuple(
        condition.condition
        for condition in state.condition_states
        if condition.actor_id == str(actor.id)
    )
    payload["conditions"] = [condition.value for condition in conditions]
    reserved_hands = sum(
        1
        for condition in state.condition_states
        if condition.condition == CombatCondition.GRAPPLED
        and condition.source_actor_id == str(actor.id)
    )
    payload["hands"] = hand_loadout_payload(actor.inventory, reserved_hands=reserved_hands)
    if CombatCondition.PRONE in conditions:
        payload["status_chips"] = [
            *payload["status_chips"],
            _status_chip(
                "Powalony",
                tone="penalty",
                title="Ataki aktora mają utrudnienie; wstawanie kosztuje połowę szybkości.",
            ),
        ]
    for condition in conditions:
        if condition in {CombatCondition.PRONE, CombatCondition.GRAPPLED}:
            continue
        definition = condition_definition(condition)
        condition_state = next(
            item
            for item in state.condition_states
            if item.actor_id == str(actor.id) and item.condition == condition
        )
        details = definition.description
        if condition_state.source_label:
            details = f"{details} Źródło: {condition_state.source_label}."
        if condition_state.save_ability is not None:
            details = (
                f"{details} Save: {condition_state.save_ability} ST {condition_state.save_dc} "
                f"na {condition_state.save_timing.value}."
            )
        payload["status_chips"] = [
            *payload["status_chips"],
            _status_chip(definition.label, tone="penalty", title=details),
        ]
    grapple = next(
        (
            condition
            for condition in state.condition_states
            if condition.actor_id == str(actor.id)
            and condition.condition == CombatCondition.GRAPPLED
        ),
        None,
    )
    if grapple is not None:
        source = next(
            (
                candidate
                for candidate in state.actors
                if str(candidate.id) == grapple.source_actor_id
            ),
            None,
        )
        payload["status_chips"] = [
            *payload["status_chips"],
            _status_chip(
                "Chwytany",
                tone="penalty",
                title=(
                    f"Szybkość 0; chwyt utrzymuje {source.name}."
                    if source is not None
                    else "Szybkość 0 do zakończenia chwytu."
                ),
            ),
        ]
    return payload


def _condition_save_payload(
    actor: Actor,
    state: CombatState,
    condition_state: ConditionState,
    active_combat_effects: tuple[ActiveCombatEffect, ...] = (),
) -> dict[str, object]:
    ability = condition_state.save_ability or ""
    request = condition_roll_request(
        D20RollRequest(
            modifiers=(
                *saving_throw_roll_modifiers(actor, ability),
                *saving_throw_aura_modifiers(state.actors, actor),
            )
        ),
        state.condition_states,
        actor,
        saving_throw_ability=ability,
    )
    request = replace(
        request,
        mode=poison_protection_roll_mode(
            actor,
            active_combat_effects,
            (
                "poison"
                if condition_state.condition == CombatCondition.POISONED
                else condition_state.condition.value,
            ),
            request.mode,
        ),
    )
    request = apply_exhaustion_to_roll_request(
        actor,
        request,
        ExhaustionRollKind.SAVING_THROW,
    )
    inspiration = next(
        (
            effect
            for effect in active_combat_effects
            if effect.actor_id == str(actor.id)
            and effect.kind == "bardic_inspiration"
        ),
        None,
    )
    bless = next(
        (
            effect
            for effect in active_combat_effects
            if effect.actor_id == str(actor.id)
            and effect.kind in {
                "bless_roll_bonus",
                "resistance_roll_bonus",
            }
        ),
        None,
    )
    return {
        "condition": condition_state.condition.value,
        "label": condition_label(condition_state.condition),
        "ability": ability,
        "dc": condition_state.save_dc,
        "timing": condition_state.save_timing.value if condition_state.save_timing is not None else None,
        "source_label": condition_state.source_label,
        "roll_mode": request.mode.value,
        "instruction": roll_instruction(request).message,
        "bardic_inspiration": (
            {"die_sides": inspiration.value, "label": inspiration.label}
            if inspiration is not None
            else None
        ),
        "bless": (
            {"die_sides": bless.value, "label": bless.label}
            if bless is not None
            else None
        ),
    }


def _hidden_actor_payload(state: CombatState, actor: Actor) -> dict[str, object] | None:
    hidden = next(
        (hidden for hidden in state.hidden_states if hidden.actor_id == str(actor.id)),
        None,
    )
    if hidden is None:
        return None
    return {
        "stealth_total": hidden.stealth_total,
        "hidden_from_actor_ids": list(hidden.hidden_from_actor_ids),
    }


def _status_chip(label: str, *, tone: str = "neutral", title: str = "") -> dict[str, str]:
    return {"label": label, "tone": tone, "title": title}


def _combat_actor_status_chips(
    actor: Actor,
    *,
    actor_effects: list[dict[str, object]],
    concentration: dict[str, object] | None,
    turn_action: TurnActionState | None = None,
    movement_remaining_feet: int | None = None,
) -> list[dict[str, str]]:
    chips: list[dict[str, str]] = []
    if actor.death_saves.dead:
        chips.append(_status_chip("Martwy", tone="danger"))
    elif actor.death_saves.stable and actor.hp <= 0:
        chips.append(_status_chip("Stabilny (0 HP)", tone="ready"))
    elif actor.needs_death_save():
        chips.append(_status_chip("Nieprzytomny", tone="danger"))
        chips.append(
            _status_chip(
                f"Death saves {actor.death_saves.successes}✓ / {actor.death_saves.failures}✗",
                tone="danger",
            )
        )
    elif actor.is_defeated():
        chips.append(_status_chip("Pokonany", tone="danger"))
    if turn_action is not None:
        chips.append(
            _status_chip(
                "Darmowa interakcja dostępna" if turn_action.object_interaction_available else "Darmowa interakcja zużyta",
                tone="ready" if turn_action.object_interaction_available else "spent",
            )
        )
        if turn_action.attack_action_active:
            remaining = max(0, turn_action.attacks_maximum - turn_action.attacks_used)
            chips.append(
                _status_chip(
                    f"Ataki {remaining}/{turn_action.attacks_maximum}",
                    tone="ready" if remaining else "spent",
                    title="Pozostałe ataki w bieżącej akcji Attack.",
                )
            )
        chips.append(
            _status_chip(
                "Akcja zużyta" if turn_action.action_use == ActionUse.ACTION_USED else "Akcja dostępna",
                tone="spent" if turn_action.action_use == ActionUse.ACTION_USED else "ready",
            )
        )
        chips.append(
            _status_chip(
                "Bonus zużyty" if turn_action.bonus_action_use == ActionUse.ACTION_USED else "Bonus dostępny",
                tone="spent" if turn_action.bonus_action_use == ActionUse.ACTION_USED else "ready",
            )
        )
        chips.append(
            _status_chip(
                "Reakcja dostępna" if turn_action.reaction_available else "Reakcja zużyta",
                tone="ready" if turn_action.reaction_available else "spent",
            )
        )
        if movement_remaining_feet is not None:
            chips.append(_status_chip(f"Ruch {movement_remaining_feet} ft", tone="movement"))
    if concentration is not None:
        chips.append(
            _status_chip(
                f"Koncentracja: {concentration.get('label', '-')}",
                tone="magic",
                title=str(concentration.get("expires", "")),
            )
        )
    for effect in actor_effects:
        label = str(effect.get("label") or effect.get("kind") or "Efekt")
        value = str(effect.get("value_label") or "")
        chip_label = f"{label}: {value}" if value else label
        chips.append(_status_chip(chip_label, tone=_effect_chip_tone(str(effect.get("kind", ""))), title=str(effect.get("expires", ""))))
    return chips


def _effect_chip_tone(kind: str) -> str:
    if kind in {"grant_ac_bonus_until_move", "dodge_until_next_turn", "disengage_until_turn_end"}:
        return "defense"
    if kind in {"grant_attack_bonus_while_on_object", "help_attack_advantage", "strength_potion", "concentration_attack_bonus"}:
        return "offense"
    if kind in {"grant_next_attack_penalty"}:
        return "penalty"
    if kind in {"ready_attack"}:
        return "ready"
    return "neutral"


def _actor_by_string_id_from_state(state: CombatState, actor_id: str) -> Actor:
    actor = next((candidate for candidate in state.actors if str(candidate.id) == actor_id), None)
    if actor is None:
        raise ValueError(f"Nieznany aktor walki: {actor_id}.")
    return actor


def _actor_names_from_actors(
    actors: tuple[Actor, ...],
    actor_ids: tuple[str, ...],
) -> tuple[str, ...]:
    names_by_id = {str(actor.id): actor.name for actor in actors}
    return tuple(names_by_id[actor_id] for actor_id in actor_ids if actor_id in names_by_id)


def _pending_concentration_action_payload(
    pending: PendingConcentrationAction,
    state: CombatState,
    active_effects: tuple[ActiveCombatEffect, ...],
    action=None,
) -> dict[str, object]:
    caster = _actor_by_string_id_from_state(state, pending.caster_id)
    selected_targets = tuple(
        actor
        for actor in state.actors
        if str(actor.id) in pending.selected_target_ids
    )
    return {
        "caster": _combat_actor_payload(
            caster,
            active_effects,
        ),
        "action": (
            _combat_action_payload(
                action,
                caster,
                equipment_blocked=flaw_blocks_equipment_use(
                    caster,
                    active_effects,
                ),
            )
            if action is not None
            else None
        ),
        "cast_level": pending.cast_level,
        "casting_minutes": pending.casting_minutes,
        "casting_ready": pending.casting_minutes > 0,
        "prepared_roll_total": pending.prepared_roll_total,
        "maximum_targets": pending.maximum_targets,
        "selected_target_ids": list(pending.selected_target_ids),
        "selection_mode": "area" if pending.legal_positions else "targets",
        "legal_positions": [
            {"col": position.col, "row": position.row}
            for position in pending.legal_positions
        ],
        "anchor": (
            {"col": pending.anchor.col, "row": pending.anchor.row}
            if pending.anchor is not None
            else None
        ),
        "area_positions": [
            {"col": position.col, "row": position.row}
            for position in pending.area_positions
        ],
        "targets": [
            _combat_actor_payload(actor, active_effects)
            for actor in state.actors
            if str(actor.id) in pending.target_ids
        ],
        "weapon_options": (
            [
                {
                    "id": item.id,
                    "name": item.name,
                    "actor_id": str(target.id),
                }
                for target in selected_targets
                for item in target.inventory
                if item.kind == "weapon"
                and not item.magic_effects
                and not item.requires_attunement
                and "magical" not in item.properties
            ]
            if getattr(action, "id", "") == "magic_weapon"
            else []
        ),
    }


def _pending_multi_target_damage_spell_payload(
    pending: PendingMultiTargetDamageSpell,
    state: CombatState,
) -> dict[str, object]:
    actors_by_id = {str(actor.id): actor for actor in state.actors}
    return {
        "action_id": pending.action_id,
        "cast_level": pending.cast_level,
        "projectile_count": pending.projectile_count,
        "selected_count": len(pending.selected_target_ids),
        "selected_target_ids": list(pending.selected_target_ids),
        "selected_targets": [
            {
                "id": target_id,
                "name": actors_by_id[target_id].name,
            }
            for target_id in pending.selected_target_ids
            if target_id in actors_by_id
        ],
        "projectile_attack_roll": pending.projectile_attack_roll,
        "damage_dice_count": pending.damage_dice_count,
        "damage_die_sides": pending.damage_die_sides,
        "targets": [
            {
                "id": target_id,
                "name": actors_by_id[target_id].name,
                "position": [
                    actors_by_id[target_id].position.col,
                    actors_by_id[target_id].position.row,
                ],
            }
            for target_id in pending.legal_target_ids
            if target_id in actors_by_id
        ],
    }


def _pending_concentration_check_payload(
    pending: PendingConcentrationCheck,
    state: CombatState,
    active_effects: tuple[ActiveCombatEffect, ...],
) -> dict[str, object]:
    actor = _actor_by_string_id_from_state(state, pending.actor_id)
    request = apply_exhaustion_to_roll_request(
        actor,
        D20RollRequest(
            modifiers=(
                *saving_throw_roll_modifiers(actor, "constitution"),
                *saving_throw_aura_modifiers(state.actors, actor),
            )
        ),
        ExhaustionRollKind.SAVING_THROW,
    )
    modifiers = request.modifiers
    modifier = sum(item.value for item in modifiers)
    effects = tuple(
        effect for effect in active_effects if effect.id in pending.effect_ids
    )
    return {
        "actor": _combat_actor_payload(actor, active_effects),
        "effect_ids": list(pending.effect_ids),
        "effects": [effect.as_payload() for effect in effects],
        "damage": pending.damage,
        "dc": pending.dc,
        "modifier": modifier,
        "roll_mode": request.mode.value,
        "modifier_components": [_roll_modifier_payload(item) for item in modifiers],
        "instruction": (
            f"{actor.name} otrzymał {pending.damage} obrażeń. "
            f"Rzuć CON save przeciw ST {pending.dc}."
        ),
    }


def _ready_trigger_label(trigger: str) -> str:
    labels = {
        "enemy_moves": "gdy przeciwnik się poruszy",
        "enemy_attacks": "gdy przeciwnik zaatakuje",
        "giant_killer": "po ataku Dużej lub większej istoty",
    }
    return labels.get(trigger, trigger)


def _encode_cast_source_id(
    source_id: str,
    cast_level: int | None,
    metamagic_ids: tuple[str, ...] = (),
) -> str:
    value = source_id if cast_level is None else f"{source_id}@{cast_level}"
    return (
        f"{value}#{','.join(metamagic_ids)}"
        if metamagic_ids
        else value
    )


def _decode_cast_source_id(value: str) -> tuple[str, int | None]:
    source_id, cast_level, _metamagic_ids = _decode_source_selection(value)
    return source_id, cast_level


def _decode_source_selection(value: str) -> tuple[str, int | None, tuple[str, ...]]:
    cast_value, metadata_separator, raw_metamagic = value.partition("#")
    metamagic_ids = (
        tuple(item for item in raw_metamagic.split(",") if item)
        if metadata_separator
        else ()
    )
    source_id, separator, raw_level = cast_value.rpartition("@")
    if separator and raw_level.isdigit():
        return source_id, int(raw_level), metamagic_ids
    return cast_value, None, metamagic_ids


def _validate_selected_cast_level(
    actor: Actor,
    source,
    cast_level: int | None,
) -> None:
    if cast_level is None:
        return
    if source is None:
        raise ValueError("Nieznane źródło czaru.")
    spell_level = int(getattr(source, "spell_level", 0))
    if spell_level <= 0:
        raise ValueError("Cantrip nie używa poziomu slotu.")
    if cast_level not in available_cast_levels(actor, spell_level):
        raise ValueError(f"Slot poziomu {cast_level} nie jest dostępny dla tego czaru.")


def _attack_source_payload(
    source,
    actor: Actor | None = None,
    *,
    condition_states: tuple[ConditionState, ...] = (),
    active_effects: tuple[ActiveCombatEffect, ...] = (),
) -> dict[str, object]:
    prepared = _source_is_prepared(actor, source)
    unavailable_reason = _attack_source_unavailable_reason(
        actor,
        source,
        condition_states=condition_states,
        active_effects=active_effects,
    )
    attack_kind = effective_attack_kind(source)
    return {
        "id": source.id,
        "name": source.name,
        "source_type": source.source_type.value,
        "attack_kind": attack_kind.value,
        "range_feet": source.range_feet,
        "long_range_feet": source.long_range_feet,
        "reach_feet": melee_reach_feet(source) if attack_kind == AttackKind.MELEE else None,
        "damage_hint": source.damage_hint,
        "damage_fixed": source.damage_fixed,
        "damage_die_sides": source.damage_die_sides,
        "damage_modifier": source.damage_modifier,
        "damage_type": source.damage_type,
        "damage_components": [
            component.as_payload() for component in source.damage_components
        ],
        "ability": source.ability,
        "spell_level": source.spell_level,
        "cast_level": source.cast_level,
        "upcast_damage_dice_per_level": source.upcast_damage_dice_per_level,
        "cantrip_damage_dice_per_tier": source.cantrip_damage_dice_per_tier,
        "available_cast_levels": (
            list(available_cast_levels(actor, source.spell_level))
            if actor is not None
            else []
        ),
        "casting_kind": source.casting_kind.value,
        "action_cost": source.action_cost.value,
        "prepared": prepared,
        "available": unavailable_reason is None,
        "unavailable_reason": unavailable_reason,
        "source_item_id": source.source_item_id,
        "resource_label": _source_resource_label(source, actor),
        "resource_pool_id": source.resource_pool_id,
        "resource_cost": source.resource_cost,
        "metamagic_ids": list(source.metamagic_ids),
        "tabletop_riders": list(source.tabletop_riders),
        "metamagic_options": (
            [
                {
                    "id": option.id,
                    "name": option.name,
                    "sorcery_point_cost": option.sorcery_point_cost,
                }
                for option in metamagic_options_for_source(actor, source)
            ]
            if actor is not None
            else []
        ),
        "ammunition_type": source.ammunition_type,
        "ammunition_remaining": (
            ammunition_quantity(actor, source.ammunition_type)
            if actor is not None and source.ammunition_type is not None
            else None
        ),
        "loading": source.loading,
        "heavy": source.heavy,
        "weapon_special_rule": (
            source.weapon_special_rule.value
            if source.weapon_special_rule is not None
            else None
        ),
        "area": _spell_area_payload(source.area),
        "save_ability": source.save_ability,
        "save_dc": source.save_dc,
        "save_damage_on_success": source.save_damage_on_success,
        "mechanic": action_mechanic_payload(attack_mechanic_from_source(source)),
    }


def _healing_source_payload(
    source: HealingSource,
    actor: Actor | None = None,
    *,
    condition_states: tuple[ConditionState, ...] = (),
    active_effects: tuple[ActiveCombatEffect, ...] = (),
) -> dict[str, object]:
    prepared = _source_is_prepared(actor, source)
    return {
        "id": source.id,
        "name": source.name,
        "source_type": source.source_type.value,
        "range_feet": source.range_feet,
        "healing_hint": source.healing_hint,
        "healing_fixed": source.healing_fixed,
        "healing_die_sides": source.healing_die_sides,
        "healing_dice_count": source.healing_dice_count,
        "healing_modifier": source.healing_modifier,
        "spell_level": source.spell_level,
        "cast_level": source.cast_level,
        "upcast_healing_dice_per_level": source.upcast_healing_dice_per_level,
        "available_cast_levels": (
            list(available_cast_levels(actor, source.spell_level))
            if actor is not None
            else []
        ),
        "casting_kind": source.casting_kind.value,
        "action_cost": source.action_cost.value,
        "prepared": prepared,
        "available": prepared and (
            actor is None
            or can_consume_spell_resource(
                actor,
                source.spell_level,
                getattr(source, "cast_level", None),
                source.id,
            )
        ),
        "unavailable_reason": _spell_source_unavailable_reason(
            actor,
            source,
            condition_states=condition_states,
            active_effects=active_effects,
        ),
        "resource_label": _source_resource_label(source, actor),
        "resource_pool_id": source.resource_pool_id,
        "resource_cost": source.resource_cost,
        "metamagic_ids": list(source.metamagic_ids),
        "metamagic_options": (
            [
                {
                    "id": option.id,
                    "name": option.name,
                    "sorcery_point_cost": option.sorcery_point_cost,
                }
                for option in metamagic_options_for_source(actor, source)
            ]
            if actor is not None
            else []
        ),
        "mechanic": action_mechanic_payload(healing_mechanic_from_source(source)),
    }


def _source_resource_label(source, actor: Actor | None = None) -> str:
    resource_pool_id = getattr(source, "resource_pool_id", None)
    if resource_pool_id is not None:
        pool = actor_resource_pool(actor, resource_pool_id) if actor is not None else None
        if pool is not None:
            recharge = (
                f", Recharge {pool.recharge.minimum_roll}–{pool.recharge.die_sides}"
                if pool.recharge is not None
                else ""
            )
            return f"{pool.label} {pool.current}/{pool.maximum}{recharge}"
        return f"zasób: {resource_pool_id}"
    ammunition_type = getattr(source, "ammunition_type", None)
    if ammunition_type is not None:
        quantity = ammunition_quantity(actor, ammunition_type) if actor is not None else 0
        return f"amunicja {ammunition_type}: {quantity}"
    casting_kind = getattr(source, "casting_kind", None)
    casting_value = getattr(casting_kind, "value", str(casting_kind or "none"))
    if casting_value == "cantrip":
        return "cantrip"
    spell_level = int(
        getattr(source, "cast_level", None)
        or getattr(source, "spell_level", 0)
        or 0
    )
    if casting_value == "leveled" or spell_level > 0:
        return f"slot {spell_level}. poziomu"
    return ""


def _source_is_prepared(actor: Actor | None, source) -> bool:
    if actor is None:
        return bool(getattr(source, "prepared", True))
    source_id = str(source.id)
    if any(
        profile.kind.value in {"known", "innate", "at_will"}
        and source_id in profile.spell_ids
        for profile in actor.spell_access
    ):
        return True
    casting_kind = getattr(source, "casting_kind", None)
    casting_value = getattr(casting_kind, "value", None)
    if casting_value is None:
        casting_value = (
            "leveled" if int(getattr(source, "spell_level", 0) or 0) > 0 else "none"
        )
    return spell_is_prepared(
        actor.spell_preparation,
        source_id,
        casting_kind=casting_value,
        legacy_prepared=bool(getattr(source, "prepared", True)),
    )


def _spell_source_unavailable_reason(
    actor: Actor | None,
    source,
    *,
    condition_states: tuple[ConditionState, ...] = (),
    active_effects: tuple[ActiveCombatEffect, ...] = (),
) -> str | None:
    if not _source_is_prepared(actor, source):
        return "Czar nie został przygotowany."
    if actor is not None and not can_consume_spell_resource(
        actor,
        int(getattr(source, "spell_level", 0)),
        getattr(source, "cast_level", None),
        str(getattr(source, "id", "")),
    ):
        return "Brak dostępnego slotu albo użycia wrodzonego czaru."
    if actor is not None:
        cast_validation = actor_spell_cast_validation(
            actor,
            str(source.id),
            cast_level=getattr(source, "cast_level", None),
            condition_states=condition_states,
            active_effects=active_effects,
        )
        if cast_validation is not None and not cast_validation.valid:
            return " ".join(cast_validation.errors)
    return None


def _spell_preparation_actor_payload(
    actor: Actor,
    *,
    include_spell_details: bool,
) -> dict[str, object]:
    profile = actor.spell_preparation
    if profile is None:
        raise ValueError("Postać nie posiada profilu przygotowywania czarów.")
    payload = {
        "actor_id": str(actor.id),
        "actor_name": actor.name,
        **profile.as_payload(),
    }
    if not include_spell_details:
        return payload
    compiled = compile_actor_combat_content(actor)
    attack_by_id = {source.id: source for source in compiled.attack_sources}
    healing_by_id = {source.id: source for source in compiled.healing_sources}
    action_by_id = {action.id: action for action in compiled.combat_actions}
    spell_by_id = {spell.id: spell for spell in actor.spells}
    payload["spells"] = [
        {
            **entry,
            **_spell_preparation_description_payload(
                actor,
                spell_by_id[str(entry["id"])],
                attack_source=attack_by_id.get(str(entry["id"])),
                healing_source=healing_by_id.get(str(entry["id"])),
                combat_action=action_by_id.get(str(entry["id"])),
            ),
        }
        for entry in payload["spells"]
        if str(entry["id"]) in spell_by_id
    ]
    return payload


def _spell_preparation_description_payload(
    actor: Actor,
    spell,
    *,
    attack_source=None,
    healing_source=None,
    combat_action=None,
) -> dict[str, object]:
    casting_label = {
        "action": "akcja",
        "bonus_action": "akcja dodatkowa",
        "reaction": "reakcja",
        "minute": "1 minuta",
        "ten_minutes": "10 minut",
        "hour": "1 godzina",
    }.get(spell.casting_time.value, spell.casting_time.value)
    range_label = {
        "self": "na siebie",
        "touch": "dotyk",
        "sight": "wzrok",
        "unlimited": "bez ograniczenia",
    }.get(
        spell.range.kind.value,
        f"{spell.range.feet} ft"
        if spell.range.feet
        else spell.range.kind.value,
    )
    duration_label = {
        "instantaneous": "natychmiastowy",
        "round": f"{spell.duration.amount} runda",
        "minute": f"{spell.duration.amount} minuta",
        "ten_minutes": "10 minut",
        "hour": f"{spell.duration.amount} godzina",
        "eight_hours": "8 godzin",
        "twenty_four_hours": "24 godziny",
        "ten_days": "10 dni",
        "until_dispelled": "do rozproszenia",
    }.get(spell.duration.kind.value, spell.duration.kind.value)
    components = [
        label
        for enabled, label in (
            (spell.components.verbal, "W"),
            (spell.components.somatic, "S"),
            (bool(spell.components.materials), "M"),
        )
        if enabled
    ]
    effect_summary = _spell_effect_summary_pl(
        actor,
        spell,
        attack_source=attack_source,
        healing_source=healing_source,
        combat_action=combat_action,
    )
    concentration = " Wymaga koncentracji." if spell.concentration else ""
    ritual = " Można rzucić jako rytuał." if spell.ritual else ""
    mechanics = (
        f"Rzucanie: {casting_label}; zasięg: {range_label}; "
        f"komponenty: {', '.join(components) or 'brak'}; "
        f"czas trwania: {duration_label}.{concentration}{ritual} "
        f"{effect_summary}"
    )
    flavor_by_effect = {
        "attack": "Energia zaklęcia pomyka ku celowi i uderza z magiczną siłą.",
        "healing": "Magia splata rany i przywraca siły wybranemu stworzeniu.",
        "combat_action": "Zaklęcie zmienia układ sił na polu walki.",
        "assisted": "Zaklęcie nagina warunki sceny zgodnie z wolą czarującego.",
        "exploration": "Subtelna magia odsłania lub przekształca element świata.",
    }
    return {
        "school": spell.school.value,
        "casting_time": spell.casting_time.value,
        "range": {
            "kind": spell.range.kind.value,
            "feet": spell.range.feet,
        },
        "duration": {
            "kind": spell.duration.kind.value,
            "amount": spell.duration.amount,
        },
        "concentration": spell.concentration,
        "ritual": spell.ritual,
        "flavor_description": flavor_by_effect.get(
            spell.effect_kind,
            "Magia wywołuje opisany efekt w świecie gry.",
        ),
        "mechanical_description": mechanics,
    }


def _spell_effect_summary_pl(
    actor: Actor,
    spell,
    *,
    attack_source=None,
    healing_source=None,
    combat_action=None,
) -> str:
    if attack_source is not None:
        if attack_source.save_ability:
            opening = (
                f"Cel wykonuje rzut obronny na "
                f"{_ability_label_pl(attack_source.save_ability)} przeciw ST "
                f"{attack_source.save_dc or actor.spell_save_dc}."
            )
        else:
            attack_label = (
                "dystansowy"
                if attack_source.attack_kind == AttackKind.RANGED
                else "wręcz"
            )
            opening = f"Wykonujesz {attack_label} atak czarem."
        result = f" Przy trafieniu lub nieudanym rzucie zadaje {attack_source.damage_hint}."
        rider = (
            " Następny atak przeciw celowi ma przewagę."
            if attack_source.on_hit_effect_kind == "guiding_bolt_mark"
            else ""
        )
        tabletop = (
            f" Dodatkowo przy stole: {' '.join(attack_source.tabletop_riders)}"
            if attack_source.tabletop_riders
            else ""
        )
        return f"{opening}{result}{rider}{tabletop}"
    if healing_source is not None:
        exclusions = (
            f" Nie działa na: {', '.join(healing_source.excluded_creature_types)}."
            if healing_source.excluded_creature_types
            else ""
        )
        return (
            f"Wybrany legalny cel odzyskuje {healing_source.healing_hint} PW."
            f"{exclusions}"
        )
    if combat_action is not None:
        if combat_action.action_type == "multi_target_damage":
            projectile_count = int(combat_action.projectile_count)
            damage = (
                f"1k{combat_action.damage_die_sides}"
                f"{combat_action.damage_modifier:+d}"
            )
            return (
                f"Tworzysz {projectile_count} pociski, rozdzielasz je między "
                f"legalne cele, a każdy automatycznie zadaje {damage} "
                f"obrażeń typu {combat_action.damage_type}. "
                "Wyższy slot dodaje kolejne pociski."
            )
        if combat_action.action_type == "reaction_ac_bonus":
            return (
                f"Po trafieniu reakcją zyskujesz +{combat_action.value} KP "
                "do początku swojej następnej tury; może to zmienić trafienie w pudło."
            )
        if combat_action.instructions:
            return combat_action.instructions
        return (
            f"Resolver walki: {combat_action.action_type.replace('_', ' ')}. "
            "Interfejs prowadzi przez legalne cele, zasób i wymagane rzuty."
        )
    if spell.effect_kind == "exploration":
        return (
            "Czar działa w eksploracji. Runtime sprawdza legalny cel, komponenty, "
            "slot oraz przypisany efekt lub flagę sceny."
        )
    return (
        "Czar ma kontrakt wspomagany: runtime rozlicza legalność, koszt i czas, "
        "a opisany efekt rozstrzyga odpowiedni resolver lub jawna procedura przy stole."
    )


def _spell_payload(actor: Actor, spell) -> dict[str, object]:
    from dnd_board_game.character_creation import (
        AssistedSpellFamily,
        assisted_spell_plan,
    )

    validation = actor_spell_cast_validation(actor, spell.id)
    plan = assisted_spell_plan(spell.id)
    exploration_castable = (
        spell.effect_kind == "exploration"
        or spell.id in {
            "pass_without_trace",
            "protection_from_poison",
            "see_invisibility",
        }
        or (
        plan is not None
        and (
            plan.family
            in {
                AssistedSpellFamily.EXPLORATION,
                AssistedSpellFamily.NARRATIVE,
            }
            or spell.id
            in {
                "animal_friendship",
                "calm_emotions",
                "charm_person",
                "enthrall",
                "suggestion",
            }
        )
        )
    )
    ritual_validation = (
        actor_spell_cast_validation(actor, spell.id, ritual=True)
        if spell.ritual
        else None
    )
    return {
        "id": spell.id,
        "name": spell.name,
        "level": spell.level,
        "school": spell.school.value,
        "casting_time": spell.casting_time.value,
        "range": {"kind": spell.range.kind.value, "feet": spell.range.feet},
        "components": {
            "verbal": spell.components.verbal,
            "somatic": spell.components.somatic,
            "materials": [
                {
                    "item_id": material.item_id,
                    "label": material.label,
                    "minimum_value_cp": material.minimum_value_cp,
                    "consumed": material.consumed,
                    "quantity": material.quantity,
                }
                for material in spell.components.materials
            ],
        },
        "duration": {
            "kind": spell.duration.kind.value,
            "amount": spell.duration.amount,
        },
        "concentration": spell.concentration,
        "ritual": spell.ritual,
        "ritual_casting_minutes": (
            ritual_casting_minutes(spell.casting_time) if spell.ritual else None
        ),
        "effect_kind": spell.effect_kind,
        "scaling": (
            None
            if spell.scaling is None
            else {
                "damage_dice_per_slot_level": spell.scaling.damage_dice_per_slot_level,
                "healing_dice_per_slot_level": spell.scaling.healing_dice_per_slot_level,
                "targets_per_slot_level": spell.scaling.targets_per_slot_level,
            }
        ),
        "available_cast_levels": (
            list(validation.available_cast_levels) if validation is not None else []
        ),
        "castable": validation.valid if validation is not None else False,
        "exploration_castable": exploration_castable,
        "cast_flag": f"cast_{spell.id}" if exploration_castable else "",
        "unavailable_reasons": (
            list(validation.errors) if validation is not None else []
        ),
        "ritual_castable": (
            ritual_validation.valid if ritual_validation is not None else False
        ),
        "ritual_unavailable_reasons": (
            list(ritual_validation.errors) if ritual_validation is not None else []
        ),
    }


def _timed_magic_effect_payload(
    effect: TimedMagicEffect,
    *,
    elapsed_minutes: int,
) -> dict[str, object]:
    if effect.expires_at_minute is None:
        expiration_label = "Do rozproszenia"
    else:
        remaining = max(0, effect.expires_at_minute - elapsed_minutes)
        expiration_label = f"Pozostało {remaining} min"
    return {
        "id": effect.id,
        "actor_id": effect.actor_id,
        "kind": "exploration_magic",
        "label": effect.label,
        "object_id": f"spell:{effect.spell_id}",
        "value": 0,
        "value_label": "Aktywny efekt magiczny",
        "expires": expiration_label,
        "summary": f"{effect.label}: {expiration_label.lower()}.",
        "source": {
            "type": "spell",
            "id": effect.spell_id,
            "label": effect.label,
        },
        "duration": "timed_minutes",
        "stacking": "replace",
        "stacking_key": effect.flag_key,
        "additional_expirations": [],
    }


def _attack_source_unavailable_reason(
    actor: Actor | None,
    source,
    *,
    condition_states: tuple[ConditionState, ...] = (),
    active_effects: tuple[ActiveCombatEffect, ...] = (),
) -> str | None:
    from dnd_board_game.inventory import item_power_available

    spell_reason = _spell_source_unavailable_reason(
        actor,
        source,
        condition_states=condition_states,
        active_effects=active_effects,
    )
    if spell_reason is not None:
        return spell_reason
    source_item_id = getattr(source, "source_item_id", None)
    if actor is not None and source_item_id is not None:
        item = _inventory_item_for_attack_source(actor, source_item_id)
        if item is not None and item.requires_attunement and not item.attuned:
            return "Przedmiot wymaga dostrojenia podczas krótkiego odpoczynku."
        if item is None or not item_power_available(item) or not item.equipped:
            return "Broń leży na polu lub pozostaje niewyposażona w ekwipunku."
    ammunition_type = getattr(source, "ammunition_type", None)
    if actor is not None and ammunition_type is not None and not has_ammunition(
        actor,
        ammunition_type,
    ):
        return f"Brak amunicji typu {ammunition_type}."
    resource_pool_id = getattr(source, "resource_pool_id", None)
    resource_cost = int(getattr(source, "resource_cost", 1))
    if actor is not None and resource_pool_id is not None and not can_spend_actor_resource(
        actor,
        resource_pool_id,
        resource_cost,
    ):
        pool = actor_resource_pool(actor, resource_pool_id)
        label = pool.label if pool is not None else resource_pool_id
        return f"Brak dostępnych użyć: {label}."
    return None


def _source_action_economy_available(state: CombatState, source: object) -> bool:
    cost = getattr(source, "action_cost", ActionEconomyCost.ACTION)
    if (
        cost == ActionEconomyCost.ACTION
        and state.turn_action.action_use != ActionUse.ACTION_AVAILABLE
    ):
        return False
    if (
        cost == ActionEconomyCost.BONUS_ACTION
        and state.turn_action.bonus_action_use != ActionUse.ACTION_AVAILABLE
    ):
        return False
    spell_level = int(getattr(source, "spell_level", 0))
    if (
        cost == ActionEconomyCost.BONUS_ACTION
        and state.turn_action.leveled_action_spell_cast
    ):
        return False
    if (
        cost == ActionEconomyCost.ACTION
        and spell_level > 0
        and state.turn_action.bonus_action_spell_cast
    ):
        return False
    return True


def _inventory_item_for_attack_source(actor: Actor, source_item_id: str):
    matches = tuple(
        item
        for item in actor.inventory
        if item.id == source_item_id or item.source_ref == source_item_id
    )
    return next((item for item in matches if item.equipped and item.available), matches[0] if matches else None)


def _encounter_attack_sources(
    encounter: LoadedEncounter,
    actor: Actor,
    *,
    reserved_hands: int = 0,
) -> tuple:
    sources = list(encounter.attack_source_options_by_actor.get(actor.id, ()))
    known_ids = {source.id for source in sources}
    for item in actor.inventory:
        if item.kind != "weapon":
            continue
        source_keys = tuple(dict.fromkeys(key for key in (item.id, item.source_ref) if key))
        for key in source_keys:
            for source in encounter.weapon_attack_sources_by_item_id.get(key, ()):
                if source.id in known_ids:
                    continue
                sources.append(source)
                known_ids.add(source.id)
    species_sources = tuple(
        source
        for source in (breath_weapon_attack_source(actor),)
        if source is not None
    )
    bound_sources = (
        *(attack_source_for_actor(source, actor) for source in sources),
        *species_sources,
        unarmed_strike_source(actor),
    )
    return attack_sources_with_versatile_variants(
        actor,
        bound_sources,
        reserved_hands=reserved_hands,
    )


