def _attack_context_category(source) -> CombatMenuCategory:
    source_type = getattr(getattr(source, "source_type", None), "value", "")
    if source_type == "spell":
        return CombatMenuCategory.MAGIC
    if source_type == "item":
        return CombatMenuCategory.ITEM
    return CombatMenuCategory.ATTACK


def _combat_action_payload(
    action,
    actor: Actor | None = None,
    *,
    equipment_blocked: bool = False,
    condition_states: tuple[ConditionState, ...] = (),
    active_effects: tuple[ActiveCombatEffect, ...] = (),
) -> dict[str, object]:
    from dnd_board_game.inventory import item_power_available

    quantity = _combat_action_item_quantity(action, actor)
    item = _combat_action_item(action, actor)
    charge_cost = int(getattr(action, "charge_cost", 0))
    charges_current = item.charges_current if item is not None else None
    charges_maximum = item.charges_maximum if item is not None else None
    prepared = _source_is_prepared(actor, action)
    has_spell_resource = actor is None or can_consume_spell_resource(
        actor,
        action.spell_level,
        spell_id=action.id,
    )
    has_item_resource = (
        charges_current is not None and charges_current >= charge_cost
        if charge_cost > 0
        else quantity is None or quantity > 0
    )
    item_power_ready = item is None or item_power_available(item)
    spell_validation = (
        actor_spell_cast_validation(
            actor,
            action.id,
            condition_states=condition_states,
            active_effects=active_effects,
        )
        if actor is not None and action.spell_level > 0
        else None
    )
    item_blocked = equipment_blocked and action.source_item_id is not None
    available = (
        prepared
        and has_spell_resource
        and has_item_resource
        and item_power_ready
        and (spell_validation is None or spell_validation.valid)
        and not item_blocked
    )
    return {
        "id": action.id,
        "name": action.name,
        "action_type": action.action_type,
        "label": action.label,
        "value": action.value,
        "ability": action.ability,
        "duration": action.duration,
        "target_faction": action.target_faction,
        "target_count": int(getattr(action, "target_count", 1)),
        "upcast_targets_per_level": int(
            getattr(action, "upcast_targets_per_level", 0)
        ),
        "spell_level": action.spell_level,
        "casting_kind": action.casting_kind.value,
        "prepared": prepared,
        "concentration": action.concentration,
        "source_item_id": action.source_item_id,
        "range_feet": action.range_feet,
        "area": (
            {
                "shape": action.area.shape.value,
                "radius_feet": action.area.radius_feet,
                "length_feet": action.area.length_feet,
                "width_feet": action.area.width_feet,
                "target_mode": action.area.target_mode.value,
            }
            if getattr(action, "area", None) is not None
            else None
        ),
        "effect_kind": action.effect_kind,
        "action_cost": action.action_cost.value,
        "casting_time": action.casting_time.value,
        "instructions": str(getattr(action, "instructions", "")),
        "resolution_mode": str(getattr(action, "resolution_mode", "automatic")),
        "board_relevance": str(getattr(action, "board_relevance", "direct")),
        "mechanic_family": str(getattr(action, "mechanic_family", "")),
        "resolver_id": str(getattr(action, "resolver_id", "")),
        "cast_flag": str(getattr(action, "cast_flag", "")),
        "projectile_count": int(getattr(action, "projectile_count", 0)),
        "upcast_projectiles_per_level": int(
            getattr(action, "upcast_projectiles_per_level", 0)
        ),
        "damage_die_sides": int(getattr(action, "damage_die_sides", 0)),
        "damage_modifier": int(getattr(action, "damage_modifier", 0)),
        "damage_type": str(getattr(action, "damage_type", "")),
        "allowed_creature_types": list(
            getattr(action, "allowed_creature_types", ())
        ),
        "minimum_intelligence": getattr(action, "minimum_intelligence", None),
        "effect_options": list(getattr(action, "effect_options", ())),
        "hit_point_pool_dice_count": int(
            getattr(action, "hit_point_pool_dice_count", 0)
        ),
        "upcast_hit_point_pool_dice_per_level": int(
            getattr(action, "upcast_hit_point_pool_dice_per_level", 0)
        ),
        "excluded_creature_types": list(
            getattr(action, "excluded_creature_types", ())
        ),
        "ongoing_damage_dice_count": int(
            getattr(action, "ongoing_damage_dice_count", 0)
        ),
        "save_damage_on_success": str(
            getattr(action, "save_damage_on_success", "none")
        ),
        "damage_on_cast": bool(getattr(action, "damage_on_cast", False)),
        "action_cost_label": action_economy_cost_label(action.action_cost),
        "source_item_quantity": quantity,
        "charge_cost": charge_cost,
        "source_item_charges_current": charges_current,
        "source_item_charges_maximum": charges_maximum,
        "available": available,
        "available_cast_levels": (
            list(spell_validation.available_cast_levels)
            if spell_validation is not None
            else [0] if action.spell_level == 0 else []
        ),
        "unavailable_reason": (
            "Skaza Brakki: podczas Szału nie może korzystać z ekwipunku."
            if item_blocked
            else _combat_action_unavailable_reason(
                action,
                actor,
                quantity=quantity,
                charges_current=charges_current,
                condition_states=condition_states,
                active_effects=active_effects,
            )
        ),
        "resource_label": (
            f"ładunki {charges_current}/{charges_maximum}"
            if charges_maximum is not None
            else _source_resource_label(action, actor)
        ),
        "metamagic_ids": list(getattr(action, "metamagic_ids", ())),
        "metamagic_options": (
            [
                {
                    "id": option.id,
                    "name": option.name,
                    "sorcery_point_cost": option.sorcery_point_cost,
                }
                for option in metamagic_options_for_combat_action(actor, action)
            ]
            if actor is not None and action.action_type == "assisted_spell"
            else []
        ),
        "mechanic": action_mechanic_payload(combat_action_mechanic_from_definition(action)),
    }


def _combat_action_item_quantity(action, actor: Actor | None) -> int | None:
    if actor is None or action.source_item_id is None:
        return None
    item = next((candidate for candidate in actor.inventory if candidate.id == action.source_item_id), None)
    return item.quantity if item is not None else 0


def _combat_action_item(action: object, actor: Actor | None) -> InventoryItem | None:
    if actor is None or action.source_item_id is None:
        return None
    return next(
        (
            candidate
            for candidate in actor.inventory
            if candidate.id == action.source_item_id
            or candidate.source_ref == action.source_item_id
        ),
        None,
    )


def _combat_action_unavailable_reason(
    action,
    actor: Actor | None,
    *,
    quantity: int | None,
    charges_current: int | None,
    condition_states: tuple[ConditionState, ...] = (),
    active_effects: tuple[ActiveCombatEffect, ...] = (),
) -> str | None:
    spell_reason = _spell_source_unavailable_reason(
        actor,
        action,
        condition_states=condition_states,
        active_effects=active_effects,
    )
    if spell_reason is not None:
        return spell_reason
    item = _combat_action_item(action, actor)
    if item is not None and item.requires_attunement and not item.attuned:
        return "Przedmiot wymaga dostrojenia podczas krótkiego odpoczynku."
    charge_cost = int(getattr(action, "charge_cost", 0))
    if charge_cost > 0 and (charges_current is None or charges_current < charge_cost):
        return "Brak wystarczającej liczby ładunków."
    if charge_cost == 0 and quantity is not None and quantity <= 0:
        return "Brak wymaganego przedmiotu."
    return None


def _pending_player_attack_payload(
    pending: PendingPlayerAttack | None,
    state: CombatState,
    encounter: LoadedEncounter | None,
    active_combat_effects: tuple[ActiveCombatEffect, ...] = (),
) -> dict[str, object] | None:
    if pending is None or encounter is None:
        return None
    attacker = next((actor for actor in state.actors if str(actor.id) == pending.attacker_id), None)
    target = next((actor for actor in state.actors if str(actor.id) == pending.target_id), None)
    if attacker is None or target is None:
        return None
    sources = _encounter_attack_sources(
        encounter,
        attacker,
        reserved_hands=len(grappled_actor_ids(state.condition_states, str(attacker.id))),
    )
    source = next((candidate for candidate in sources if candidate.id == pending.source_id), None) or (
        sources[0] if sources else None
    )
    if source is None:
        return None
    if pending.cast_level is not None:
        source = attack_source_at_cast_level(source, pending.cast_level)
    if pending.metamagic_ids:
        source = apply_metamagic_to_source(
            attacker,
            source,
            pending.metamagic_ids,
            validate_resources=False,
        )
    if pending.two_weapon_bonus:
        source = two_weapon_bonus_attack_source(attacker, source)
    source = attack_source_with_target_combat_effects(attacker, target, source, active_combat_effects)
    source = attack_source_with_hidden_advantage(
        source,
        is_hidden_from(state.hidden_states, str(attacker.id), str(target.id)),
    )
    positioning = AttackPositioning(
        cover_level=CoverLevel(pending.cover_level),
        cover_bonus=pending.cover_bonus,
        cover_sources=pending.cover_sources,
        ranged_threat_actor_ids=pending.ranged_threat_actor_ids,
        flanking_ally_ids=pending.flanking_ally_ids,
    )
    source = attack_source_with_positioning(source, positioning)
    source = attack_source_with_prone(source, state.condition_states, attacker, target)
    if pending.sneak_attack:
        source = plan_sneak_attack(
            state=state,
            active_effects=active_combat_effects,
            attacker=attacker,
            target=target,
            source=source,
            roll_mode=source.attack_roll_request.mode,
        ).source
    if pending.colossus_slayer and source.damage_components:
        component = colossus_slayer_damage(
            attacker,
            target,
            damage_type=source.damage_components[0].damage_type,
        )
        if component is not None:
            source = replace(
                source,
                damage_components=(*source.damage_components, component),
                damage_hint=f"{source.damage_hint} + {component.hint()}",
            )
    if pending.divine_smite_slot_level:
        smite = divine_smite_damage(
            attacker,
            slot_level=pending.divine_smite_slot_level,
            target_creature_type=target.creature_type,
        )
        source = replace(
            source,
            damage_components=(*source.damage_components, smite),
            damage_hint=f"{source.damage_hint} + {smite.hint()}",
        )
    divine_smite_levels = (
        available_cast_levels(attacker, 1)
        if pending.stage == "damage_roll"
        and actor_has_feature(attacker, "divine_smite")
        and source.source_type == AttackSourceType.WEAPON
        and source.attack_kind == AttackKind.MELEE
        else ()
    )
    instruction = roll_instruction(source.attack_roll_request)
    ranged_threats = tuple(
        candidate
        for candidate in state.actors
        if str(candidate.id) in pending.ranged_threat_actor_ids
    )
    is_acid_splash = source.id == "acid_splash"
    twinned_targets = (
        tuple(
            candidate
            for candidate in start_attack_action(
                encounter.board,
                attacker,
                state.actors,
                source,
                state.hidden_states,
            ).legal_targets
            if candidate.id != pending.target_id
            and (
                not is_acid_splash
                or grid_distance_feet(target.position, candidate.position) <= 5
            )
        )
        if (
            pending.stage == "confirm_attack"
            and (
                "metamagic_twinned" in pending.metamagic_ids
                or is_acid_splash
            )
        )
        else ()
    )
    return {
        "stage": pending.stage,
        "two_weapon_bonus": pending.two_weapon_bonus,
        "sneak_attack": pending.sneak_attack,
        "colossus_slayer": pending.colossus_slayer,
        "divine_smite_slot_level": pending.divine_smite_slot_level,
        "divine_smite_available_levels": list(divine_smite_levels),
        "attacker": _combat_actor_payload(attacker, active_combat_effects),
        "target": _combat_actor_payload(target, active_combat_effects),
        "source": _attack_source_payload(source, attacker),
        "attack_instruction": instruction.message,
        "attack_modifier": instruction.breakdown.modifier_total,
        "attack_mode": instruction.mode.value,
        "active_modifiers": [_roll_modifier_payload(modifier) for modifier in instruction.breakdown.active_modifiers],
        "ignored_modifiers": [_roll_modifier_payload(modifier) for modifier in instruction.breakdown.ignored_modifiers],
        "damage_instruction": _damage_roll_instruction(
            source,
            critical=pending.critical,
        ),
        "damage_components": [
            component.as_payload(critical=pending.critical)
            for component in source.damage_components
        ],
        "natural_roll": pending.natural_roll,
        "natural_rolls": list(pending.natural_rolls),
        "total": pending.total,
        "target_ac": combat_armor_class(target, active_combat_effects) + pending.cover_bonus,
        "positioning": {
            "cover_level": pending.cover_level,
            "cover_bonus": pending.cover_bonus,
            "cover_sources": list(pending.cover_sources),
            "ranged_in_melee": bool(pending.ranged_threat_actor_ids),
            "ranged_threat_actor_ids": list(pending.ranged_threat_actor_ids),
            "ranged_threats": [
                {
                    "id": str(candidate.id),
                    "name": candidate.name,
                    "position": [candidate.position.col, candidate.position.row],
                }
                for candidate in ranged_threats
            ],
            "flanking": bool(pending.flanking_ally_ids),
            "flanking_ally_ids": list(pending.flanking_ally_ids),
        },
        "hit": pending.hit,
        "critical": pending.critical,
        "twinned_spell": {
            "available": bool(twinned_targets),
            "label": (
                "Drugi cel Kwasowego rozprysku"
                if is_acid_splash
                else "Twinned Spell"
            ),
            "optional": is_acid_splash,
            "second_attack": pending.twinned_second_attack,
            "selected_target_id": pending.twinned_target_id,
            "eligible_targets": [
                {
                    "id": target.id,
                    "name": target.name,
                    "position": [target.position.col, target.position.row],
                }
                for target in twinned_targets
            ],
        },
        "empowered_spell": {
            "available": (
                pending.stage == "damage_roll"
                and actor_has_feature(attacker, "metamagic_empowered")
                and "metamagic_empowered" not in pending.metamagic_ids
                and any(component.dice is not None for component in source.damage_components)
                and can_spend_actor_resource(attacker, "sorcery_points", 1)
            ),
            "active": "metamagic_empowered" in pending.metamagic_ids,
            "maximum_rerolled_dice": max(
                1,
                ability_modifier(attacker.ability_scores.charisma),
            ),
        },
        "open_hand_technique": (
            {
                "save_dc": open_hand_technique_save_dc(attacker),
                "target_name": target.name,
            }
            if pending.stage == "open_hand_choice"
            else None
        ),
        "repelling_blast": (
            {
                "target_name": target.name,
                "distance_feet": 10,
            }
            if pending.stage == "repelling_blast_choice"
            else None
        ),
        "saving_throws": [save.as_payload() for save in pending.saving_throws],
        "spell_save_dc": source.save_dc or attacker.spell_save_dc,
        "bardic_inspiration": next(
            (
                {
                    "die_sides": effect.value,
                    "label": effect.label,
                }
                for effect in active_combat_effects
                if effect.actor_id == str(attacker.id)
                and effect.kind == "bardic_inspiration"
            ),
            None,
        ),
        "bless": next(
            (
                {
                    "die_sides": effect.value,
                    "label": effect.label,
                }
                for effect in active_combat_effects
                if effect.actor_id == str(attacker.id)
                and effect.kind == "bless_roll_bonus"
            ),
            None,
        ),
        "mirror_image": next(
            (
                {
                    "duplicates": effect.value,
                    "redirect_threshold": {3: 6, 2: 8, 1: 11}.get(
                        effect.value,
                        6,
                    ),
                    "duplicate_ac": (
                        10 + ability_modifier(target.ability_scores.dexterity)
                    ),
                }
                for effect in active_combat_effects
                if effect.actor_id == str(target.id)
                and effect.kind == "mirror_image"
                and effect.value > 0
            ),
            None,
        ),
    }


def _pending_player_healing_payload(
    pending: PendingPlayerHealing | None,
    state: CombatState,
    encounter: LoadedEncounter | None,
) -> dict[str, object] | None:
    if pending is None or encounter is None:
        return None
    healer = next((actor for actor in state.actors if str(actor.id) == pending.healer_id), None)
    target = next((actor for actor in state.actors if str(actor.id) == pending.target_id), None)
    if healer is None or target is None:
        return None
    source = next(
        (candidate for candidate in encounter.healing_sources_by_actor.get(healer.id, ()) if candidate.id == pending.source_id),
        None,
    )
    if source is None:
        return None
    if pending.cast_level is not None:
        source = healing_source_at_cast_level(source, pending.cast_level)
    if pending.metamagic_ids:
        source = apply_metamagic_to_source(
            healer,
            source,
            pending.metamagic_ids,
            validate_resources=False,
        )
    twinned_targets = (
        tuple(
            target
            for target in legal_healing_targets(
                encounter.board,
                healer,
                state.actors,
                source,
            )
            if target.id != pending.target_id
        )
        if "metamagic_twinned" in pending.metamagic_ids
        else ()
    )
    return {
        "stage": pending.stage,
        "healer": _combat_actor_payload(healer),
        "target": _combat_actor_payload(target),
        "source": _healing_source_payload(source, healer),
        "healing_instruction": f"Rzuć {source.healing_hint} i wpisz sumę leczenia.",
        "twinned_spell": {
            "available": bool(twinned_targets),
            "selected_target_id": pending.twinned_target_id,
            "eligible_targets": [
                {
                    "id": target.id,
                    "name": target.name,
                    "position": [target.position.col, target.position.row],
                }
                for target in twinned_targets
            ],
        },
    }


def _pending_area_spell_payload(
    pending: PendingAreaSpell | None,
    state: CombatState,
    encounter: LoadedEncounter | None,
    active_combat_effects: tuple[ActiveCombatEffect, ...] = (),
) -> dict[str, object] | None:
    if pending is None or encounter is None:
        return None
    caster = next((actor for actor in state.actors if str(actor.id) == pending.caster_id), None)
    if caster is None:
        return None
    source = next(
        (
            candidate
            for candidate in _encounter_attack_sources(encounter, caster)
            if candidate.id == pending.source_id
        ),
        None,
    )
    if source is None:
        return None
    if pending.cast_level is not None:
        source = attack_source_at_cast_level(source, pending.cast_level)
    if pending.metamagic_ids:
        source = apply_metamagic_to_source(
            caster,
            source,
            pending.metamagic_ids,
            validate_resources=False,
        )
    spell = next(
        (spell for spell in caster.spells if spell.id == pending.source_id),
        None,
    )
    sculpt_eligible = (
        tuple(
            actor
            for actor in state.actors
            if str(actor.id) in {
                *pending.target_ids,
                *pending.protected_target_ids,
            }
            and actor.faction == caster.faction
            and actor.id != caster.id
        )
        if actor_has_feature(caster, "sculpt_spells")
        and spell is not None
        and spell.school.value == "evocation"
        and pending.stage == "confirm_area"
        else ()
    )
    return {
        "stage": pending.stage,
        "caster": _combat_actor_payload(caster, active_combat_effects),
        "source": _attack_source_payload(source, caster),
        "origin": [pending.origin.col, pending.origin.row],
        "anchor": [pending.anchor.col, pending.anchor.row],
        "area_positions": [[position.col, position.row] for position in pending.area_positions],
        "targets": [
            _combat_actor_payload(actor, active_combat_effects)
            for actor in state.actors
            if str(actor.id) in pending.target_ids
        ],
        "protected_targets": [
            _combat_actor_payload(actor, active_combat_effects)
            for actor in state.actors
            if str(actor.id) in pending.protected_target_ids
        ],
        "careful_targets": [
            _combat_actor_payload(actor, active_combat_effects)
            for actor in state.actors
            if str(actor.id) in pending.careful_target_ids
        ],
        "metamagic": {
            "ids": list(pending.metamagic_ids),
            "careful": {
                "available": (
                    "metamagic_careful" in pending.metamagic_ids
                    and pending.stage == "confirm_area"
                ),
                "maximum_targets": max(
                    1,
                    ability_modifier(caster.ability_scores.charisma),
                ),
                "selected_target_ids": list(pending.careful_target_ids),
            },
            "heightened": {
                "available": (
                    "metamagic_heightened" in pending.metamagic_ids
                    and pending.stage == "confirm_area"
                ),
                "selected_target_id": pending.heightened_target_id,
            },
        },
        "empowered_spell": {
            "available": (
                pending.stage == "damage_roll"
                and actor_has_feature(caster, "metamagic_empowered")
                and "metamagic_empowered" not in pending.metamagic_ids
                and any(component.dice is not None for component in source.damage_components)
                and can_spend_actor_resource(caster, "sorcery_points", 1)
            ),
            "active": "metamagic_empowered" in pending.metamagic_ids,
            "maximum_rerolled_dice": max(
                1,
                ability_modifier(caster.ability_scores.charisma),
            ),
        },
        "sculpt_spells": {
            "available": bool(sculpt_eligible),
            "maximum_targets": 1 + (pending.cast_level or (spell.level if spell else 0)),
            "eligible_targets": [
                _combat_actor_payload(actor, active_combat_effects)
                for actor in sculpt_eligible
            ],
        },
        "saving_throws": [save.as_payload() for save in pending.saving_throws],
        "target_cover": [
            {
                "actor_id": actor_id,
                "cover_level": positioning.cover_level.value,
                "cover_bonus": positioning.cover_bonus,
                "cover_sources": list(positioning.cover_sources),
            }
            for actor_id, positioning in pending.target_positioning
        ],
        "spell_save_dc": source.save_dc or caster.spell_save_dc,
        "damage_instruction": _damage_roll_instruction(source),
        "damage_components": [
            component.as_payload()
            for component in source.damage_components
        ],
    }


def _pending_enemy_opportunity_attack_payload(
    pending: PendingEnemyOpportunityAttack | None,
    state: CombatState,
    encounter: LoadedEncounter | None,
    active_combat_effects: tuple[ActiveCombatEffect, ...] = (),
) -> dict[str, object] | None:
    if pending is None or encounter is None:
        return None
    attacker = next((actor for actor in state.actors if str(actor.id) == pending.attacker_id), None)
    target = next((actor for actor in state.actors if str(actor.id) == pending.target_id), None)
    if attacker is None or target is None:
        return None
    source = encounter.attack_sources_by_actor.get(attacker.id)
    if source is None:
        return None
    source = attack_source_with_target_combat_effects(attacker, target, source, active_combat_effects)
    instruction = roll_instruction(source.attack_roll_request)
    threats = [
        _combat_actor_payload(actor, active_combat_effects)
        for actor in state.actors
        if str(actor.id) in pending.threat_actor_ids
    ]
    return {
        "stage": pending.stage,
        "attacker": _combat_actor_payload(attacker, active_combat_effects),
        "target": _combat_actor_payload(target, active_combat_effects),
        "threats": threats,
        "current_index": pending.current_index,
        "source": _attack_source_payload(source, attacker),
        "attack_instruction": instruction.message,
        "attack_modifier": instruction.breakdown.modifier_total,
        "attack_mode": instruction.mode.value,
        "active_modifiers": [_roll_modifier_payload(modifier) for modifier in instruction.breakdown.active_modifiers],
        "ignored_modifiers": [_roll_modifier_payload(modifier) for modifier in instruction.breakdown.ignored_modifiers],
        "damage_instruction": _damage_roll_instruction(
            source,
            critical=pending.critical,
        ),
        "damage_components": [
            component.as_payload(critical=pending.critical)
            for component in source.damage_components
        ],
        "natural_roll": pending.natural_roll,
        "natural_rolls": list(pending.natural_rolls),
        "total": pending.total,
        "target_ac": target.ac,
        "hit": pending.hit,
        "critical": pending.critical,
    }


